/* == 01. Fonts ========================================================= */
@font-face {
  font-family: "BBH Bartle";
  src: url("../fonts/BBHBartle-Regular.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

/* == 02. Tokens — light theme ========================================== */
:root {
  --u: calc(100vw / 2560);
  --gut: calc(var(--u) * 60);

  --acc: #d8470e;
  --acc-d: #c23e0b;
  --acc-s: #fde7dc;
  --acc-s2: #fbd5c2;
  --acc-s3: #fff4ee;
  --acc-sh: var(--acc-a24);
  --acc-a03: rgba(216, 71, 14, .03);
  --acc-a04: rgba(216, 71, 14, .04);
  --acc-a06: rgba(216, 71, 14, .06);
  --acc-a07: rgba(216, 71, 14, .07);
  --acc-a08: rgba(216, 71, 14, .08);
  --acc-a10: rgba(216, 71, 14, .1);
  --acc-a12: rgba(216, 71, 14, .12);
  --acc-a14: rgba(216, 71, 14, .14);
  --acc-a16: rgba(216, 71, 14, .16);
  --acc-a18: rgba(216, 71, 14, .18);
  --acc-a20: rgba(216, 71, 14, .2);
  --acc-a24: rgba(216, 71, 14, .24);
  --acc-a25: rgba(216, 71, 14, .25);
  --acc-a30: rgba(216, 71, 14, .3);
  --acc-a35: rgba(216, 71, 14, .35);
  --acc-a40: rgba(216, 71, 14, .4);
  --acc-a45: rgba(216, 71, 14, .45);
  --acc-a50: rgba(216, 71, 14, .5);
  --ok: #2fa36b;

  --bg: #f7f8fa;
  --page: #fdfefe;
  --stage: #f4f5f7;
  --surf: #fff;
  --surf2: #f4f5f7;
  --ink: #111418;
  --ink-h: #2a2e35;
  --on-ink: #fff;
  --on-ink-25: rgba(255, 255, 255, .25);
  --on-ink-55: rgba(255, 255, 255, .55);
  --mute: #8a9099;
  --body: #5f6671;
  --line: rgba(17, 20, 24, .25);
  --line2: rgba(17, 20, 24, .22);
  --line3: rgba(17, 20, 24, .2);
  --chip-line: rgba(17, 20, 24, .22);
  --line-bar: #e3e5e8;
  --hair: rgba(17, 20, 24, .1);
  --ghost: rgba(17, 20, 24, .12);
  --ghost2: rgba(17, 20, 24, .1);
  --tint: var(--acc-a04);
  --tint2: var(--acc-a03);
  --glass: rgba(255, 255, 255, .88);
  --glass9: rgba(255, 255, 255, .9);
  --glass94: rgba(255, 255, 255, .94);
  --glass86: rgba(255, 255, 255, .86);
  --glass80: rgba(255, 255, 255, .8);
  --glass60: rgba(255, 255, 255, .6);
  --glass50: rgba(255, 255, 255, .5);
  --s1: #eceef1;
  --s2: #f5f6f8;
  --av1: #e3e5e9;
  --av2: #f0f1f3;
  --shadow: 0 20px 50px rgba(17, 20, 24, .1);
  --stripes: repeating-linear-gradient(135deg, var(--s1) 0 calc(var(--u) * 14), var(--s2) calc(var(--u) * 14) calc(var(--u) * 28));

  color-scheme: light;
}

/* == 03. Tokens — dark theme =========================================== */
[data-theme="dark"] {
  --bg: #111317;
  --page: #111317;
  --stage: #0f1114;
  --surf: #15171b;
  --surf2: #1b1e23;
  --ink: #f2f3f5;
  --ink-h: #d9dce1;
  --on-ink: #111418;
  --on-ink-25: rgba(17, 20, 24, .25);
  --on-ink-55: rgba(17, 20, 24, .55);
  --mute: #7d838d;
  --body: #a3a9b3;
  --line: rgba(242, 243, 245, .18);
  --line2: rgba(242, 243, 245, .16);
  --line3: rgba(242, 243, 245, .16);
  --chip-line: rgba(242, 243, 245, .2);
  --line-bar: #2a2e35;
  --hair: rgba(242, 243, 245, .1);
  --ghost: rgba(242, 243, 245, .1);
  --ghost2: rgba(242, 243, 245, .08);
  --tint: var(--acc-a07);
  --tint2: var(--acc-a06);
  --glass: rgba(17, 19, 23, .85);
  --glass9: rgba(17, 19, 23, .85);
  --glass94: rgba(20, 22, 27, .9);
  --glass86: rgba(20, 22, 27, .82);
  --glass80: rgba(255, 255, 255, .03);
  --glass60: rgba(22, 24, 29, .6);
  --glass50: rgba(22, 24, 29, .5);
  --s1: #1a1d22;
  --s2: #15171b;
  --av1: #1f2228;
  --av2: #15171b;

  color-scheme: dark;
}

/* == 04. Reset and base ================================================ */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: Geist, Helvetica, Arial, sans-serif;
  font-weight: 300;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1,
h2,
h3,
p,
ul,
ol,
dl,
dd,
figure,
blockquote,
address {
  margin: 0;
  padding: 0;
}

h1,
h2,
h3 {
  font-weight: 300;
}

ul,
ol {
  list-style: none;
}

address {
  font-style: normal;
}

img,
svg {
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover {
  color: var(--acc);
}

button,
input,
select {
  font: inherit;
  color: inherit;
  letter-spacing: inherit;
}

button {
  cursor: pointer;
  background: none;
  border: 0;
  padding: 0;
}

input::placeholder {
  color: var(--mute);
  opacity: 1;
}

:focus-visible {
  outline: 2px solid var(--acc);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.skip {
  position: absolute;
  left: 16px;
  top: -60px;
  z-index: 100;
  padding: 10px 18px;
  border-radius: 20px;
  background: var(--ink);
  color: var(--on-ink);
  font-size: 14px;
}

.skip:focus {
  top: 12px;
}

.acc {
  color: var(--acc);
}

.mute {
  color: var(--mute);
}

.nobr {
  white-space: nowrap;
}

.flip {
  transform: rotate(180deg);
}

/* == 05. Icons ========================================================= */
.ico {
  flex-shrink: 0;
}

.i10 { width: calc(var(--u) * 10); height: calc(var(--u) * 10); }
.i11 { width: calc(var(--u) * 11); height: calc(var(--u) * 11); }
.i12 { width: calc(var(--u) * 12); height: calc(var(--u) * 12); }
.i14 { width: calc(var(--u) * 14); height: calc(var(--u) * 14); }
.i16 { width: calc(var(--u) * 16); height: calc(var(--u) * 16); }
.i18 { width: calc(var(--u) * 18); height: calc(var(--u) * 18); }
.i20 { width: calc(var(--u) * 20); height: calc(var(--u) * 20); }
.i22 { width: calc(var(--u) * 22); height: calc(var(--u) * 22); }
.i30 { width: calc(var(--u) * 30); height: calc(var(--u) * 30); }
.i-pin { width: calc(var(--u) * 14); height: calc(var(--u) * 18); color: var(--acc); }
.i-pin-s { width: calc(var(--u) * 10); height: calc(var(--u) * 13); }
.i-shield { width: calc(var(--u) * 20); height: calc(var(--u) * 22); }
.i-truck { width: calc(var(--u) * 19); height: calc(var(--u) * 18); }
.i-bm { width: calc(var(--u) * 16); height: calc(var(--u) * 18); }

.star {
  color: var(--acc);
}

.star--ink {
  color: var(--ink);
}

/* Outline figures set in BBH Bartle */
.fig {
  overflow: visible;
}

.fig text {
  font-family: "BBH Bartle", Geist, sans-serif;
  font-weight: 400;
  fill: none;
  stroke-width: 1;
}

.fig--ink text { stroke: var(--ink); }
.fig--acc text { stroke: var(--acc); }
.fig--soft text { stroke: var(--acc); fill: var(--acc-a08); }
.fig--soft10 text { stroke: var(--acc); fill: var(--acc-a10); }

/* Rulers */
.ruler {
  width: 100%;
  height: calc(var(--u) * 14);
  overflow: visible;
}

.ruler line {
  stroke-width: .5;
}

.ruler__maj { stroke: var(--acc); }
.ruler__min { stroke: var(--mute); }

.ruler text {
  font-family: Geist, sans-serif;
  font-size: 11px;
  font-weight: 300;
  letter-spacing: 1.5px;
  fill: var(--mute);
}

/* account › Preferences › Reduce motion: <html data-motion="reduce"> (theme.js) switches animations off site-wide */
[data-motion="reduce"] *,
[data-motion="reduce"] *::before,
[data-motion="reduce"] *::after {
  animation-duration: .01ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: .01ms !important;
  scroll-behavior: auto !important;
}

/* == 06. Layout ======================================================== */
.wrap {
  margin-left: var(--gut);
  margin-right: var(--gut);
}

.sec {
  display: flex;
  flex-direction: column;
}

.sep {
  margin: calc(var(--u) * 80) var(--gut);
  height: .5px;
  border: 0;
  background: var(--line);
}

.hd-gap {
  height: calc(var(--u) * 80);
}

/* == 07. Section heads ================================================= */
.shead {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: calc(var(--u) * 60);
  padding: 0 var(--gut);
}

.shead__l {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 26);
}

.shead--80 .shead__l {
  gap: calc(var(--u) * 22);
}

.shead__r {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 36);
}

.shead--jr .vsep {
  background: var(--line2);
}

.shead--why .shead__r {
  gap: calc(var(--u) * 30);
}

.shead--jr .shead__r {
  gap: calc(var(--u) * 24);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 18);
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 3.92);
  color: var(--mute);
}

.eyebrow__n {
  color: var(--acc);
}

.eyebrow__rule {
  width: calc(var(--u) * 60);
  height: .5px;
  background: var(--mute);
}

.h2 {
