/* == 10. Header ======================================================== */
:root {
  --hs96: rgba(255, 255, 255, .96);
  --hs94: rgba(255, 255, 255, .94);
  --hs92: rgba(255, 255, 255, .92);
  --hs90: rgba(255, 255, 255, .9);
  --hs60: rgba(255, 255, 255, .6);
  --hi04: rgba(17, 20, 24, .04);
  --hi15: rgba(17, 20, 24, .15);
  --hi18: rgba(17, 20, 24, .18);
  --hi25: rgba(17, 20, 24, .25);
}

[data-theme="dark"] {
  --hs96: rgba(22, 24, 29, .96);
  --hs94: rgba(22, 24, 29, .94);
  --hs92: rgba(22, 24, 29, .92);
  --hs90: rgba(22, 24, 29, .9);
  --hs60: rgba(22, 24, 29, .6);
  --hi04: rgba(242, 243, 245, .04);
  --hi15: rgba(242, 243, 245, .15);
  --hi18: rgba(242, 243, 245, .18);
  --hi25: rgba(242, 243, 245, .25);
