/* == 11. Hero ========================================================== */
/* Laptop/HD screens (1200–1999px): the hero grows to the window height.
   main.js sets --hs = window height / hero height (1…1.25); everything inside
   the hero scales by it, the photo grows from the centre. 2000px+ is untouched. */
:root {
  --uw: calc(100vw / 2560);
}

@media (min-width: 1200px) {
  .hero {
    --u: calc(var(--uw) * var(--hs, 1));
  }
}

.hero {
  position: relative;
  height: calc(var(--u) * 1200);
  overflow: hidden;
  background-color: var(--page);
  background-image: url("../img/hero-bg.webp"), linear-gradient(90deg, #f5f7fb 0%, #fff 25%, #fdfffe 50%, #fff 80%, #f8fafb 100%);
  background-repeat: no-repeat, no-repeat;
  background-size: calc(var(--u) * 2560) calc(var(--u) * 1060), 100% 100%;
  background-position: center bottom, left top;
  color: var(--ink);
}

[data-theme="dark"] .hero {
  background-image: url("../img/hero-dark.webp"), linear-gradient(90deg, rgb(7, 8, 12) 0%, rgb(24, 26, 30) 25%, rgb(33, 35, 41) 50%, rgb(19, 21, 24) 75%, rgb(11, 12, 16) 100%);
}

.hero__social {
  position: absolute;
  left: var(--gut);
  top: calc(var(--u) * 330);
