/* == 22. Responsive — tablet (768–1199px) ============================= */
@media (max-width: 1199px) {
  :root {
    --u: .6px;
    --gut: 32px;
  }

  /* header: burger + drawer */
  .hd__bar {
    font-size: 13px;
  }

  .hd__info li:nth-child(3),
  .hd__util a:nth-child(-n+3),
  .hd__sep {
    display: none;
  }

  .hd__main {
    height: auto;
    align-items: center;
  }

  .hd__logo,
  .hd__acts {
    position: relative;
    z-index: 2;
  }

  .logo {
    height: 44px;
  }

  .hd__burger {
    display: flex;
  }

  .nav {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 1;
    transform: none;
    padding: 150px var(--gut) 40px;
    overflow-y: auto;
    background: var(--bg);
  }

  .is-menu .nav {
    display: block;
  }

  .is-menu body {
    overflow: hidden;
  }

  .nav__list {
    height: auto;
    flex-direction: column;
    max-width: 560px;
    margin: 0 auto;
  }

  .nav__btn {
    width: 100%;
    height: 60px;
    padding: 0 4px;
    justify-content: space-between;
    border: 0;
    border-bottom: .5px solid var(--line);
    border-radius: 0;
    font-size: 17px;
  }

  .nav__btn.is-current {
    color: var(--acc);
    border-color: var(--line);
  }

  .nav__btn .ico {
    width: 12px;
    height: 12px;
    transition: transform .2s;
  }

  .nav__item.is-open .nav__btn .ico {
    transform: rotate(180deg);
  }

  .dd {
    position: static;
    padding: 0;
  }

  .dd__list {
    width: auto;
    padding: 4px 0 12px 16px;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .dd__link {
    padding: 14px 0;
    gap: 16px;
  }

  .dd__t {
    font-size: 14px;
  }

  /* second level becomes a nested accordion */
  .dd__sub,
  .dd__sub--up {
    position: static;
    padding: 0;
  }

  .dd__list--sub {
    width: auto;
    padding: 0 0 8px 28px;
  }

  .dd__list--sub .dd__link,
  .dd__list--tight .dd__link {
    padding: 12px 0;
  }

  .dd__more {
    width: 12px;
    height: 12px;
    transition: transform .2s;
  }

  .dd__grp.is-open .dd__more {
    transform: rotate(90deg);
  }

  .dd__n {
    font-size: 12px;
  }

  /* hero: copy, picture, search stacked */
  .hero {
    height: auto;
    padding: 150px var(--gut) 40px;
    background-image: linear-gradient(90deg, #f5f7fb 0%, #fff 25%, #fdfffe 50%, #fff 80%, #f8fafb 100%);
    background-size: 100% 100%;
  }

  [data-theme="dark"] .hero {
    background-image: linear-gradient(90deg, rgb(7, 8, 12) 0%, rgb(24, 26, 30) 25%, rgb(33, 35, 41) 50%, rgb(19, 21, 24) 75%, rgb(11, 12, 16) 100%);
  }

  .hero__social,
  .range,
  .gauge {
    display: none;
  }

  .hero__copy {
    position: static;
  }

  .hero__copy::after {
    content: "";
    display: block;
    width: calc(100% + 2 * var(--gut));
    height: 46vw;
    margin: 12px calc(-1 * var(--gut)) 0;
    background: url("../img/hero-bg.webp") 50% 72% / 140% auto no-repeat;
    -webkit-mask-image: linear-gradient(180deg, transparent 0, #000 22%);
  }

  [data-theme="dark"] .hero__copy::after {
    background-image: url("../img/hero-dark.webp");
  }

  .hero__title {
    font-size: 56px;
    line-height: 1.02;
  }

  .hero__sub {
    font-size: 19px;
    line-height: 1.4;
    white-space: normal;
  }

  .fincard {
    display: none;
  }

  .search {
    position: relative;
    left: auto;
    right: auto;
    top: auto;
    height: auto;
    margin-top: 12px;
    padding: 8px;
    border-radius: 28px;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .search__f,
  .search__f.w12 {
    height: 72px;
    padding: 0 18px;
    border-right: 0;
    border-bottom: .5px solid var(--hi25);
  }

  .search__chev {
    right: 18px;
  }

  .search__sel {
    font-size: 16px;
  }

  .search__count {
    padding: 16px 18px;
    justify-content: flex-start;
  }

  .search__go {
    grid-column: 2 / -1;
    height: 56px;
    margin: 8px 0 0;
    justify-content: center;
  }

  /* section heads wrap */
  .shead {
    flex-direction: column;
    align-items: flex-start;
    gap: 24px;
  }

  .shead__r {
    flex-wrap: wrap;
    gap: 16px;
    max-width: 100%;
  }

  .chips {
    max-width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .h2 {
    white-space: normal;
  }

  /* featured */
  .car {
    flex-basis: 340px;
  }

  .car__title {
    white-space: normal;
  }

  .feat__foot {
    flex-wrap: wrap;
    row-gap: 16px;
  }

  .feat__note {
    order: 5;
    width: 100%;
  }

  /* body type bento */
  .bento {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: none;
    grid-auto-rows: minmax(300px, auto);
    grid-template-areas:
      "big big"
      "lux ele"
      "suv cla"
      "con mix"
      "quiz quiz";
  }

  .bt__photo {
    min-height: 300px;
  }

  /* car of the week: stacked, the scene keeps its artboard proportions */
  .cw__stage {
    height: auto;
    padding: 40px var(--gut);
    display: flex;
    flex-direction: column;
    gap: 24px;
  }

  .cw__l,
  .cw__r,
  .cw__week,
  .cw__thumbs,
  .cw__bar-panel {
    position: static;
  }

  .cw__l {
    order: 1;
  }

  .cw__scene {
    --u: calc(100vw / 2560 * 1.25);
    order: 2;
    position: relative;
    inset: auto;
    width: calc(var(--u) * 2560);
    height: calc(var(--u) * 1080);
    margin: -40px calc(50% - calc(var(--u) * 1280)) -20px;
  }

  .spot__lbl {
    display: none;
  }

  .cw__r {
    order: 3;
    align-items: flex-start;
  }

  .cw__price {
    align-items: flex-start;
  }

  .cw__week {
    display: none;
  }

  .cw__thumbs {
    order: 5;
  }

  .cw__thumbs ul {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .cw__photos {
    text-align: left;
  }

  .cw__bar-panel {
    order: 4;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 24px 0;
    padding: 24px;
  }

  .cw__spec {
    padding: 0 20px;
  }

  .cw__spec:nth-child(3) {
    border-left: 0;
  }

  .cw__acts {
    grid-column: 1 / -1;
    flex-direction: row;
    flex-wrap: wrap;
  }

  .cw__book {
    flex: 1 1 260px;
  }

  .cw__row {
    flex: 1 1 260px;
  }

  .cw__title {
    white-space: normal;
  }

  .cw__tags {
    flex-wrap: wrap;
  }

  /* why, how, stats */
  .grid4,
  .steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .steps {
    row-gap: 48px;
  }

  .step__track {
    right: 0;
  }

  .step:nth-child(2n) .step__track {
    right: 0;
  }

  .backed {
    flex-wrap: wrap;
  }

  .backed__list {
    flex-wrap: wrap;
    gap: 10px;
  }

  .how__foot {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .how__tags {
    flex-wrap: wrap;
    gap: 16px;
  }

  /* finance */
  .fin__head {
    flex-direction: column;
    align-items: flex-start;
    gap: 20px;
  }

  .fin__ctrl {
    justify-content: flex-start;
    row-gap: 10px;
  }

  .fin__chips {
    flex-wrap: wrap;
  }

  .fpill {
    height: auto;
    flex-direction: column;
    border-radius: 32px;
  }

  .fpill__car {
    padding: 20px;
  }

  .fpill__sliders {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 24px 0;
    padding: 4px 0 24px;
  }

  .fsl {
    padding: 0 20px;
  }

  .fsl:nth-child(odd) {
    border-left: 0;
  }

  .fsl--credit {
    grid-column: 1 / -1;
    border-left: 0;
  }

  .fsl__val {
    font-size: 15px;
  }

  .fres {
    padding: 20px 20px 20px 28px;
    border-radius: 28px;
    justify-content: space-between;
    flex-wrap: wrap;
  }

  .fin__foot {
    flex-wrap: wrap;
    row-gap: 12px;
  }

  .fin__foot > p:first-child {
    white-space: normal;
  }

  .split {
    order: 3;
    flex-basis: 100%;
    max-width: none;
  }

  /* reviews */
  .revs__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .rvf {
    grid-column: 1 / -1;
    height: 640px;
  }

  .rv--h820,
  .rv--h700,
  .rv--h800 {
    height: 520px;
    align-self: start;
  }

  .revs__foot,
  .jr__foot {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
  }

  /* journal */
  .grid3 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .field--news {
    width: 100%;
    max-width: 460px;
  }

  .ctx__v {
    white-space: normal;
  }

  /* footer */
  .ft {
    padding: 48px var(--gut) 40px;
  }

  .ft__side,
  .reg {
    display: none;
  }

  .ft__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .ft__cell--s2,
  .ft__cell--s3,
  .ft__cell--s6 {
    grid-column: 1 / -1;
  }

  .ft__cell--s1 {
    grid-column: span 1;
  }

  .ft__mark {
    height: 30vw;
  }

  .ft__word {
    top: 64px;
    font-size: 16vw;
    background-size: 97vw auto;
    background-position: center -16.8vw;
  }

  .ft__legal {
    grid-column: 1 / -1;
  }
}

