/* == 25. Sign in / sign up popup ======================================= */
/* calc(var(--m) * 1) = 1px of the 640px card; the card scales with the viewport height */
.auth {
  --m: clamp(.55px, calc(100vh / 1150), 1px);
  --in-bg: #fff;
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  margin: 0;
  padding: 40px 16px;
  border: 0;
  background: transparent;
  color: var(--ink);
  overflow-y: auto;
}

[data-theme="dark"] .auth {
  --in-bg: #181a1f;
}

.auth[open] {
  display: flex;
  animation: auth-fade .2s ease-out;
}

.auth::backdrop {
  background: rgba(17, 20, 24, .5);
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  animation: auth-fade .2s ease-out;
}

@keyframes auth-fade {
  from { opacity: 0; }
}

@keyframes auth-rise {
  from { opacity: 0; transform: translateY(16px); }
}

.is-modal,
.is-modal body {
  overflow: hidden;
}

.auth__card {
  width: calc(var(--m) * 640);
  margin: auto;
  padding: calc(var(--m) * 40) calc(var(--m) * 44) calc(var(--m) * 36);
  border-radius: calc(var(--m) * 40);
  background: var(--bg);
  box-shadow: 0 calc(var(--m) * 40) calc(var(--m) * 120) rgba(0, 0, 0, .35);
  display: flex;
  flex-direction: column;
  gap: calc(var(--m) * 24);
  animation: auth-rise .26s cubic-bezier(.2, .8, .2, 1);
}

.auth__top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.auth__logo {
  height: calc(var(--m) * 40);
}

.auth__x {
  width: calc(var(--m) * 55);
  height: calc(var(--m) * 55);
  border-radius: 50%;
  border: .5px solid var(--ink);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--ink);
}

.auth__x:hover {
  color: var(--acc);
}

.auth__x .ico {
  width: calc(var(--m) * 18);
  height: calc(var(--m) * 18);
}

.auth__head {
  display: flex;
  flex-direction: column;
  gap: calc(var(--m) * 10);
}

.auth__title {
  font-size: max(12px, calc(var(--m) * 48));
  letter-spacing: -.04em;
  line-height: 1;
}

.auth__sub {
  font-size: max(12px, calc(var(--m) * 17));
  color: var(--body);
}

.auth__tabs {
  display: flex;
  padding: calc(var(--m) * 4);
  border-radius: calc(var(--m) * 30);
  border: .5px solid var(--ink);
}

.auth__tab {
  flex: 1;
  height: calc(var(--m) * 50);
  border-radius: calc(var(--m) * 25);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: max(12px, calc(var(--m) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--m) * 1.82);
  white-space: nowrap;
  color: var(--ink);
}

.auth__tab:hover {
  color: var(--acc);
}

.auth__tab.is-on {
  background: var(--ink);
  color: var(--on-ink);
}

.auth__social {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: calc(var(--m) * 10);
}

.auth__soc {
  height: calc(var(--m) * 58);
  border-radius: calc(var(--m) * 29);
  border: .5px solid var(--ink);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--m) * 12);
  font-size: max(12px, calc(var(--m) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--m) * 1.68);
  color: var(--ink);
}

.auth__soc:hover {
  color: var(--acc);
}

.auth__soc .i20 {
  width: calc(var(--m) * 20);
  height: calc(var(--m) * 20);
}

.i-apple {
  width: calc(var(--m) * 18);
  height: calc(var(--m) * 20);
}

.auth__or {
  display: flex;
  align-items: center;
  gap: calc(var(--m) * 16);
  font-size: max(12px, calc(var(--m) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--m) * 2.64);
  color: var(--mute);
}

.auth__or span {
  flex: 1;
  height: .5px;
  background: var(--line2);
}

.auth__form {
  display: flex;
  flex-direction: column;
  gap: calc(var(--m) * 24);
}

.auth__names {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: calc(var(--m) * 14);
}

/* fields */
.afield {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--m) * 8);
}

.afield__lbl {
  display: flex;
  justify-content: space-between;
  font-size: max(12px, calc(var(--m) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--m) * 2.42);
  color: var(--mute);
}

.afield__lbl .acc {
  margin-right: calc(var(--m) * 8);
}

.afield__aside {
  color: var(--acc);
  text-transform: uppercase;
}

.afield__aside:hover {
  color: var(--acc-d);
}

.afield__aside--mute {
  color: var(--mute);
}

.afield__box {
  height: calc(var(--m) * 58);
  padding: 0 calc(var(--m) * 22);
  border-radius: calc(var(--m) * 29);
  border: .5px solid var(--line2);
  background: var(--in-bg);
  display: flex;
  align-items: center;
  gap: calc(var(--m) * 12);
  transition: border-color .15s, box-shadow .15s;
}

.afield.is-filled .afield__box {
  border-color: var(--ink);
}

.afield__box:focus-within,
.afield.is-filled .afield__box:focus-within {
  border: 1px solid var(--acc);
  box-shadow: 0 0 0 calc(var(--m) * 5) var(--acc-a14);
}

.afield.is-error .afield__box {
  border: 1px solid var(--acc);
}

.afield__in {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  font-size: max(12px, calc(var(--m) * 19));
  font-weight: 300;
  color: var(--ink);
}

.afield__ok {
  width: calc(var(--m) * 22);
  height: calc(var(--m) * 22);
  border-radius: 50%;
  background: var(--ok);
  color: #fff;
  display: none;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.afield__ok .ico {
  width: calc(var(--m) * 10);
  height: calc(var(--m) * 10);
}

.afield.is-valid .afield__ok {
  display: flex;
}

.afield__show {
  font-size: max(12px, calc(var(--m) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--m) * 1.76);
  color: var(--ink);
}

.afield__show:hover {
  color: var(--acc);
}

.afield__msg {
  font-size: max(12px, calc(var(--m) * 11));
  letter-spacing: calc(var(--m) * 0.44);
  color: var(--acc);
}

.afield__msg:empty {
  display: none;
}

.afield__msg.is-note {
  color: var(--ok);
}

/* keep me signed in */
.keep {
  display: flex;
  align-items: center;
  gap: calc(var(--m) * 12);
  font-size: max(12px, calc(var(--m) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--m) * 1.82);
  color: var(--ink);
  cursor: pointer;
}

.keep__in {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}

.keep__box {
  width: calc(var(--m) * 22);
