/* == 27. Preloader ===================================================== */
/* the AVAVA outline draws itself, then slowly fills with the accent from the bottom up */
.pre {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 28px;
  background: var(--bg);
  transition: opacity .5s ease, visibility .5s ease;
  animation: pre-out .5s ease 8s forwards;
}

.pre.is-done {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.pre__logo {
  width: min(340px, 64vw);
  height: auto;
  overflow: visible;
}

.pre__line {
  fill: none;
  stroke: var(--acc);
  stroke-width: 1.2;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: pre-draw 1.1s ease-out forwards;
}

.pre__fill {
  fill: var(--acc);
  transform: translateY(26px);
  animation: pre-fill 1.8s cubic-bezier(.6, 0, .3, 1) .5s forwards;
}

.pre__sub {
  fill: var(--ink);
  opacity: 0;
  animation: pre-in .6s ease .6s forwards;
}

.pre__bar {
  position: relative;
  width: 160px;
  height: 1px;
  overflow: hidden;
  background: var(--line2);
}

.pre__run {
  position: absolute;
  top: 0;
  left: 0;
  width: 40%;
  height: 100%;
  background: var(--acc);
  animation: pre-run 1.2s ease-in-out infinite;
}

@keyframes pre-draw {
  to { stroke-dashoffset: 0; }
}

@keyframes pre-fill {
  to { transform: translateY(0); }
}

@keyframes pre-in {
  to { opacity: 1; }
}

@keyframes pre-run {
  from { transform: translateX(-100%); }
  to { transform: translateX(250%); }
}

@keyframes pre-out {
  to { opacity: 0; visibility: hidden; }
}

@media (prefers-reduced-motion: reduce) {
  .pre__line,
  .pre__fill,
  .pre__sub,
  .pre__run {
    animation: none;
  }

  .pre__line { stroke-dashoffset: 0; }
  .pre__fill { transform: none; }
  .pre__sub { opacity: 1; }
}

