}

/* the showroom pin with its distance rings */
.vpin {
  position: relative;
}

.vpin__dot,
.vpin__r {
  position: absolute;
  left: 0;
  top: 0;
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

.vpin__dot {
  width: calc(var(--u) * 22);
  height: calc(var(--u) * 22);
  background: var(--acc);
  box-shadow: 0 0 0 calc(var(--u) * 12) var(--acc-a20), 0 0 0 calc(var(--u) * 28) var(--acc-a08);
}

.vpin__r {
  border: 1px solid var(--acc);
}

.vpin__r--1 { width: calc(var(--u) * 120); height: calc(var(--u) * 120); opacity: .5; }
.vpin__r--2 { width: calc(var(--u) * 240); height: calc(var(--u) * 240); opacity: .38; border-style: dashed; }
.vpin__r--3 { width: calc(var(--u) * 380); height: calc(var(--u) * 380); opacity: .26; border-style: dashed; }

