/* == 36. Service — shared ============================================== */
:root {
  --sv-ghost: rgba(17, 20, 24, .07);
  --sv-num: rgba(17, 20, 24, .12);
  --sv-surf2: #fbfbfc;
  --sv-soft: rgba(128, 132, 140, .35);
  --sv-dim: rgba(128, 132, 140, .3);
}

[data-theme="dark"] {
  --sv-ghost: rgba(242, 243, 245, .07);
  --sv-num: rgba(242, 243, 245, .14);
  --sv-surf2: #181a1f;
}

/* car thumbnail: follows the theme and the inherited accent; the whole car fits
   (the photos have plain white / black edges, so the box colour matches them) */
.thumb {
  display: block;
  flex-shrink: 0;
  border: .5px solid var(--line2);
  background: #fefefe url("../img/finance-light.webp") center / contain no-repeat;
}

[data-theme="dark"] .thumb {
  background-color: #000;
  background-image: url("../img/finance-dark.webp");
}

[data-skin="green"] .thumb { background-image: url("../img/merc-profile-light.webp"); }
[data-skin="green"][data-theme="dark"] .thumb { background-image: url("../img/merc-profile-dark.webp"); }

.circ--acc {
  border: 0;
  background: var(--acc);
  color: #fff;
}

.circ--acc:hover {
  background: var(--acc-d);
  color: #fff;
}

.i24 { width: calc(var(--u) * 24); height: calc(var(--u) * 24); }

/* == 37. Service — 01 services ========================================= */
.svc {
  gap: calc(var(--u) * 40);
}

.svc__slot {
  height: calc(var(--u) * 48);
  padding: 0 calc(var(--u) * 20);
  border-radius: calc(var(--u) * 24);
  border: .5px solid var(--line2);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.16);
  white-space: nowrap;
}

.svc__note {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.4);
  white-space: nowrap;
  color: var(--mute);
}

.svc .shead__r {
  gap: calc(var(--u) * 24);
}

.sgrid {
  display: grid;
  grid-template-columns: 1.3fr 1fr 1fr;
  grid-template-rows: calc(var(--u) * 420) calc(var(--u) * 420);
  gap: calc(var(--u) * 18);
}

/* featured: the 150-point inspection, dark in both themes */
.svx {
  grid-row: span 2;
}

.svx__link {
  position: relative;
  height: 100%;
  border-radius: calc(var(--u) * 32);
  border: .5px solid var(--acc);
  overflow: hidden;
  background: #111418;
  color: #f2f3f5;
  display: flex;
  flex-direction: column;
