}

.svx__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  object-position: 50% 45%;
}

.svx__photo .slot__mk--tl { left: calc(var(--u) * 14); top: calc(var(--u) * 14); }
.svx__photo .slot__mk--tr { right: calc(var(--u) * 14); top: calc(var(--u) * 14); }

.svx__photo .slot__mk--bl,
.svx__photo .slot__mk--br {
