/* == 42. Service — tablet and phone ==================================== */
@media (max-width: 1199px) {
  .sgrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: none;
  }

  .svx {
    grid-column: 1 / -1;
    grid-row: auto;
  }

  .svx__media {
    height: 320px;
  }

  .svx__name {
    font-size: 36px;
  }

  .svx__foot {
    flex-wrap: wrap;
    gap: 16px;
  }

  .scell__link {
    min-height: 300px;
    gap: 24px;
  }

  .store {
    grid-template-columns: 1fr auto;
    gap: 16px 24px;
  }

  .store__text,
  .store__bays {
    grid-column: 1 / -1;
  }

  .store__text {
    grid-row: 2;
  }

  .how2__head {
