    margin-left: auto;
    margin-right: auto;
    padding: 0 24px;
    grid-template-columns: minmax(0, 1fr);
    gap: 28px;
  }

  .pcard {
    height: 340px;
  }

  .pkg__cmp {
    grid-template-columns: minmax(0, 1fr);
    gap: 28px;
  }

  .pkg__cta {
