    border-right: 0;
    border-bottom: .5px dashed var(--line2);
  }

  .bkf__head {
    flex-direction: column;
    align-items: flex-start;
    gap: 20px;
  }

  .bkf__steps {
    width: 100%;
  }

  .bkf__step {
    flex: 1;
    width: auto;
  }

  .bkf__when {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }

  .bkf__timebox,
  .bkf__modebox,
  .bkf__try {
