  }

  .tkt {
    padding: 28px 24px;
  }

  .fqa .shead__r {
    width: 100%;
  }

  .fqa__search {
    flex: 1;
    width: auto;
    max-width: 560px;
    min-height: 48px;
  }

  .fqa__all {
    min-height: 48px;
  }

  .fqa__box {
    grid-template-columns: minmax(0, 1fr);
    min-height: 0;
  }

  .fqa__list {
    border-right: 0;
    border-bottom: .5px solid var(--line2);
  }

  .fqa__panel {
    padding: 28px 24px;
  }

  .fqa__ghost {
    font-size: 200px;
    top: -20px;
  }

  .fqp__q {
    font-size: 30px;
  }

  .fqp__a {
    font-size: 16px;
  }

  .fqp__foot {
    flex-wrap: wrap;
    gap: 16px;
  }

  .fqa__nav .circ {
    width: 44px;
    height: 44px;
  }
