    padding: 6px 6px 6px 20px;
  }

  .fqa .shead__r {
    flex-wrap: wrap;
  }

  .fqa__search {
    flex: 1 1 100%;
  }

  .fqa__row {
    padding: 18px 16px;
    gap: 14px;
  }

  .fqa__panel {
