/* == 43. Pricing — shared ============================================== */
:root {
  --pr-grp: #fbfbfc;
  --pr-grey: #eef0f3;
  --pr-soft: rgba(128, 132, 140, .35);
  --pr-div: rgba(128, 132, 140, .3);
  --pr-dim: rgba(128, 132, 140, .25);
}

[data-theme="dark"] {
  --pr-grp: #181a1f;
  --pr-grey: #1b1e23;
}

.bartle-o {
  font-family: "BBH Bartle", Geist, sans-serif;
  font-weight: 400;
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1px var(--acc);
}

/* == 44. Pricing — 01 plans ============================================ */
.pls {
  gap: calc(var(--u) * 40);
}

.pls .shead__r {
  gap: calc(var(--u) * 18);
}

.bill__save {
