  letter-spacing: calc(var(--u) * 2.2);
  white-space: nowrap;
  color: var(--mute);
}

.bill__sv {
  font-size: max(12px, calc(var(--u) * 30));
  white-space: nowrap;
  color: var(--mute);
}

.bill__sv.is-ok {
  color: var(--ok);
}

.bill {
  padding: calc(var(--u) * 4);
