}

/* cars-per-month slider */
.carsl {
  padding: calc(var(--u) * 24) calc(var(--u) * 34);
  border-radius: 999px;
  border: .5px solid var(--line2);
  background: var(--surf);
  display: grid;
  grid-template-columns: calc(var(--u) * 420) 1fr calc(var(--u) * 380);
  align-items: center;
  gap: calc(var(--u) * 40);
}

.carsl__l {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.carsl__lbl {
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.42);
  white-space: nowrap;
  color: var(--mute);
}

.carsl__v {
  font-size: max(12px, calc(var(--u) * 40));
  letter-spacing: -.03em;
  white-space: nowrap;
}

.carsl__u {
  font-size: max(12px, calc(var(--u) * 15));
  letter-spacing: 0;
  color: var(--mute);
}

.carsl__track {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 8);
}

.carsl__rail {
  position: relative;
  height: calc(var(--u) * 30);
}

.carsl__rail::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: calc(var(--u) * 14);
  height: 1px;
  background: var(--line2);
}

.carsl__fill {
  position: absolute;
  left: 0;
  top: calc(var(--u) * 13);
  width: 12%;
  height: calc(var(--u) * 3);
  background: var(--acc);
}

.carsl__tick {
  position: absolute;
  top: calc(var(--u) * 8);
  width: 1px;
  height: calc(var(--u) * 14);
  background: var(--mute);
}

.carsl__tick--1 { left: 1.7%; }
.carsl__tick--25 { left: 40.7%; }

.carsl__knob {
  position: absolute;
  left: 12%;
  top: calc(var(--u) * 3);
  width: calc(var(--u) * 24);
  height: calc(var(--u) * 24);
  margin-left: calc(var(--u) * -12);
  border-radius: 50%;
  border: 1.5px solid var(--acc);
  background: var(--surf);
  pointer-events: none;
  transition: box-shadow .2s;
}

.carsl__rail:focus-within .carsl__knob {
  box-shadow: 0 0 0 calc(var(--u) * 5) var(--acc-a20);
}

.carsl__in {
  position: absolute;
  left: calc(var(--u) * -12);
  top: 0;
  width: calc(100% + calc(var(--u) * 24));
  height: calc(var(--u) * 30);
  margin: 0;
  opacity: 0;
  cursor: pointer;
}

.carsl__ticks {
  display: flex;
  justify-content: space-between;
  font-size: max(12px, calc(var(--u) * 10));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.6);
  color: var(--mute);
}

.carsl__mid {
  margin-left: 18%;
}

.carsl__rec {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: calc(var(--u) * 14);
}

.carsl__rt {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: calc(var(--u) * 4);
}

.carsl__rl {
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.2);
  white-space: nowrap;
  color: var(--acc);
}

.carsl__rn {
  font-size: max(12px, calc(var(--u) * 28));
  white-space: nowrap;
}

.carsl__go {
  width: calc(var(--u) * 52);
  height: calc(var(--u) * 52);
}

/* the plan sheet */
.plans {
  border-radius: calc(var(--u) * 32);
  border: .5px solid var(--line2);
  background: var(--surf);
  overflow: hidden;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.plan {
  position: relative;
  padding: calc(var(--u) * 40) calc(var(--u) * 44) calc(var(--u) * 36);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 22);
  transition: background .2s;
}

.plan + .plan {
  border-left: .5px solid var(--pr-div);
}

.plan:hover {
  background: var(--acc-a03);
}

.plan.is-on {
  background: var(--acc-a04);
  box-shadow: inset 0 3px 0 var(--acc);
}

.plan__hit,
.adn__hit {
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: 0;
}

.plan__hit:focus-visible,
.adn__hit:focus-visible {
  outline-offset: -4px;
}

.plan__ghost {
  position: absolute;
  right: calc(var(--u) * -30);
  top: calc(var(--u) * 40);
  font-family: "BBH Bartle", Geist, sans-serif;
  font-size: max(12px, calc(var(--u) * 420));
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1px rgba(128, 132, 140, .14);
  pointer-events: none;
}

.plan.is-on .plan__ghost {
  -webkit-text-stroke-color: var(--acc-a35);
}

.plan__top,
.plan__name,
.plan__price,
.plan__car,
.plan__desc,
.plan__use,
.plan__rows {
  position: relative;
}

.plan__top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.plan__who {
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 3.38);
  white-space: nowrap;
  color: var(--mute);
}

.plan__who .acc {
  margin-right: calc(var(--u) * 10);
}

.plan__tags {
  display: flex;
  gap: calc(var(--u) * 6);
}

.plan__pop,
.plan__fit {
  height: calc(var(--u) * 32);
  padding: 0 calc(var(--u) * 14);
  border-radius: calc(var(--u) * 16);
  display: flex;
  align-items: center;
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.54);
  white-space: nowrap;
}

.plan__pop {
  background: var(--acc);
  color: #fff;
}

.plan__fit {
