/* == 49. Pricing — tablet and phone ==================================== */
@media (max-width: 1199px) {
  .carsl {
    grid-template-columns: 1fr auto;
    gap: 16px 24px;
    padding: 20px 24px;
    border-radius: 28px;
  }

  .carsl__track {
    grid-column: 1 / -1;
    grid-row: 2;
  }

  .plans {
    grid-template-columns: minmax(0, 1fr);
  }

  .plan + .plan {
    border-left: 0;
    border-top: .5px solid var(--pr-div);
  }

  .plan {
    padding: 28px 24px;
  }

  .plan__ghost {
    font-size: 260px;
  }

  .plan__name {
    font-size: 32px;
  }

  .plan__pv {
    font-size: 72px;
  }

  .perks {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .perks__it:nth-child(3) {
    padding-left: 0;
    border-left: 0;
  }

  .perks__it:nth-child(n+3) {
    border-top: .5px solid var(--pr-div);
  }

  /* the compare table scrolls sideways with the feature names pinned */
  .cpt__wrap {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .cpt {
    min-width: 920px;
  }

  .cpt th:first-child {
    position: sticky;
    left: 0;
    z-index: 2;
    background: var(--surf);
  }

  .cpt__gr th:first-child {
