    gap: 8px 14px;
  }

  .fcars {
    flex-wrap: wrap;
  }

  .fgrid {
    grid-template-columns: minmax(0, 1fr);
    row-gap: 0;
  }

  .ftk,
  .fdl {
    padding: 28px 24px 24px;
  }

  .ftk {
    order: 1;
  }

  .fedge--av {
    order: 2;
  }

  .fmid {
    order: 3;
    padding: 32px 0;
  }

  .fdl {
    order: 4;
  }

  .fedge--dl {
    order: 5;
  }

  .fgrid > span:not([class]) {
    display: none;
  }

  .ftk__tv {
    font-size: 48px;
  }

  .fnote {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .adns__head {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
  }

  .adns__h2 {
    flex-wrap: wrap;
    white-space: normal;
    font-size: 40px;
    row-gap: 8px;
  }

  .adns__eb {
    flex-basis: 100%;
  }

  .adns__r {
    flex-wrap: wrap;
  }

  .adns__box {
    grid-template-columns: minmax(0, 1fr);
  }

  .adns__cells {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .adn {
    border-bottom: .5px solid var(--line2);
  }

  .adn:nth-child(2n) {
    border-right: 0;
  }

  .adn__step {
    height: 48px;
  }

  .adn__sb {
    width: 40px;
    height: 40px;
  }

  .pfq__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pft {
    height: 380px;
  }

  .pft__q {
    font-size: 24px;
  }

  .pft__short {
    font-size: 48px;
  }

  .pfq__foot {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }
}

