/* == 63. Terms — shared ================================================ */
:root {
  --tm-hair: rgba(17, 20, 24, .12);
  --tm-num: rgba(17, 20, 24, .28);
  --tm-ver: rgba(17, 20, 24, .3);
  --tm-dot: rgba(128, 132, 140, .5);
  --tm-band: #111418;
}

[data-theme="dark"] {
  --tm-hair: rgba(242, 243, 245, .12);
  --tm-num: rgba(242, 243, 245, .28);
  --tm-ver: rgba(242, 243, 245, .3);
  --tm-band: #1a1d22;
}

.tms__fig,
.tmt__n,
.tmc__num {
  font-family: "BBH Bartle", Geist, sans-serif;
  font-weight: 400;
  line-height: .9;
  white-space: nowrap;
  color: transparent;
}

/* == 64. Terms — 01 the short version ================================== */
.tms {
  gap: calc(var(--u) * 40);
}

.tms__r {
  gap: calc(var(--u) * 12);
}

.tms__chips {
  display: flex;
  gap: calc(var(--u) * 12);
}

.tms__chip {
