  border: .5px solid var(--line2);
  background: var(--surf);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: calc(var(--u) * 2);
}

.tms__ck {
  font-size: max(12px, calc(var(--u) * 10));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.8);
  color: var(--mute);
}

.tms__cv {
  font-size: max(12px, calc(var(--u) * 18));
  white-space: nowrap;
}

.tms__pdf {
  height: calc(var(--u) * 62);
  padding: 0 calc(var(--u) * 8) 0 calc(var(--u) * 26);
