  border: 0;
  background: var(--ink);
  color: var(--on-ink);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 16);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.56);
  white-space: nowrap;
  cursor: pointer;
}

.tms__pdf:hover {
