  color: #fff;
}

.tms__pdot {
  width: calc(var(--u) * 46);
  height: calc(var(--u) * 46);
  border-radius: 50%;
  background: var(--acc);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transform: rotate(90deg);
}

.tms__grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: calc(var(--u) * 14);
}

.tms__card {
  position: relative;
  height: calc(var(--u) * 400);
  padding: calc(var(--u) * 30) calc(var(--u) * 30) calc(var(--u) * 26);
  border-radius: calc(var(--u) * 32);
  border: .5px solid var(--line2);
  background: var(--surf);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 14);
