}

.is-hot .tms__go {
  border-top-color: rgba(255, 255, 255, .4);
}

/* == 65. Terms — 02 the full agreement ================================= */
/* the rail is sticky: nothing above it may clip (overflow: clip, never hidden) */
.tmt {
  overflow: clip;
}

.tmt__grid {
  display: grid;
  grid-template-columns: calc(var(--u) * 600) minmax(0, 1fr);
  gap: calc(var(--u) * 80);
  align-items: start;
}

.tmt__rail {
  position: sticky;
  top: 24px;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 28);
}

.tmt__hl {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 22);
}

.tmt__h2 {
  font-size: max(12px, calc(var(--u) * 72));
  letter-spacing: -.045em;
  line-height: 1.02;
}

.tmt__find {
  height: calc(var(--u) * 64);
  padding: 0 calc(var(--u) * 20) 0 calc(var(--u) * 24);
  border-radius: calc(var(--u) * 32);
  border: .5px solid var(--ink);
  background: var(--surf);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
  color: var(--acc);
}

.tmt__in {
  flex: 1;
  min-width: 0;
  height: calc(var(--u) * 58);
  border: 0;
  outline: 0;
  background: transparent;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 20));
  color: var(--ink);
  -webkit-appearance: none;
  appearance: none;
}

.tmt__in::placeholder {
  color: var(--mute);
}

.tmt__in::-webkit-search-cancel-button {
  display: none;
}

.tmt__find:focus-within {
  box-shadow: 0 0 0 3px var(--acc-a18);
}

.tmt__hits {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  white-space: nowrap;
}

.tmt__prog {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

.tmt__pl2 {
  display: flex;
  justify-content: space-between;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.16);
  color: var(--mute);
}

.tmt__bar {
  display: block;
  height: calc(var(--u) * 4);
  border-radius: calc(var(--u) * 2);
  background: var(--hair);
  overflow: hidden;
}

.tmt__fill {
  display: block;
  height: 100%;
  width: 0;
  background: var(--acc);
  transition: width .3s;
}

.tmt__list {
  border-top: .5px solid var(--line2);
}

.tmt__row {
  position: relative;
  padding: calc(var(--u) * 16) 0;
  border-bottom: .5px solid var(--line2);
  display: grid;
  grid-template-columns: calc(var(--u) * 52) minmax(0, 1fr) auto;
  align-items: center;
  gap: calc(var(--u) * 14);
  transition: padding .25s, background-color .25s, color .25s, opacity .25s;
}

.tmt__row::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 0;
  background: var(--acc);
  transition: width .25s;
}

.tmt__row:hover {
  color: var(--acc);
}

.tmt__row.is-on {
  padding-left: calc(var(--u) * 20);
  background: var(--acc-a04);
  color: var(--acc);
}

.tmt__row.is-on::before {
  width: 3px;
}

.tmt__row.is-dim {
  opacity: .35;
}

.tmt__rn {
  font-size: max(12px, calc(var(--u) * 13));
  font-weight: 400;
  letter-spacing: calc(var(--u) * 1.3);
  color: var(--mute);
}

.tmt__row.is-on .tmt__rn {
  color: var(--acc);
}

.tmt__rt {
  font-size: max(12px, calc(var(--u) * 22));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tmt__tag {
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.54);
  color: var(--ok);
}

.tmt__tag.is-match {
  color: var(--acc);
}

.tmt__alsob {
  padding: calc(var(--u) * 26) calc(var(--u) * 28);
  border-radius: calc(var(--u) * 26);
  border: .5px solid var(--line2);
  background: var(--surf);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

