/* == 68. Terms — print ================================================= */
/* "Download PDF" and "Print" open the print dialog: the clauses print as a plain document */
@media print {
  .hd,
  .crumbs,
  .phead,
  .hd-gap,
  .tms,
  .tmc,
  .tmq,
  .sep,
  .ft,
  .tmt__rail > :not(.tmt__hl),
  .tmt__copy,
  .pre,
  .skip {
    display: none !important;
  }

  body {
    background: #fff;
    color: #000;
  }

  .tmt__grid {
    display: block;
    margin: 0;
  }

  .tmt__rail {
    position: static;
    margin-bottom: 24px;
  }

  .tmt__cl {
    padding: 16px 0;
    opacity: 1 !important;
    box-shadow: none !important;
    background: none !important;
    break-inside: avoid;
    grid-template-columns: 60px 1fr;
  }
}

/* == 69. Terms — tablet and phone ====================================== */
@media (max-width: 1199px) {
  .tms .shead {
    flex-direction: column;
    align-items: flex-start;
    gap: 20px;
  }

  .tms__r {
    flex-wrap: wrap;
  }

  .tms__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .tms__card {
    height: 320px;
  }

  /* one column; the table of contents becomes a collapsible bar on top */
  .tmt__grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 30px;
  }

  .tmt__rail {
    position: static;
    gap: 20px;
  }

  .tmt__h2 {
    font-size: 56px;
  }

  .tmt__toc {
    border: .5px solid var(--line2);
    border-radius: 24px;
    background: var(--surf);
    overflow: hidden;
  }

  .tmt__tocbtn {
    display: flex;
  }

  .tmt__list {
    border-top: .5px solid var(--line2);
  }

  .tmt__toc:not(.is-open) .tmt__list {
    display: none;
  }

  .tmt__row {
    padding: 14px 20px;
  }

  .tmt__row.is-on {
    padding-left: 26px;
  }

  .tmt__list li:last-child .tmt__row {
    border-bottom: 0;
  }

  .tmt__cl {
    padding: 30px 26px;
    grid-template-columns: 110px minmax(0, 1fr);
    gap: 20px;
  }

  .tmt__t {
    font-size: 34px;
  }

  .tmc .shead {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
  }

  .tmc__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 10px;
  }

  .tmc__track,
  .tmc__prog {
    display: none;
  }

  .tmq__band {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    border-radius: 32px;
  }

  .tmq__c--1 {
    grid-column: 1 / -1;
    border-bottom: .5px solid rgba(242, 243, 245, .12);
  }

  .tmq__c:nth-child(3) {
    border-left: 0;
  }

  .tmq__h2 {
    font-size: 56px;
  }

  .tmq__ghost {
    width: 900px;
    height: 290px;
    bottom: auto;
    top: 40px;
  }

  .tmq__ghost text {
    font-size: 290px;
  }
}

/* the collapsible bar only exists below the desktop */
.tmt__tocbtn {
  display: none;
  width: 100%;
  min-height: 56px;
  padding: 0 20px;
  border: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 16px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  cursor: pointer;
}

.tmt__tocl {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: .18em;
  color: var(--mute);
}

.tmt__tocbtn .ico {
  transition: transform .25s;
}

.tmt__toc.is-open .tmt__tocbtn .ico {
  transform: rotate(180deg);
}

@media (max-width: 1199px) {
  .tmt__tocbtn {
    display: flex;
  }
}

@media (max-width: 767px) {
  .tms__chips {
