  }

  .tms__card {
    height: auto;
    min-height: 280px;
    padding: 18px 16px 16px;
    border-radius: 24px;
  }

  /* four wide Bartle glyphs ($500, 12MO) must fit half a phone screen */
  .tms__fig {
    height: 80px;
    font-size: calc(9vw - 10px);
  }

  .tms__t {
    font-size: 22px;
  }

  .tmt__h2 {
    font-size: 44px;
  }

  .tmt__cl {
    padding: 24px 18px;
