    gap: 10px;
  }

  .tmt__side {
    flex-direction: row;
    align-items: center;
    gap: 16px;
  }

  .tmt__n {
    width: auto;
    height: auto;
    font-size: 40px;
  }

  .tmt__head {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .tmt__t {
    font-size: 28px;
  }

  .tmt__p,
  .tmt__pt {
    font-size: 17px;
  }

  .tmt__plain {
    flex-direction: column;
    gap: 10px;
    padding: 16px 18px;
  }

  .tmc__grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .tmc__dotrow {
    height: 50px;
  }

  .tmq__band {
    grid-template-columns: minmax(0, 1fr);
    border-radius: 24px;
  }

  .tmq__c,
  .tmq__c--1 {
    padding: 30px 22px;
    border-left: 0;
    border-top: .5px solid rgba(242, 243, 245, .12);
  }

  .tmq__c--1 {
