  --lx-glass: rgba(20, 22, 27, .88);
  --lx-shadow: 0 24px 60px rgba(0, 0, 0, .35);
  --lx-pop: 0 30px 70px rgba(0, 0, 0, .5);
}

.i24 { width: calc(var(--u) * 24); height: calc(var(--u) * 24); }

.lx-gap {
  height: calc(var(--u) * 60);
}

/* deal chip with its five-step meter */
.lx-deal {
  height: calc(var(--u) * 30);
  padding: 0 calc(var(--u) * 12);
  border-radius: calc(var(--u) * 15);
  background: var(--acc-a10);
  color: var(--acc);
  display: inline-flex;
  align-items: center;
  gap: calc(var(--u) * 8);
  white-space: nowrap;
