  }

  .nfh__car {
    width: 25.4%;
    height: 36.8%;
    border-radius: 999px;
  }

  .nfh__road {
    top: calc(52% + 19.7%);
    width: 36.9%;
    height: auto;
    aspect-ratio: 900 / 120;
  }

  .nfh__top {
    flex-wrap: wrap;
    gap: 10px 20px;
  }

  .nfh__bot {
    grid-template-columns: minmax(0, 1fr);
    gap: 36px;
