/* == 86. Listing v2 — tablet and phone ================================= */
@media (max-width: 1199px) {
  .l2s__card {
    grid-template-columns: minmax(0, 1fr);
    border-radius: 32px;
  }

  .l2s__ghost {
    display: none;
  }

