    left: 0;
    right: auto;
    width: min(540px, calc(200% + 12px));
  }

  .l2s__tile:nth-child(2n) .l2s__pick {
    left: auto;
    right: 0;
  }

  .l2s__go {
    grid-column: 1 / -1;
    height: 72px;
    padding-left: 26px;
    justify-content: space-between;
  }

  .l2s__gdot {
    width: 54px;
    height: 54px;
  }

  .l2s__quick {
    flex-wrap: wrap;
  }

  .l2s__r {
    padding: 24px;
    border-top: .5px solid var(--l2-hair);
  }

  .l2grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
  }

  .l2c__ph {
    height: auto;
    aspect-ratio: 790 / 440;
  }

  .l2r {
    grid-template-columns: minmax(0, 1fr);
  }

  .l2r__ph {
    min-height: 0;
    aspect-ratio: 680 / 400;
  }

  .l2r__mid {
    padding: 24px;
  }

  .l2r__side {
    padding: 24px;
    border-left: 0;
    border-top: .5px solid var(--l2-hair);
  }

  .l2r__ctas {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .l2r__ctas .lrw__view,
  .l2r__ctas .lrw__two {
    flex: 1 1 260px;
  }
}

@media (max-width: 767px) {
  .l2s__card {
    border-radius: 24px;
  }

  .l2s__l,
  .l2s__r {
    padding: 20px 16px;
  }

  .l2s__conds {
    width: 100%;
  }

  .l2s__cond {
    flex: 1;
    padding: 0 6px;
  }

  .l2s__new {
    margin-left: 0;
  }

  .l2s__in {
    font-size: 20px;
  }

  .l2s__cn {
    font-size: 30px;
  }

  .l2s__line {
    gap: 10px;
  }

  .l2s__line .ico {
    width: 24px;
    height: 24px;
  }

  /* the tiles fold into a sheet under the Filters button */
  .l2s__tier {
    display: none;
    grid-template-columns: minmax(0, 1fr);
  }

  .js-ls-pill.is-sheet .l2s__tier {
    display: grid;
  }

  .l2s__pick,
  .l2s__tile:nth-child(2n) .l2s__pick,
  .l2s__tile:nth-child(4) .l2s__pick {
    position: static;
    width: auto;
    margin-top: 6px;
    padding: 12px;
    box-shadow: none;
  }

  .l2s__tile {
    flex-direction: column;
    align-items: stretch;
  }

  .l2s__pick .lsc__opt {
    grid-template-columns: minmax(0, 1fr) 70px 40px;
    padding: 0 14px;
    gap: 10px;
  }

  .l2s__quick .lsc__chips {
    flex-wrap: nowrap;
    overflow-x: auto;
    width: 100%;
    padding-bottom: 4px;
  }

  .l2s__row {
    padding: 0;
  }

  .l2s__views {
    margin-left: 0;
  }

  .l2grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .l2c__name {
    font-size: 28px;
  }

  .l2c__price {
    flex-wrap: wrap;
  }

  .l2r__name {
    font-size: 32px;
  }

  .l2r__specs {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

