  }

  .l2r__mo {
    font-size: 40px;
  }

  .l2c__meta {
    flex-wrap: wrap;
    white-space: normal;
  }
}

/* == 87. Listing v3 — shared =========================================== */
/* Builds on 20-listing.css and 22-listing2.css (pickers, chips, keyword line,
