/* the photo fills the top of the card; the frosted panel sits over the rest */
.l3c__img {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 72%;
  object-fit: cover;
  background: #fefefe;
}

[data-theme="dark"] .l3c__img,
[data-theme="dark"] .l3r__img {
  filter: brightness(.9);
}

.l3c:hover .l3c__zoom {
  transform: scale(1.06);
}

.l3c:hover .l3ghost,
.l3r:hover .l3ghost {
  opacity: .35;
}

.l3c .l2bs,
.l3r .l2bs {
  left: calc(var(--u) * 22);
  top: calc(var(--u) * 22);
}

.l3r .l2bs {
  left: calc(var(--u) * 26);
  top: calc(var(--u) * 26);
}

.l3c .l2b,
.l3r .l2b {
  height: calc(var(--u) * 34);
  padding: 0 calc(var(--u) * 14);
}

.l3c__acts {
  position: absolute;
  right: calc(var(--u) * 22);
  top: calc(var(--u) * 22);
  display: flex;
  gap: calc(var(--u) * 8);
}

.l3c__cmp {
  height: calc(var(--u) * 48);
  padding: 0 calc(var(--u) * 18);
  letter-spacing: .12em;
}

.l3c__fav {
  width: calc(var(--u) * 48);
  height: calc(var(--u) * 48);
}

.l3drop {
  top: calc(var(--u) * 84);
  bottom: auto;
  padding: 0 calc(var(--u) * 18) 0 calc(var(--u) * 22);
}

.l3r .l3drop {
  padding-left: calc(var(--u) * 26);
}

.l3c__navs {
  position: absolute;
  left: calc(var(--u) * 20);
  right: calc(var(--u) * 20);
  top: 42%;
  display: flex;
  justify-content: space-between;
  opacity: 0;
  pointer-events: none;
  transition: opacity .3s;
}

.l3c:hover .l3c__navs,
.l3c__ph:focus-within .l3c__navs {
  opacity: 1;
  pointer-events: auto;
}

.l3c__panel {
  position: absolute;
  left: calc(var(--u) * 16);
  right: calc(var(--u) * 16);
  bottom: calc(var(--u) * 16);
  padding: calc(var(--u) * 26) calc(var(--u) * 28);
  border-radius: calc(var(--u) * 28);
  border: .5px solid var(--l2-hair);
  background: var(--l3-frost);
  -webkit-backdrop-filter: blur(18px);
  backdrop-filter: blur(18px);
  color: var(--ink);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 14);
}

.l3c__panel .lx-dots {
  position: static;
  margin: calc(var(--u) * -10) 0 calc(var(--u) * 4);
  padding: 0;
}

.l3c__hd {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: calc(var(--u) * 12);
}

.l3c__name {
  min-width: 0;
  font-size: max(12px, calc(var(--u) * 36));
  letter-spacing: -.03em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: color .25s;
}

.l3c:hover .l3c__name,
.l3r:hover .l3r__name {
  color: var(--acc);
}

.l3c__yl {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.92);
  color: var(--mute);
  white-space: nowrap;
}

/* the panel opens on hover: grid rows 0fr → 1fr */
.l3c__more {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows .45s var(--lx-ease);
}

.l3c:hover .l3c__more,
.l3c:focus-within .l3c__more {
  grid-template-rows: 1fr;
}

.l3c__mi {
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 14);
}

.l3c__mi > :last-child {
  margin-bottom: calc(var(--u) * 4);
}

.l3c__trim {
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--body);
}

.l3c__pr {
  padding-top: calc(var(--u) * 16);
  border-top: .5px solid var(--l2-hair);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.l3c__price {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 2);
}

.l3c__mo {
  font-size: max(12px, calc(var(--u) * 34));
  white-space: nowrap;
}

.l3c__per {
  font-size: max(12px, calc(var(--u) * 13));
  color: var(--acc);
}

.l3c__full {
  font-size: max(12px, calc(var(--u) * 13));
  color: var(--mute);
}

.l3c__ctas {
  display: flex;
  gap: calc(var(--u) * 8);
}

.l3c__td {
  height: calc(var(--u) * 56);
  padding: 0 calc(var(--u) * 18);
  border-radius: calc(var(--u) * 28);
  border: .5px solid var(--l2-hair);
  display: flex;
  align-items: center;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.44);
  white-space: nowrap;
  opacity: 0;
  transition: opacity .3s, color .25s;
}

.l3c:hover .l3c__td,
.l3c:focus-within .l3c__td {
  opacity: 1;
}

.l3c__td:hover {
  color: var(--acc);
}

/* == 90. Listing v3 — 02 cinematic rows ================================ */
.l3r {
  height: calc(var(--u) * 470);
  border-radius: calc(var(--u) * 40);
  background: var(--surf);
  display: grid;
  grid-template-columns: calc(var(--u) * 760) minmax(0, 1fr);
}

.l3r__ph {
  position: relative;
  overflow: hidden;
  background: var(--l3-photo);
  isolation: isolate;
}

.l3r__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: #fefefe;
}

.l3r:hover .l3c__zoom {
  transform: scale(1.05);
}

.l3r__fav {
  position: absolute;
  right: calc(var(--u) * 24);
  top: calc(var(--u) * 24);
}

.l3r__fav .l3c__fav {
  width: calc(var(--u) * 50);
  height: calc(var(--u) * 50);
}

.l3r__navs {
  position: absolute;
  right: calc(var(--u) * 24);
  bottom: calc(var(--u) * 24);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 8);
  opacity: 0;
  transform: translateX(calc(var(--u) * 40));
  pointer-events: none;
  transition: opacity .3s, transform .35s var(--lx-ease);
}

.l3r:hover .l3r__navs,
.l3r__ph:focus-within .l3r__navs {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

.l3r__th {
  width: calc(var(--u) * 96);
  height: calc(var(--u) * 64);
}

.l3r .lx-dots {
  padding: 0 calc(var(--u) * 40);
  transition: opacity .3s;
}

.l3r:hover .lx-dots {
  opacity: 0;
}

.l3r__info {
  position: relative;
  min-width: 0;
  padding: calc(var(--u) * 34) calc(var(--u) * 40);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 16);
}

.l3r__nm {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
}

.l3r__name {
  font-size: max(12px, calc(var(--u) * 52));
  letter-spacing: -.04em;
  line-height: 1;
  transition: color .25s;
}

.l3r__trim {
  font-size: max(12px, calc(var(--u) * 17));
  color: var(--body);
}

.l3r .l3deal__m span {
  width: calc(var(--u) * 12);
}

.l3r__foot {
  margin-top: auto;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: calc(var(--u) * 16);
}

.l3r__mo {
  font-size: max(12px, calc(var(--u) * 50));
  letter-spacing: -.035em;
  line-height: 1;
  white-space: nowrap;
}

.l3r__per {
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--acc);
}

.l3r__full {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

.l3r__ctas {
  display: flex;
  gap: calc(var(--u) * 8);
}

.l3r__cmp,
.l3r__td {
  height: calc(var(--u) * 58);
  padding: 0 calc(var(--u) * 20);
  border-radius: calc(var(--u) * 29);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.44);
  white-space: nowrap;
  display: flex;
  align-items: center;
}

.l3r__cmp {
  border: .5px solid var(--lx-soft);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.l3r__cmp[aria-pressed="true"] {
  border-color: var(--acc);
  background: var(--acc);
  color: #fff;
}

.l3r__cmp.is-full {
  opacity: .6;
  cursor: not-allowed;
}

.l3r__td {
  padding: 0 calc(var(--u) * 18);
  border: .5px solid var(--l2-hair);
}

.l3r__cmp:hover,
.l3r__td:hover {
  color: var(--acc);
}

.l3r__cmp[aria-pressed="true"]:hover {
  color: #fff;
}

/* touch screens: no hover, so the controls and the full panel stay open */
@media (hover: none) {
  .l3c__navs,
  .l3r__navs {
    opacity: 1;
    transform: none;
    pointer-events: auto;
  }

  .l3c__more {
    grid-template-rows: 1fr;
  }

  .l3c__td {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .l3c:hover,
  .l3r:hover {
    transform: none;
  }
}

/* == 91. Listing v3 — tablet and phone ================================= */
@media (max-width: 1199px) {
  .l3s__card {
    border-radius: 32px;
  }

  .l3s__bar {
    padding: 18px 20px;
    flex-direction: column;
    align-items: flex-start;
  }

  .l3s__conds {
    max-width: 100%;
    overflow-x: auto;
  }

  .l3s__body {
    grid-template-columns: minmax(0, 1fr);
  }

  .l3s__l {
    padding: 24px 20px;
    border-right: 0;
  }

  .l3s__kw {
    height: 80px;
  }

  .l3s__in {
    height: 74px;
    font-size: 30px;
  }

  .l3s__drop {
    top: calc(100% + 8px);
    width: 100%;
  }

  .l3s__big {
    font-size: 110px;
  }

  .l3s__tiles {
    border-top: .5px solid var(--l2-hair);
  }

  .l3s__tile:nth-child(odd) {
    border-left: 0;
  }

  .l3s__tile:nth-child(3),
  .l3s__tile:nth-child(3) .l3s__tb {
    border-bottom-left-radius: 32px;
  }

  .l3s__tile:last-child,
  .l3s__tile:last-child .l3s__tb {
    border-bottom-right-radius: 32px;
  }

  .l3s__tb {
    min-height: 150px;
    padding: 20px;
  }

  .l3s__tv {
    font-size: 26px;
  }

  .l3s__tile:nth-child(2n) .l3s__pick {
    left: auto;
    right: 0;
  }

  .l3s__pick {
    width: min(540px, calc(200% + 1px));
  }

  /* cards: the photo on top, the panel below and always open */
  .l3grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
  }

  .l3c {
    height: auto;
  }

  .l3c__ph {
    position: static;
    display: flex;
    flex-direction: column;
  }

  .l3c__zoom {
    position: relative;
    inset: auto;
    display: block;
    aspect-ratio: 790 / 500;
    overflow: hidden;
  }

  .l3c__img {
    height: 100%;
  }

  .l3c:hover .l3c__zoom {
    transform: none;
  }

  .l3c__panel {
    position: static;
    margin: 0;
    border: 0;
    border-radius: 0;
    background: var(--surf);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .l3c__more {
    grid-template-rows: 1fr;
  }

  .l3c__td {
    opacity: 1;
  }

  .l3c__navs {
    top: 22%;
  }

  .l3ghost {
    top: 70px;
  }

  .l3r {
    height: auto;
    grid-template-columns: minmax(0, 1fr);
  }

  .l3r__ph {
    aspect-ratio: 760 / 470;
  }

  .l3r__info {
    padding: 24px;
  }

  .l3r__foot {
    flex-wrap: wrap;
  }

  .l3r__ctas {
    flex-wrap: wrap;
  }
}

@media (max-width: 767px) {
  .l3s__eb {
    flex-wrap: wrap;
    white-space: normal;
  }

  .l3s__conds {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 4px;
    overflow: visible;
  }

  .l3s__cond {
    height: 52px;
    padding: 0 14px;
    justify-content: space-between;
  }

  .l3s__cs {
    display: none;
  }

  .l3s__in {
    font-size: 20px;
  }

  .l3s__kw .l2s__line .ico {
    width: 24px;
    height: 24px;
  }

  .l3s__chips {
    flex-wrap: nowrap;
    overflow-x: auto;
    padding-bottom: 4px;
  }

  .l3s__foot {
    flex-direction: column;
    align-items: stretch;
    gap: 16px;
  }

  .l3s__big {
    font-size: 80px;
  }

  .l3s__go {
    height: 72px;
    padding-left: 26px;
    justify-content: space-between;
  }

  .l3s__go .lsc__gdot {
    width: 54px;
    height: 54px;
  }

  /* the tiles fold into a sheet under the Filters button */
  .l3s__tiles {
    display: none;
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: none;
  }

  .js-ls-pill.is-sheet .l3s__tiles {
    display: grid;
  }

  .l3s__tile,
  .l3s__tile:nth-child(odd) {
    border-left: 0;
  }

  .l3s__tile:nth-child(3),
  .l3s__tile:nth-child(3) .l3s__tb {
    border-bottom-left-radius: 0;
  }

  .l3s__tile:last-child,
  .l3s__tile:last-child .l3s__tb {
    border-radius: 0 0 24px 24px;
  }

  .l3s__pick,
  .l3s__tile:nth-child(2n) .l3s__pick {
    position: static;
    width: auto;
    margin: 6px 12px 12px;
    padding: 12px;
    box-shadow: none;
  }

  .l3s__pick .lsc__opt {
    grid-template-columns: minmax(0, 1fr) 70px 40px;
    padding: 0 14px;
    gap: 10px;
  }

  .l3grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .l3c__hd {
    flex-direction: column;
    gap: 4px;
  }

  .l3c__name {
    max-width: 100%;
    font-size: 26px;
  }

  .l3specs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .l3sp:nth-child(3) {
    padding-left: 0;
    border-left: 0;
  }

  .l3sp:nth-child(n + 3) {
    border-top: .5px solid var(--l2-hair);
  }

  .l3deal {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }

  .l3c__pr {
    flex-wrap: wrap;
  }

  .l3r__name {
    font-size: 32px;
  }

  .l3r__mo {
    font-size: 36px;
  }

  .l3r__th {
    display: none;
  }
