    padding: 0 6px;
    border-radius: 12px;
    background: var(--acc);
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
  }

  .l4t__fn[hidden] {
    display: none;
  }

  .l4t__pop--sort {
    right: auto;
    left: 0;
    width: min(420px, calc(100vw - 32px));
  }

  /* the sidebar becomes a slide-over sheet */
  .l4__body {
    display: block;
  }

  .l4side {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    z-index: 1500;
    width: min(440px, 92vw);
    padding: 24px 20px;
    border-radius: 0 24px 24px 0;
    overflow-y: auto;
    visibility: hidden;
    transform: translateX(-105%);
    transition: transform .35s var(--lx-ease), visibility 0s .35s;
  }

  .l4side.is-open {
    visibility: visible;
    transform: none;
    transition: transform .35s var(--lx-ease), visibility 0s 0s;
  }

  .l4side__close {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: .5px solid var(--l4-field);
    background: transparent;
    color: var(--ink);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
  }

  .l4side__h {
    margin-right: auto;
    font-size: 28px;
  }

  .l4dd__btn {
    height: 58px;
  }

  .l4dd__v,
  .l4chk,
  .l4dd__opt {
    font-size: 16px;
  }

  .l4dd__pop {
    position: static;
    margin-top: 8px;
    box-shadow: none;
  }

  .l4scrim {
    position: fixed;
    inset: 0;
    z-index: 1400;
    background: rgba(17, 20, 24, .45);
    display: block;
  }

  .l4scrim[hidden] {
    display: none;
  }

  .l4grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
  }

  .l4c__ph {
    height: auto;
    aspect-ratio: 790 / 460;
  }
}

@media (max-width: 767px) {
  .l4t__tabs {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 4px;
    overflow: visible;
  }

  .l4t__tab {
    height: 56px;
    padding: 0 14px;
    justify-content: space-between;
  }

  .l4t__ts {
    display: none;
  }

  .l4t__save {
    padding: 0 14px;
  }

  .l4t__views .l4t__view {
    padding: 0 12px;
  }

  .l4grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .l4c__specs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .l4c__name {
    font-size: 28px;
  }
}

/* == 97. Listing v5 — dark sidebar ===================================== */
