  border-radius: calc(var(--u) * 28);
  background: var(--acc);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.56);
