}

.l6tile__s {
  font-size: max(12px, calc(var(--u) * 11));
  opacity: .7;
  white-space: nowrap;
}

.l6tile__c {
  height: calc(var(--u) * 30);
  min-width: calc(var(--u) * 42);
  padding: 0 calc(var(--u) * 10);
