/* == 102. Listing Map v1 — shared ====================================== */
/* Built on Listing v1 (20-listing.css): console, cards, rows. Adds the split
   layout with a sticky price-pin map, the narrowed map rows and Load more. */
:root {
  --lm-map: #e9ecef;
  --lm-grid: rgba(17, 20, 24, .06);
  --lm-water: #d6e1ea;
  --lm-road: #fff;
  --lm-line: rgba(17, 20, 24, .18);
  --lm-hair: rgba(17, 20, 24, .12);
  --lm-hover: rgba(17, 20, 24, .04);
}

[data-theme="dark"] {
  --lm-map: #1a1d22;
  --lm-grid: rgba(242, 243, 245, .05);
  --lm-water: #161b22;
  --lm-road: #262a31;
  --lm-line: rgba(242, 243, 245, .16);
  --lm-hair: rgba(242, 243, 245, .12);
  --lm-hover: rgba(242, 243, 245, .05);
}

/* the two switches at the end of the chip row */
.lm__sw .lsc__view {
  display: flex;
  align-items: center;
  justify-content: center;
}

.lm__ic {
  width: calc(var(--u) * 56);
  padding: 0;
}

/* == 103. Listing Map v1 — layout and map ============================== */
/* the map is sticky: the section clips, never hides, its overflow */
.lm {
  overflow: clip;
}

.lm__body {
  display: flex;
  gap: calc(var(--u) * 30);
  align-items: flex-start;
}

.lm__map {
  display: none;
}

.lm.is-map .lm__map {
  position: sticky;
  top: 20px;
  flex: 0 0 calc(40% - calc(var(--u) * 18));
  height: calc(100vh - 40px);
  border-radius: calc(var(--u) * 36);
  border: .5px solid var(--lm-line);
  background: var(--lm-map);
  overflow: hidden;
  isolation: isolate;
  display: block;
}

/* the drawn map (grid, water, roads) shows until the tiles arrive */
.lm__mock {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(var(--lm-grid) 1px, transparent 1px), linear-gradient(90deg, var(--lm-grid) 1px, transparent 1px);
  background-size: calc(var(--u) * 80) calc(var(--u) * 80);
}

.lm__water {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 18%;
  background: var(--lm-water);
}

.lm__road {
  position: absolute;
  background: var(--lm-road);
}

.lm__road--1 { left: 0; right: 0; top: 38%; height: calc(var(--u) * 14); transform: rotate(-8deg); transform-origin: left; }
.lm__road--2 { left: 0; right: 0; top: 66%; height: calc(var(--u) * 10); transform: rotate(5deg); transform-origin: left; }
.lm__road--3 { top: 0; bottom: 0; left: 46%; width: calc(var(--u) * 12); transform: rotate(10deg); }
.lm__road--4 { top: 0; bottom: 0; left: 74%; width: calc(var(--u) * 8); transform: rotate(-6deg); }

.lm.is-live .lm__mock {
  display: none;
}

.lm__live {
  position: absolute;
  inset: 0;
  background: transparent;
  font-family: Geist, sans-serif;
}

.lm__map .leaflet-container {
  isolation: isolate;
  background: transparent;
}

.lm__live .leaflet-tile-pane {
  filter: grayscale(1) contrast(.92) brightness(1.04);
  opacity: .85;
}

[data-theme="dark"] .lm__live .leaflet-tile-pane {
  filter: grayscale(1) invert(1) contrast(.85) brightness(.8);
  opacity: .9;
}

.lm__live .leaflet-control-attribution {
  margin: 0 calc(var(--u) * 24) calc(var(--u) * 24) 0 !important;
  padding: 4px 10px;
  border-radius: 8px;
  background: var(--surf);
  font-size: 12px;
  color: var(--mute);
}

.lm__live .leaflet-control-attribution a {
  color: var(--ink);
}

/* price pins: the bottom centre of the pill is the coordinate */
.lmpin-wrap {
  position: relative;
}

.lmpin {
  position: absolute;
  left: 0;
  top: 0;
  height: calc(var(--u) * 44);
  padding: 0 calc(var(--u) * 18);
  border-radius: calc(var(--u) * 22);
  border: .5px solid var(--lm-line);
  background: var(--surf);
  color: var(--ink);
  box-shadow: 0 calc(var(--u) * 10) calc(var(--u) * 24) rgba(17, 20, 24, .18);
  display: flex;
  align-items: center;
  font-size: max(12px, calc(var(--u) * 15));
  white-space: nowrap;
  cursor: pointer;
  transform: translate(-50%, -100%);
  transition: transform .25s, background-color .25s, color .25s, border-color .25s;
}

.lmpin-wrap.is-on .lmpin,
.lmpin:hover {
  border-color: var(--acc);
  background: var(--acc);
  color: #fff;
  transform: translate(-50%, -100%) scale(1.12);
}

.lm__zoom {
  position: absolute;
  right: calc(var(--u) * 24);
  top: calc(var(--u) * 24);
  z-index: 500;
  border-radius: calc(var(--u) * 26);
  border: .5px solid var(--lm-line);
  background: var(--surf);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.lm__zb {
  width: calc(var(--u) * 52);
  height: calc(var(--u) * 52);
  border: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 22));
  cursor: pointer;
}

.lm__zb + .lm__zb {
  border-top: .5px solid var(--lm-line);
}

.lm__zb:hover {
  color: var(--acc);
}

.lm__count {
  position: absolute;
  left: calc(var(--u) * 24);
  bottom: calc(var(--u) * 24);
  z-index: 500;
  height: calc(var(--u) * 44);
  padding: 0 calc(var(--u) * 20);
  border-radius: calc(var(--u) * 22);
  border: .5px solid var(--lm-line);
  background: var(--surf);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  color: var(--mute);
}

.lm__cd {
  width: calc(var(--u) * 8);
  height: calc(var(--u) * 8);
  border-radius: 50%;
  background: var(--acc);
}

.lm__area {
  position: absolute;
  left: 50%;
  top: calc(var(--u) * 24);
  z-index: 500;
  height: calc(var(--u) * 44);
  padding: 0 calc(var(--u) * 20);
  border: 0;
  border-radius: calc(var(--u) * 22);
  background: var(--acc);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  box-shadow: 0 calc(var(--u) * 10) calc(var(--u) * 24) var(--acc-a30);
  transform: translateX(-50%);
  cursor: pointer;
}

.lm__area[hidden],
.lm__btn[hidden] {
  display: none;
}

/* == 104. Listing Map v1 — results ===================================== */
.lm__res {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.lm__grid,
.lm__list {
  margin: 0;
}

.lm.is-map .lm__grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

/* the list holds both row styles: v1 rows in the grid layout, 113e rows next to the map */
.lm.is-map .lm__list .lrw,
.lm:not(.is-map) .lm__list .lmr {
  display: none;
}

.lm.is-map .lm__list {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 14);
}

.lm__list[hidden],
.lm.is-map .lm__list[hidden] {
  display: none;
}

/* a pin hovered on the map lights its card like a hover */
.lcd.is-hot .lcd__ph {
  box-shadow: 0 calc(var(--u) * 36) calc(var(--u) * 80) rgba(17, 20, 24, .18);
}

.lcd.is-hot .lcd__img {
  transform: scale(1.04);
}

.lcd.is-hot .lcd__nav {
  opacity: 1;
}

.lcd.is-hot .lcd__n {
  bottom: calc(var(--u) * 120);
  color: var(--acc-a20);
  -webkit-text-stroke-color: var(--acc);
}

.lcd.is-hot .lcd__specs {
  transform: translateY(0);
  opacity: 1;
}

.lcd.is-hot .lx-dots {
  opacity: 0;
}

.lcd.is-hot .lcd__name,
.lcd.is-hot .lcd__go {
  color: var(--acc);
}

.lcd.is-hot .lcd__gdot {
  border-color: var(--acc);
  background: var(--acc);
  color: #fff;
}

/* row 113e */
.lmr {
  min-width: 0;
  border-radius: calc(var(--u) * 32);
  border: .5px solid var(--lm-hair);
  background: var(--surf);
  overflow: hidden;
  display: grid;
  grid-template-columns: calc(var(--u) * 440) minmax(0, 1fr) calc(var(--u) * 300);
  transition: border-color .25s;
}

.lmr:hover,
.lmr.is-hot {
  border-color: var(--acc-a40);
}

.lmr.is-cmp {
  border-color: var(--acc);
  box-shadow: inset 0 0 0 .5px var(--acc);
}

.lmr__ph {
  position: relative;
  height: calc(var(--u) * 320);
  background: var(--stripes);
  overflow: hidden;
}

.lmr__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  background: #fefefe;
  transition: transform .5s var(--lx-ease);
}

[data-theme="dark"] .lmr__img {
  filter: brightness(.9);
}

.lmr:hover .lmr__img,
.lmr.is-hot .lmr__img {
  transform: scale(1.04);
}

.lmr__tag {
  position: absolute;
  left: calc(var(--u) * 20);
  top: calc(var(--u) * 20);
  height: calc(var(--u) * 30);
  padding: 0 calc(var(--u) * 12);
  border-radius: calc(var(--u) * 15);
  color: #fff;
  display: flex;
  align-items: center;
