.lmr__tag--acc { background: var(--acc); }
.lmr__tag--ok { background: var(--ok); }
.lmr__tag--ink { background: #111418; }
.lmr__tag--mute { background: #5f6671; }

.lmr__fav {
  position: absolute;
  right: calc(var(--u) * 16);
  top: calc(var(--u) * 16);
