  flex-direction: column;
  gap: calc(var(--u) * 12);
  overflow: hidden;
}

/* ghost word: the last word of the model, sized min(170, 520 / (letters × 1.3)) */
.lmr__ghost {
  position: absolute;
  right: calc(var(--u) * 10);
  bottom: calc(var(--u) * -24);
  font-family: "BBH Bartle", Geist, sans-serif;
  font-weight: 400;
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1px var(--acc-a40);
  white-space: nowrap;
  pointer-events: none;
}

.lmr__g50 { font-size: calc(var(--u) * 50); }
.lmr__g100 { font-size: calc(var(--u) * 100); }
.lmr__g133 { font-size: calc(var(--u) * 133); }
.lmr__g170 { font-size: calc(var(--u) * 170); }

.lmr__meta,
.lmr__name,
.lmr__line,
.lmr__specs {
  position: relative;
}

.lmr__meta {
