  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.16);
  color: var(--mute);
}

.lmr__name {
  font-size: max(12px, calc(var(--u) * 40));
  font-weight: 300;
  letter-spacing: -.03em;
}

.lmr__name a {
  transition: color .25s;
}

.lmr:hover .lmr__name a,
.lmr.is-hot .lmr__name a {
  color: var(--acc);
}

.lmr__line {
  max-width: calc(var(--u) * 560);
  font-size: max(12px, calc(var(--u) * 17));
  line-height: 1.5;
  color: var(--body);
}

.lmr__specs {
  margin-top: auto;
  padding-top: calc(var(--u) * 16);
  border-top: .5px solid var(--lm-hair);
  display: flex;
}

.lmr__sp {
  flex: 1;
  min-width: 0;
  padding-right: calc(var(--u) * 20);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
}

.lmr__sk {
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.76);
  color: var(--mute);
}

.lmr__sv {
  font-size: max(12px, calc(var(--u) * 22));
  white-space: nowrap;
}

.lmr__side {
  min-width: 0;
  padding: calc(var(--u) * 30);
  border-left: .5px solid var(--lm-hair);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: calc(var(--u) * 14);
}

.lmr__pr {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.lmr__mo {
  font-size: max(12px, calc(var(--u) * 40));
  color: var(--acc);
  white-space: nowrap;
}

.lmr__per {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--body);
}

.lmr__full {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

.lmr__ctas {
  display: flex;
  gap: calc(var(--u) * 8);
}

.lmr__cmp {
  flex: 1;
  height: calc(var(--u) * 52);
  border-radius: calc(var(--u) * 26);
  border: .5px solid var(--lm-hair);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.2);
  white-space: nowrap;
  cursor: pointer;
}

.lmr__cmp:hover {
  border-color: var(--acc);
}

.lmr__cmp[aria-pressed="true"] {
  border-color: var(--acc);
  background: var(--acc);
  color: #fff;
}

.lmr__cmp.is-full {
  opacity: .6;
  cursor: not-allowed;
}

.lmr__go {
  width: calc(var(--u) * 52);
  height: calc(var(--u) * 52);
  border-radius: 50%;
  background: var(--acc);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.lmr__go:hover {
  background: var(--acc-d);
  color: #fff;
}

/* Load more */
.lm__more {
  margin-top: calc(var(--u) * 60);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--u) * 18);
}

.lm__btn {
  width: 100%;
  height: calc(var(--u) * 96);
  border-radius: calc(var(--u) * 48);
  border: .5px solid var(--line2);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 16));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 3.2);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--u) * 22);
  cursor: pointer;
  transition: border-color .25s, background-color .25s, color .25s;
}

.lm__btn:hover {
  border-color: var(--acc);
  background: var(--lm-hover);
  color: var(--acc);
}

.lm__bd {
  width: calc(var(--u) * 52);
  height: calc(var(--u) * 52);
  border-radius: 50%;
  background: var(--acc);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: max(12px, calc(var(--u) * 18));
}

.lm__btn.is-loading .lm__bd {
  animation: lm-spin .8s linear infinite;
}

@keyframes lm-spin {
  to { transform: rotate(360deg); }
}

.lm__shown {
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.08);
  color: var(--mute);
}

.lm__ink {
  color: var(--ink);
}

.lm__track {
  width: calc(var(--u) * 320);
  height: 3px;
  border-radius: 2px;
  background: var(--line2);
  overflow: hidden;
}

.lm__bar {
  display: block;
  height: 100%;
  background: var(--acc);
  transition: width .4s;
}

.lm__fab {
  display: none;
}

@media (prefers-reduced-motion: reduce) {
  .lm__btn.is-loading .lm__bd {
    animation: none;
  }
}

/* == 105. Listing Map v1 — smaller screens ============================= */
@media (max-width: 1599px) {
  .lm.is-map .lm__map {
    flex-basis: calc(45% - calc(var(--u) * 18));
  }

  .lm.is-map .lm__grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 1199px) {
  /* the map becomes a full-screen layer behind a floating Map / List button */
  .lm.is-map .lm__map {
    display: none;
  }

  .lm.is-map.is-full .lm__map {
    position: fixed;
    inset: 0;
    z-index: 1500;
    height: auto;
    border-radius: 0;
    display: block;
  }

  .lm.is-map .lm__fab {
    position: fixed;
    left: 50%;
    bottom: 20px;
    z-index: 1600;
    height: 52px;
    padding: 0 26px;
    border: 0;
    border-radius: 26px;
    background: var(--ink);
    color: var(--on-ink);
    font: inherit;
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: .14em;
    box-shadow: 0 12px 30px rgba(17, 20, 24, .3);
    transform: translateX(-50%);
    display: block;
    cursor: pointer;
  }

  .lm__body {
    display: block;
  }

  .lm.is-map .lm__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .lmr {
    grid-template-columns: minmax(0, 1fr);
  }

  .lmr__ph {
    height: auto;
    aspect-ratio: 440 / 260;
  }

  .lmr__side {
    border-left: 0;
    border-top: .5px solid var(--lm-hair);
  }

  .lm__more {
    margin-top: 40px;
  }

  .lm__btn {
    height: 72px;
  }

  .lm__track {
    width: min(320px, 80%);
  }
}

@media (max-width: 767px) {
  /* the count chip moves up, clear of the attribution */
  .lm__count {
    top: 16px;
    bottom: auto;
    left: 16px;
  }

  .lm.is-map .lm__grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .lmr__name {
    font-size: 28px;
  }

  .lmr__specs {
    flex-wrap: wrap;
    gap: 10px 0;
  }

  .lmr__sp {
    flex-basis: 50%;
  }

  .lm__btn {
    font-size: 13px;
    letter-spacing: .14em;
  }
}

/* == 106. Listing Map v2 — command bar ================================= */
