.lsg-hr.is-today .lsg-hr__today {
  display: inline;
}

.lsg-store__acts {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: calc(var(--u) * 10);
}

.lsg-store__acts .lsg-btn {
  height: calc(var(--u) * 68);
  padding: 0 calc(var(--u) * 16);
  font-size: max(12px, calc(var(--u) * 13));
  letter-spacing: calc(var(--u) * 1.82);
}

.lsg-store__acts .lsg-btn--wide {
  grid-column: 1 / 3;
  height: calc(var(--u) * 80);
  font-size: max(12px, calc(var(--u) * 15));
  letter-spacing: calc(var(--u) * 2.4);
}

.lsg-dlv {
  margin-top: auto;
  padding: calc(var(--u) * 24) calc(var(--u) * 26);
  border-radius: calc(var(--u) * 24);
  background: var(--sg-chip);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 20);
}

.lsg-dlv__ic {
  width: calc(var(--u) * 52);
  height: calc(var(--u) * 52);
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--surf);
  color: var(--acc);
  display: flex;
  align-items: center;
  justify-content: center;
}

.lsg-dlv__txt {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.lsg-dlv__t {
  font-size: max(12px, calc(var(--u) * 19));
}

.lsg-dlv__d {
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--body);
}

/* similar cars */
.lsg-sims {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: calc(var(--u) * 30);
}

.lsg-sc__a {
  height: 100%;
  border-radius: calc(var(--u) * 36);
  border: .5px solid var(--sg-ln);
  background: var(--surf);
  color: var(--ink);
  text-decoration: none;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color .25s;
}

.lsg-sc__a:hover {
  border-color: var(--acc);
}

.lsg-sc__ph {
  position: relative;
  height: calc(var(--u) * 340);
  background: var(--stripes);
  display: block;
}

.lsg-sc__ph img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.lsg-sc__m {
  position: absolute;
  left: calc(var(--u) * 20);
  top: calc(var(--u) * 20);
  height: calc(var(--u) * 32);
  padding: 0 calc(var(--u) * 14);
  border-radius: calc(var(--u) * 16);
  background: var(--surf);
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.54);
  display: flex;
  align-items: center;
}

.lsg-sc__b {
  padding: calc(var(--u) * 30) calc(var(--u) * 32) calc(var(--u) * 32);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.lsg-sc__meta {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.16);
  color: var(--mute);
}

.lsg-sc__n {
  font-size: max(12px, calc(var(--u) * 32));
  letter-spacing: -.02em;
}

.lsg-sc__p {
  margin-top: calc(var(--u) * 10);
  padding-top: calc(var(--u) * 20);
  border-top: .5px solid var(--sg-ln);
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: calc(var(--u) * 12);
}

.lsg-sc__mo {
  font-size: max(12px, calc(var(--u) * 32));
  color: var(--acc);
}

.lsg-sc__per {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--body);
}

.lsg-sc__c {
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--mute);
}

/* sticky bar: slides in once the hero has left the screen */
.lsg-stk {
  position: fixed;
  left: 0;
  right: 0;
  top: 0;
  z-index: 60;
  transform: translateY(-110%);
  transition: transform .35s var(--lx-ease);
}

.lsg-stk.is-on {
  transform: translateY(0);
}

.lsg-stk__in {
  height: calc(var(--u) * 104);
  padding: 0 var(--gut);
  border-bottom: .5px solid var(--sg-ln);
  background: var(--surf);
  box-shadow: var(--sg-stk-shadow);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 30);
}

.lsg-stk__th {
  width: calc(var(--u) * 120);
  height: calc(var(--u) * 68);
  flex-shrink: 0;
  border-radius: calc(var(--u) * 14);
  object-fit: cover;
}

.lsg-stk__t {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.lsg-stk__n {
  font-size: max(12px, calc(var(--u) * 28));
  letter-spacing: -.02em;
}

.lsg-stk__m {
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.08);
  color: var(--mute);
}

.lsg-stk__p {
  margin-left: auto;
  display: flex;
  align-items: baseline;
  gap: calc(var(--u) * 14);
  white-space: nowrap;
}

.lsg-stk__mo {
  font-size: max(12px, calc(var(--u) * 40));
  color: var(--acc);
}

.lsg-stk__per {
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--body);
}

.lsg-stk__c {
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--mute);
}

.lsg-stk .lsg-stk__b {
  height: calc(var(--u) * 64);
  padding: 0 calc(var(--u) * 30);
  font-size: max(12px, calc(var(--u) * 14));
  letter-spacing: calc(var(--u) * 1.96);
}

.lsg-stk .lsg-btn--acc {
  padding: 0 calc(var(--u) * 34);
}

/* lightbox */
.lsg-box {
  width: 100vw;
  max-width: none;
  height: 100vh;
  max-height: none;
  margin: 0;
  padding: 0;
  border: 0;
  background: var(--sg-box);
  color: #fff;
}

.lsg-box::backdrop {
  background: var(--sg-box);
}

.lsg-box[open] {
  display: flex;
  align-items: center;
  justify-content: center;
}

.lsg-box__img {
  width: min(92vw, 138vh);
  height: auto;
  max-height: 86vh;
  object-fit: contain;
}

.lsg-box__slot {
  width: min(92vw, 138vh);
  aspect-ratio: 3 / 2;
  max-height: 86vh;
  border-radius: 20px;
  background: repeating-linear-gradient(135deg, #20242a 0 14px, #181b20 14px 28px);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: ui-monospace, Menlo, monospace;
  font-size: 14px;
  color: var(--sg-band-mute);
}

.lsg-box__cnt {
  position: absolute;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: .14em;
  white-space: nowrap;
}

.lsg-box__x {
  position: absolute;
  right: 20px;
  top: 20px;
  width: 52px;
  height: 52px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: var(--sg-white18);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.lsg-box__x .ico {
  width: 24px;
  height: 24px;
}

.lsg-box .lsg-arw {
  position: absolute;
  top: 50%;
  width: 56px;
  height: 56px;
  margin-top: -28px;
  font-size: 20px;
}

.lsg-box__prev {
  left: 20px;
}

.lsg-box__next {
  right: 20px;
}

/* the prototype leaves these at the browser's regular weight */
.lsg-pill,
.lsg-glass,
.lsg-arw,
.lsg-info__cust,
.lsg-price__unit,
.lsg-rnd,
.lsg-adv__r,
.lsg-adv__chat,
.lsg-spec__u,
.lsg-h__n,
.lsg-h__go,
.lsg-q__by,
.lsg-hi__n,
.lsg-more,
.lsg-band__ghost,
.lsg-band__lbl,
.lsg-score__n,
.lsg-band__pdf,
.lsg-tl__m,
.lsg-vin,
.lsg-fcard,
.lsg-map__youtag,
.lsg-you__tag,
.lsg-map__chip,
.lsg-store__acts .lsg-btn--out,
.lsg-sc__m {
  font-weight: 400;
}

.lsg-fcard .lsg-seg__b,
.lsg-fcard .lsg-trade,
.lsg-sums dd {
  font-weight: 300;
}

