/* == 114. Listing Single v2 — shared =================================== */
/* Tokens, the section header, .lsg-e / .lsg-s and the lightbox come from 30-listing-single.css. */
:root {
  --sv-glass: rgba(17, 20, 24, .6);
  --sv-glass80: rgba(17, 20, 24, .8);
  --sv-card: rgba(14, 15, 18, .62);
  --sv-w14: rgba(255, 255, 255, .14);
  --sv-w18: rgba(255, 255, 255, .18);
  --sv-w20: rgba(255, 255, 255, .2);
  --sv-w40: rgba(255, 255, 255, .4);
  --sv-w55: rgba(255, 255, 255, .55);
  --sv-w60: rgba(255, 255, 255, .6);
  --sv-w70: rgba(255, 255, 255, .7);
  --sv-w85: rgba(255, 255, 255, .85);
  --sv-shade: linear-gradient(180deg, rgba(9, 10, 12, .35) 0%, rgba(9, 10, 12, 0) 22%, rgba(9, 10, 12, 0) 45%, rgba(9, 10, 12, .88) 100%);
  --sv-more: rgba(17, 20, 24, .66);
  --sv-ok12: rgba(47, 163, 107, .12);
  --sv-ok25: rgba(47, 163, 107, .25);
  --sv-c10: rgba(242, 243, 245, .1);
  --sv-c12: rgba(242, 243, 245, .12);
  --sv-c22: rgba(242, 243, 245, .22);
  --sv-trade1: #262a31;
  --sv-trade2: #1f2228;
  --sv-acc55: rgba(216, 71, 14, .55);
  /* the Serpent is shot on white: a deeper shade keeps the white title readable */
  --sv-shade-light: linear-gradient(180deg, rgba(9, 10, 12, .35) 0%, rgba(9, 10, 12, 0) 18%, rgba(9, 10, 12, .2) 40%, rgba(9, 10, 12, .78) 68%, rgba(9, 10, 12, .92) 100%);
}

[data-skin="green"] {
  --sv-acc55: rgba(18, 132, 79, .55);
}

.lsv-hero,
.lsv-nav,
.lsv-sec {
  font-weight: 400;
}

.lsv .lsg-h__r {
  font-weight: 300;
}

.lsv-sec {
  padding-top: calc(var(--u) * 110);
  scroll-margin-top: calc(var(--u) * 100);
}

/* == 115. Listing Single v2 — hero and section nav ===================== */
.lsv-hero {
  position: relative;
  height: calc(var(--u) * 1240);
  margin: calc(var(--u) * 20) calc(var(--u) * 20) 0;
  border-radius: calc(var(--u) * 44);
  overflow: hidden;
  background: #111317;
  color: #fff;
}

.lsv-hero__bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 55%;
}

.lsv-hero__shade {
  position: absolute;
  inset: 0;
  background: var(--sv-shade);
}

:root:not([data-skin]) .lsv-hero__shade {
  background: var(--sv-shade-light);
}

.lsv-hero__tl,
.lsv-hero__tr {
  position: absolute;
  top: calc(var(--u) * 50);
  display: flex;
  gap: calc(var(--u) * 8);
}

.lsv-hero__tl {
  left: calc(var(--u) * 60);
}

.lsv-hero__tr {
  right: calc(var(--u) * 60);
}

.lsv-pill {
  height: calc(var(--u) * 44);
  padding: 0 calc(var(--u) * 18);
  border-radius: calc(var(--u) * 22);
  background: var(--sv-glass);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
