/* == 121. Listing Single v3 — split and stage ========================== */
/* Shared pieces: tokens and .lsg-e / .lsg-s (30), the condition rows, range, ribbon and lightbox (31). */
:root {
  --st-l14: rgba(17, 20, 24, .14);
  --st-l30: rgba(17, 20, 24, .3);
  --st-bar-shadow: 0 -14px 40px rgba(17, 20, 24, .08);
  --st-w25: rgba(255, 255, 255, .25);
  --st-w35: rgba(255, 255, 255, .35);
  --st-glass: rgba(17, 20, 24, .66);
}

[data-theme="dark"] {
  --st-l14: rgba(242, 243, 245, .14);
  --st-l30: rgba(242, 243, 245, .3);
  --st-bar-shadow: 0 -14px 40px rgba(0, 0, 0, .35);
}

.lst-stage,
.lst-col,
.lst-bar {
  font-weight: 400;
}

.lst {
  margin-top: calc(var(--u) * 24);
  display: grid;
  grid-template-columns: calc(var(--u) * 1400) minmax(0, 1fr);
  gap: calc(var(--u) * 80);
  align-items: start;
}

/* the stage ends just above the fixed bar: viewport − 40 − 112 on the artboard */
.lst-stage {
  position: sticky;
  top: calc(var(--u) * 20);
  height: calc(100vh - calc(var(--u) * 152));
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.lst-media {
  position: relative;
  flex: 1;
  min-height: 0;
  border-radius: calc(var(--u) * 40);
  overflow: hidden;
  background: #111317;
}

.lst-layers {
  position: absolute;
  inset: 0;
}

.lst-layer {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transform: scale(1.04);
  transition: opacity .7s ease, transform 1.2s var(--lx-ease);
}

.lst-layer.is-on {
  opacity: 1;
  transform: scale(1);
}

/* the condition map: the side photo in a 3:2 box on dark, points by % */
.lst-cmap {
  position: absolute;
  inset: 0;
