  cursor: pointer;
  transition: background .25s, color .25s;
}

.js-s3-tier {
  font-size: max(12px, calc(var(--u) * 15));
}

.lst-seg__b.is-on {
  background: var(--ink);
  color: var(--on-ink);
}

.lst-trade {
  padding: calc(var(--u) * 20) calc(var(--u) * 22);
  border-radius: calc(var(--u) * 24);
  border: .5px solid var(--line2);
  background: var(--sg-chip);
  color: var(--ink);
  font: inherit;
  text-align: left;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 16);
  cursor: pointer;
}

.lst-trade[aria-pressed="true"] {
  border-color: var(--acc);
}

.lst-trade__txt {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.lst-trade__t {
  font-size: max(12px, calc(var(--u) * 19));
  font-weight: 300;
}

.lst-trade__d {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--body);
}

.lst-trade__sw {
  width: calc(var(--u) * 60);
  height: calc(var(--u) * 34);
  margin-left: auto;
  padding: calc(var(--u) * 3);
  flex-shrink: 0;
  border-radius: calc(var(--u) * 17);
  background: var(--line2);
  display: flex;
  transition: background .25s;
}

.lst-trade__sw span {
  width: calc(var(--u) * 28);
  height: calc(var(--u) * 28);
  border-radius: 50%;
  background: #fff;
  transition: transform .25s;
}

.lst-trade[aria-pressed="true"] .lst-trade__sw {
  background: var(--acc);
}

.lst-trade[aria-pressed="true"] .lst-trade__sw span {
  transform: translateX(calc(var(--u) * 26));
}

.lst-cta {
  height: calc(var(--u) * 80);
  border-radius: calc(var(--u) * 40);
  background: var(--acc);
  color: #fff;
  font-size: max(12px, calc(var(--u) * 15));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.4);
  text-decoration: none;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: filter .25s;
}

.lst-cta:hover {
  filter: brightness(1.08);
}

/* pickup or delivery: real radios, the card is the label */
.lst-dels {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.lst-dels li {
  position: relative;
}

.lst-del__in {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.lst-del {
  padding: calc(var(--u) * 30) calc(var(--u) * 32);
  border-radius: calc(var(--u) * 30);
  border: .5px solid var(--st-l14);
  background: var(--surf);
  display: flex;
  align-items: flex-start;
  gap: calc(var(--u) * 22);
  cursor: pointer;
  transition: border-color .25s;
}

.lst-del__in:checked + .lst-del {
  border: 1.5px solid var(--acc);
}

.lst-del__in:focus-visible + .lst-del {
  outline: 2px solid var(--acc);
  outline-offset: 3px;
}

.lst-del__r {
  width: calc(var(--u) * 30);
  height: calc(var(--u) * 30);
  margin-top: calc(var(--u) * 4);
  flex-shrink: 0;
  border-radius: 50%;
  border: 1.5px solid var(--st-l30);
  display: flex;
  align-items: center;
  justify-content: center;
}

.lst-del__r span {
  width: calc(var(--u) * 14);
  height: calc(var(--u) * 14);
  border-radius: 50%;
}

.lst-del__in:checked + .lst-del .lst-del__r {
  border-color: var(--acc);
}

.lst-del__in:checked + .lst-del .lst-del__r span {
  background: var(--acc);
}

.lst-del__b {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 8);
}

.lst-del__top {
  display: flex;
  justify-content: space-between;
  gap: calc(var(--u) * 20);
  font-weight: 300;
}

.lst-del__t {
  font-size: max(12px, calc(var(--u) * 26));
}

.lst-del__p {
  font-size: max(12px, calc(var(--u) * 22));
}

.lst-del__p--ok {
  color: var(--ok);
}

.lst-del__d {
  font-size: max(12px, calc(var(--u) * 16));
  font-weight: 300;
  line-height: 1.5;
  color: var(--body);
}

.lst-del__w {
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.82);
  color: var(--mute);
}

/* == 123. Listing Single v3 — the fixed bar ============================ */
.lst-bar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 60;
  transform: translateY(110%);
  transition: transform .35s var(--lx-ease);
}

.lst-bar.is-on {
  transform: translateY(0);
}

.lst-bar__in {
  height: calc(var(--u) * 112);
  padding: 0 var(--gut);
  border-top: .5px solid var(--sg-ln);
  background: var(--surf);
  box-shadow: var(--st-bar-shadow);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 30);
}

.lst-bar__th {
  width: calc(var(--u) * 120);
  height: calc(var(--u) * 72);
  flex-shrink: 0;
  border-radius: calc(var(--u) * 14);
  object-fit: cover;
}

.lst-bar__t {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.lst-bar__n {
  font-size: max(12px, calc(var(--u) * 26));
  font-weight: 300;
  letter-spacing: -.02em;
}

.lst-bar__m {
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.08);
  color: var(--mute);
}

.lst-bar__div {
  width: .5px;
  height: calc(var(--u) * 50);
  flex-shrink: 0;
  background: var(--line2);
}

.lst-bar__p {
  display: flex;
  align-items: baseline;
  gap: calc(var(--u) * 12);
  white-space: nowrap;
}

.lst-bar__mo {
  font-size: max(12px, calc(var(--u) * 40));
  font-weight: 300;
  color: var(--acc);
}

.lst-bar__per {
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--body);
}

.lst-bar__chip {
  height: calc(var(--u) * 44);
  padding: 0 calc(var(--u) * 18);
  border-radius: calc(var(--u) * 22);
  background: var(--sg-chip);
  font-size: max(12px, calc(var(--u) * 14));
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.lst-bar__acts {
  margin-left: auto;
  display: flex;
  gap: calc(var(--u) * 10);
}

.lst-bar__td,
.lst-bar__res {
  height: calc(var(--u) * 68);
  border-radius: calc(var(--u) * 34);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.96);
  white-space: nowrap;
  text-decoration: none;
  display: flex;
  align-items: center;
  cursor: pointer;
  transition: background .25s, border-color .25s, color .25s;
}

.lst-bar__td {
  padding: 0 calc(var(--u) * 30);
  border: .5px solid var(--line2);
  color: var(--ink);
}

.lst-bar__td:hover {
  border-color: var(--acc);
  color: var(--acc);
}

.lst-bar__res {
  padding: 0 calc(var(--u) * 40);
  border: 0;
  background: var(--acc);
  color: #fff;
}

/* == 124. Listing Single v3 — smaller screens ========================== */
@media (max-width: 1599px) and (min-width: 1200px) {
  /* the stage takes half the width; the thumbnails go (the mini-shots stay) */
  .lst {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: calc(var(--u) * 60);
  }

  .lst-thumbs {
    display: none;
  }

  .lst-trust {
    flex-wrap: wrap;
    justify-content: flex-start;
    gap: 6px 16px;
  }

  .lst-bar__chip,
  .lst-bar__div {
    display: none;
  }
}

@media (max-width: 1199px) {
  /* no split: the stage sticks to the top as a 3:2 strip and still follows the reading */
  .lst {
    margin-top: 16px;
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }

  .lst-stage {
    top: 0;
    z-index: 5;
    height: auto;
    margin: 0 calc(-1 * var(--gut));
    padding: 8px var(--gut);
    background: var(--bg);
  }

  .lst-media {
    flex: none;
    height: min(62vw, 42vh);
    border-radius: 20px;
  }

  .lst-thumbs {
    display: none;
  }

  .lst-tag {
    left: 12px;
    top: 12px;
    height: 32px;
    padding: 0 12px;
    gap: 8px;
  }

  .lst-tr {
    right: 12px;
    top: 12px;
  }

  .lst-glass {
    height: 32px;
    padding: 0 12px;
  }

  .js-s3-spin {
    display: none;
  }

  .lst-prog {
    left: 12px;
    right: 12px;
    bottom: 12px;
  }

  .lst-spot {
    width: 30px;
    height: 30px;
    font-size: 13px;
    box-shadow: 0 0 0 5px var(--acc-a25);
  }

  .lst-spot--ok {
    box-shadow: 0 0 0 5px var(--sv-ok25);
  }

  .lst-spot.is-on {
    border-width: 2px;
  }

  .lst-col {
    padding-top: 24px;
  }

  .lst-sec {
    padding-bottom: 64px;
    scroll-margin-top: calc(min(62vw, 42vh) + 24px);
  }

  .lst-h1 {
    font-size: 110px;
  }

  .lst-pcard,
  .lst-fin {
    padding: 28px;
    border-radius: 24px;
  }

  .lst-pcard__v {
    font-size: 64px;
  }

  .lst-trust {
    flex-wrap: wrap;
    justify-content: flex-start;
    gap: 8px 20px;
  }

  .lst-h2 {
    font-size: 40px;
  }

  .lst-big__v {
    font-size: 56px;
  }

  .lst-fin__v {
    font-size: 80px;
  }

  /* the bar keeps price and Reserve */
  .lst-bar__in {
    height: auto;
    padding: 12px var(--gut);
    gap: 16px;
  }

  .lst-bar__th,
  .lst-bar__t,
  .lst-bar__div,
  .lst-bar__chip,
  .lst-bar__td {
    display: none;
  }

  .lst-bar__mo {
    font-size: 24px;
  }

  .lst-bar__res {
    height: 48px;
    padding: 0 20px;
    font-size: 12px;
  }

  .lst-page ~ .ft {
    margin-bottom: 72px;
  }
}

@media (max-width: 767px) {
  .lst-media {
    border-radius: 16px;
  }

  .lst-tag__bar,
  .lst-tag__l {
    display: none;
  }

  .lst-h1 {
    font-size: min(72px, 19vw);
  }

  .lst-make {
    margin-top: 20px;
    font-size: 26px;
  }

  .lst-pcard,
  .lst-fin {
    padding: 22px 18px;
  }

  .lst-pcard__row {
    flex-direction: column;
    align-items: flex-start;
  }

  .lst-pcard__cash {
    align-items: flex-start;
  }

  .lst-pcard__v {
    font-size: 52px;
  }

  .lst-pcard__acts {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) 56px;
  }

  .lst-res,
  .lst-out,
  .lst-fav {
    height: 56px;
    font-size: 12px;
  }

  .lst-fav {
    font-size: 18px;
  }

  .lst-trust {
    flex-direction: column;
  }

  .lst-hi {
    grid-template-columns: minmax(0, 1fr);
  }

  .lst-hi__t {
    padding: 18px;
  }

  .lst-h2 {
    font-size: 30px;
  }

  .lst-p {
    font-size: 17px;
  }

  .lst-row {
    font-size: 16px;
  }

  .lst-minis {
    flex-wrap: wrap;
  }

  .lst-mini {
    width: 120px;
    height: 80px;
  }

  .lst-big__t {
    padding: 18px;
  }

  .lst-big__v {
    font-size: 40px;
  }

  .lst-og__ul {
    grid-template-columns: minmax(0, 1fr);
  }

  .lst-tl__i {
    grid-template-columns: 56px 20px minmax(0, 1fr);
    gap: 12px;
  }

  .lst-tl__y {
    font-size: 18px;
  }

  .lst-tl__t {
    font-size: 18px;
  }

  .lst-ck {
    white-space: normal;
  }

  .lst-vin {
    flex-wrap: wrap;
  }

  .lst-vin__v {
    font-size: 15px;
  }

  /* BBH Bartle is wide: six glyphs take about 6.3em */
  .lst-fin__v {
    font-size: min(56px, 12vw);
  }

  .lst-seg__b {
    height: 44px;
    font-size: 13px;
  }

  .lst-del {
    padding: 20px;
    gap: 14px;
  }

  .lst-del__t {
    font-size: 20px;
  }

  .lst-del__p {
    font-size: 18px;
  }
}

/* == 125. Listing Single v4 — title and bento ========================== */
/* Shared: tokens, .lsg-h, .lsg-e / .lsg-s (30), range, pdf button and lightbox (31). */
:root {
  --sx-glass: rgba(17, 20, 24, .66);
  --sx-w50: rgba(255, 255, 255, .5);
  --sx-ok14: rgba(47, 163, 107, .14);
  --sx-deal: linear-gradient(90deg, #2fa36b 0%, #9cc94a 35%, #e0b23a 60%, #d8573a 100%);
  --sx-slot1: #eceef1;
  --sx-slot2: #f5f6f8;
}

[data-theme="dark"] {
  --sx-slot1: #1c1f24;
  --sx-slot2: #16181c;
}

.lsx-title,
.lsx-bento,
.lsx-sec,
.lsx-mbar {
  font-weight: 400;
}

.lsx .lsg-h__r {
  font-weight: 300;
}

.lsx-sec {
  padding-top: calc(var(--u) * 100);
  scroll-margin-top: calc(var(--u) * 20);
}

.lsx-h {
  padding-bottom: calc(var(--u) * 28);
  margin-bottom: calc(var(--u) * 40);
}

.lsx-h .lsg-h__t {
  font-size: max(12px, calc(var(--u) * 64));
}

.lsx-tile {
  min-width: 0;
  border-radius: calc(var(--u) * 32);
  background: var(--surf);
}

.lsx-k {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.16);
  color: var(--mute);
}

.lsx-link {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  color: var(--mute);
  text-decoration: none;
  transition: color .25s;
}

.lsx-link:hover {
  color: var(--acc);
}

.lsx-ink {
  color: var(--ink);
}

.lsx-ok {
  color: var(--ok);
}

/* title strip */
.lsx-title {
  margin-top: calc(var(--u) * 24);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: calc(var(--u) * 40);
}

.lsx-title__l {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.lsx-title__meta {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.34);
  color: var(--mute);
}

.lsx-avail {
  height: calc(var(--u) * 30);
  padding: 0 calc(var(--u) * 12);
  border-radius: calc(var(--u) * 15);
  background: var(--sx-ok14);
  color: var(--ok);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 8);
  letter-spacing: .14em;
}

.lsx-avail__dot {
  width: calc(var(--u) * 7);
  height: calc(var(--u) * 7);
  border-radius: 50%;
  background: var(--ok);
}

.lsx-h1 {
  font-size: max(12px, calc(var(--u) * 84));
  letter-spacing: -.05em;
  line-height: 1;
  white-space: nowrap;
}

.lsx-title__r {
  padding-bottom: calc(var(--u) * 6);
  display: flex;
  gap: calc(var(--u) * 10);
}

.lsx-pill,
.lsx-fav {
  height: calc(var(--u) * 60);
  padding: 0 calc(var(--u) * 24);
  border-radius: calc(var(--u) * 30);
  border: .5px solid var(--line2);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.82);
  white-space: nowrap;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--u) * 10);
  cursor: pointer;
  transition: background .25s, border-color .25s, color .25s;
}

.lsx-pill:hover {
  border-color: var(--acc);
}

.lsx-pill--cmp[aria-pressed="true"] {
  border-color: var(--acc);
  background: var(--acc);
  color: #fff;
}

.lsx-fav {
  width: calc(var(--u) * 60);
  padding: 0;
  border-radius: 50%;
  font-size: max(12px, calc(var(--u) * 20));
  letter-spacing: 0;
}

.lsx-fav[aria-pressed="true"] {
  border-color: var(--acc);
  color: var(--acc);
}

/* the bento: 12 columns, 7 rows of 150 */
.lsx-bento {
  margin-top: calc(var(--u) * 30);
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  grid-auto-rows: calc(var(--u) * 150);
  gap: calc(var(--u) * 16);
}

.lsx-photo {
  position: relative;
  grid-column: 1 / 8;
  grid-row: 1 / 7;
  border-radius: calc(var(--u) * 36);
  overflow: hidden;
  background: var(--stripes);
}

.lsx-photo__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  cursor: zoom-in;
}

.lsx-photo__img[hidden],
.lsx-photo__slot[hidden],
.lsx-eq__ul li.lsx-eq__more {
  display: none;
}

.lsx-eq.is-open .lsx-eq__ul li.lsx-eq__more {
  display: flex;
}

.lsx-photo__slot {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
  white-space: nowrap;
}

.lsx-glass {
  height: calc(var(--u) * 44);
  padding: 0 calc(var(--u) * 18);
  border: 0;
  border-radius: calc(var(--u) * 22);
  background: var(--sx-glass);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
  cursor: pointer;
}

button.lsx-glass:hover,
.lsx-glass[aria-pressed="true"] {
  background: var(--acc);
}

.lsx-photo__cnt {
  position: absolute;
  left: calc(var(--u) * 28);
  top: calc(var(--u) * 28);
  cursor: default;
}

.lsx-photo__num {
  font-family: ui-monospace, Menlo, monospace;
}

.lsx-photo__sep {
  opacity: .5;
}

.lsx-photo__tr {
  position: absolute;
  right: calc(var(--u) * 28);
  top: calc(var(--u) * 28);
  display: flex;
  gap: calc(var(--u) * 8);
}

.lsx-photo__foot {
  position: absolute;
  left: calc(var(--u) * 28);
  right: calc(var(--u) * 28);
  bottom: calc(var(--u) * 28);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 16);
}

.lsx-dots {
  display: flex;
  gap: calc(var(--u) * 8);
}

/* the Serpent is shot on white: the white dots sit on a dark glass pill */
:root:not([data-skin]) .lsx-dots {
  padding: calc(var(--u) * 14) calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
  background: var(--sx-glass);
}

.lsx-dot {
  width: calc(var(--u) * 8);
  height: 8px;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: var(--sx-w50);
  cursor: pointer;
  transition: width .3s, background .3s;
}

.lsx-dot.is-on {
  width: calc(var(--u) * 34);
  background: #fff;
}

.lsx-photo__nav {
  margin-left: auto;
  display: flex;
  gap: calc(var(--u) * 10);
}

.lsx-arw {
  width: calc(var(--u) * 60);
  height: calc(var(--u) * 60);
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: var(--surf);
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 20));
  cursor: pointer;
