/* == 127. Listing Single v4 — finance, equipment, history, next ======== */
.lsx-fin {
  padding: calc(var(--u) * 30) calc(var(--u) * 30) calc(var(--u) * 30) calc(var(--u) * 50);
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) minmax(0, .9fr) auto auto;
  gap: calc(var(--u) * 40);
  align-items: center;
}

.lsx-fin__dp {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

.lsx-fin__k {
  display: flex;
  justify-content: space-between;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.16);
  color: var(--mute);
}

.lsx-fin__val {
  font-size: max(12px, calc(var(--u) * 16));
  letter-spacing: calc(var(--u) * 0.32);
  color: var(--ink);
  white-space: nowrap;
}

.lsx-fin .lsv-range {
  margin: 2px 0;
}

.lsx-seg {
  padding: calc(var(--u) * 4);
  border-radius: calc(var(--u) * 30);
  background: var(--sg-chip);
  display: flex;
}

.lsx-seg__b {
  height: calc(var(--u) * 52);
  flex: 1;
  border: 0;
  border-radius: calc(var(--u) * 26);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 15));
  font-weight: 300;
  cursor: pointer;
  transition: background .25s, color .25s;
}

.lsx-seg__b--tier {
  font-size: max(12px, calc(var(--u) * 14));
}

.lsx-seg__b.is-on {
  background: var(--ink);
  color: var(--on-ink);
}

.lsx-fin__mo {
  display: flex;
  align-items: baseline;
  gap: calc(var(--u) * 10);
  white-space: nowrap;
}

.lsx-fin__v {
  font-family: "BBH Bartle", Geist, sans-serif;
  font-size: max(12px, calc(var(--u) * 64));
  line-height: .9;
  color: var(--acc);
}

.lsx-fin__per {
  font-size: max(12px, calc(var(--u) * 16));
  color: var(--body);
}

.lsx-fin__go {
  height: calc(var(--u) * 76);
  padding: 0 calc(var(--u) * 36);
  border-radius: calc(var(--u) * 38);
  background: var(--acc);
  color: #fff;
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.96);
  white-space: nowrap;
  text-decoration: none;
  display: flex;
  align-items: center;
  transition: filter .25s;
}

.lsx-fin__go:hover {
  filter: brightness(1.08);
}

/* equipment: a tile opens to the full width */
.lsx-eqs {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: calc(var(--u) * 16);
}

.lsx-eq {
  position: relative;
  padding: calc(var(--u) * 36) calc(var(--u) * 40);
  border: .5px solid transparent;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 22);
  transition: border-color .25s;
}

.lsx-eq.is-open {
  grid-column: 1 / -1;
  border-color: var(--acc);
}

.lsx-eq__b {
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-weight: 400;
  text-align: left;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 16);
  cursor: pointer;
}

/* the whole tile is the toggle */
.lsx-eq__b::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
}

.lsx-eq__n {
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 13));
  color: var(--acc);
}

.lsx-eq__t {
  font-size: max(12px, calc(var(--u) * 32));
  font-weight: 300;
  letter-spacing: -.02em;
}

.lsx-eq__c {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

.lsx-eq__m {
  width: calc(var(--u) * 46);
  height: calc(var(--u) * 46);
  margin-left: auto;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--sg-chip);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 20));
  display: flex;
  align-items: center;
  justify-content: center;
}

.lsx-eq__minus,
.lsx-eq.is-open .lsx-eq__plus {
  display: none;
}

.lsx-eq.is-open .lsx-eq__minus {
  display: inline;
}

.lsx-eq.is-open .lsx-eq__m {
  background: var(--acc);
  color: #fff;
}

.lsx-eq__ul {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  column-gap: calc(var(--u) * 30);
}

.lsx-eq.is-open .lsx-eq__ul {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.lsx-eq__ul li {
  padding: calc(var(--u) * 14) 0;
  border-top: .5px solid var(--sg-ln);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
  font-size: max(12px, calc(var(--u) * 17));
  font-weight: 300;
}

.lsx-eq__ul .acc {
  display: flex;
}

.lsx-specwrap {
  grid-column: 1 / -1;
  padding: calc(var(--u) * 14) calc(var(--u) * 44);
}

.lsx-specs {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  column-gap: calc(var(--u) * 50);
}

.lsx-specs__r {
  padding: calc(var(--u) * 20) 0;
  border-bottom: .5px solid var(--sg-ln);
  display: flex;
  justify-content: space-between;
  gap: calc(var(--u) * 20);
  font-size: max(12px, calc(var(--u) * 17));
  font-weight: 300;
}

.lsx-specs__r dt {
  color: var(--mute);
}

.lsx-specs__r dd {
  text-align: right;
}

/* history */
.lsx-hist {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr);
  gap: calc(var(--u) * 16);
}

.lsx-tlwrap {
  padding: calc(var(--u) * 44) calc(var(--u) * 50);
}

.lsx-tl {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: calc(var(--u) * 24);
}

.lsx-tl::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: calc(var(--u) * 60);
  height: .5px;
  background: var(--line2);
}

.lsx-tl__i {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

.lsx-tl__y {
  font-size: max(12px, calc(var(--u) * 34));
  font-weight: 300;
  letter-spacing: -.03em;
  line-height: 1;
}

.lsx-tl__dot {
  width: calc(var(--u) * 16);
  height: calc(var(--u) * 16);
  margin: calc(var(--u) * 8) 0;
  border-radius: 50%;
  border: 1.5px solid var(--line2);
  background: var(--surf);
  box-shadow: 0 0 0 calc(var(--u) * 6) var(--surf);
}

.lsx-tl__t {
  font-size: max(12px, calc(var(--u) * 20));
  font-weight: 300;
}

.lsx-tl__d {
  font-size: max(12px, calc(var(--u) * 14));
  line-height: 1.5;
  color: var(--body);
}

.lsx-tl__m {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.44);
  color: var(--mute);
}

.lsx-tl__i.is-now .lsx-tl__y {
  color: var(--acc);
}

.lsx-tl__i.is-now .lsx-tl__dot {
  border-color: var(--acc);
  background: var(--acc);
}

.lsx-ckwrap {
  padding: calc(var(--u) * 30) calc(var(--u) * 40);
  display: flex;
  flex-direction: column;
}

.lsx-ck {
  padding: calc(var(--u) * 14) 0;
  border-bottom: .5px solid var(--sg-ln);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
}

.lsx-ck__k {
  font-size: max(12px, calc(var(--u) * 17));
  font-weight: 300;
}

.lsx-ck__v {
  margin-left: auto;
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--mute);
}

.lsx-vin {
  padding-top: calc(var(--u) * 18);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
}

.lsx-vin__v {
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 17));
  letter-spacing: calc(var(--u) * 1.02);
  overflow-wrap: anywhere;
}

.lsx-vin__copy {
  height: calc(var(--u) * 44);
  margin-left: auto;
  padding: 0 calc(var(--u) * 18);
  flex-shrink: 0;
  border-radius: calc(var(--u) * 22);
  border: .5px solid var(--line2);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  cursor: pointer;
}

.lsx-vin__copy.is-done {
  color: var(--ok);
}

/* your next step */
.lsx-next {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: calc(var(--u) * 16);
}

.lsx-card {
  min-width: 0;
  padding: calc(var(--u) * 50);
  border-radius: calc(var(--u) * 32);
  background: var(--surf);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 26);
}

.lsx-card--ink {
  border-radius: calc(var(--u) * 36);
  background: var(--sg-band);
  color: var(--sg-on-band);
}

.lsx-card__top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.lsx-card__eb {
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.34);
  color: var(--mute);
}

.lsx-card--ink .lsx-card__eb {
  color: var(--sg-band-mute);
}

.lsx-card__l {
  font-family: "BBH Bartle", Geist, sans-serif;
  font-size: max(12px, calc(var(--u) * 44));
  color: var(--acc);
}

.lsx-card__t {
  font-size: max(12px, calc(var(--u) * 48));
  letter-spacing: -.03em;
  line-height: 1.05;
}

.lsx-card__d {
  font-size: max(12px, calc(var(--u) * 17));
  font-weight: 300;
  line-height: 1.5;
  color: var(--body);
}

.lsx-card--ink .lsx-card__d {
  color: var(--sg-band-body);
}

.lsx-a {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.lsx-a li {
  display: flex;
  gap: calc(var(--u) * 14);
  font-size: max(12px, calc(var(--u) * 16));
  font-weight: 300;
  color: #d9dce1;
}

.lsx-a__n {
  font-family: ui-monospace, Menlo, monospace;
  color: var(--acc);
}

.lsx-card__cta {
  height: calc(var(--u) * 80);
  margin-top: auto;
  border: 0;
  border-radius: calc(var(--u) * 40);
  background: var(--acc);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.24);
  white-space: nowrap;
  text-decoration: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background .25s, filter .25s;
}

a.lsx-card__cta:hover {
  filter: brightness(1.08);
}

.lsx-slots {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: calc(var(--u) * 8);
}

.lsx-slot {
  height: calc(var(--u) * 66);
  border-radius: calc(var(--u) * 20);
  border: .5px solid var(--line2);
  background: transparent;
  color: var(--ink);
  font: inherit;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: calc(var(--u) * 2);
  cursor: pointer;
  transition: background .25s, border-color .25s, color .25s;
}

.lsx-slot.is-on {
  border-color: var(--acc);
  background: var(--acc);
  color: #fff;
}

.lsx-slot__d {
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.54);
  opacity: .75;
}

.lsx-slot__h {
  font-size: max(12px, calc(var(--u) * 18));
  font-weight: 300;
}

.lsx-qs {
  display: flex;
  flex-wrap: wrap;
  gap: calc(var(--u) * 8);
}

.lsx-q {
  height: calc(var(--u) * 50);
  padding: 0 calc(var(--u) * 18);
  border-radius: calc(var(--u) * 25);
  border: .5px solid var(--line2);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 15));
  font-weight: 300;
  cursor: pointer;
  transition: background .25s, border-color .25s, color .25s;
}

.lsx-q.is-on {
  border-color: var(--acc);
  background: var(--acc-a10);
  color: var(--acc);
}

.lsx-ask {
  height: calc(var(--u) * 80);
  margin-top: auto;
  padding: 0 calc(var(--u) * 10) 0 calc(var(--u) * 28);
  border-radius: calc(var(--u) * 40);
  background: var(--sg-chip);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.lsx-ask__in {
  min-width: 0;
  flex: 1;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 17));
  font-weight: 300;
  outline: 0;
}

.lsx-ask__in::placeholder {
  color: var(--mute);
}

.lsx-ask:focus-within {
  box-shadow: 0 0 0 2px var(--acc);
}

.lsx-ask__go {
  width: calc(var(--u) * 60);
  height: calc(var(--u) * 60);
  padding: 0;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: var(--acc);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 20));
  cursor: pointer;
}

/* the bottom bar exists below 1200 px only */
.lsx-mbar {
  display: none;
}

/* == 128. Listing Single v4 — smaller screens ========================== */
@media (max-width: 1599px) and (min-width: 1200px) {
  /* the bento turns into 6 columns: photo, price + deal, inspection + advisor, stats 3 × 2 */
  .lsx-bento {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }

  .lsx-photo {
    grid-column: 1 / -1;
    grid-row: 1 / 6;
  }

  .lsx-price {
    grid-column: 1 / 4;
    grid-row: 6 / 9;
  }

  .lsx-deal {
    grid-column: 4 / 7;
    grid-row: 6 / 9;
  }

  .lsx-insp {
    grid-column: 1 / 3;
    grid-row: 9 / 11;
  }

  .lsx-adv {
    grid-column: 3 / 7;
    grid-row: 9 / 11;
  }

  .lsx-stat {
    grid-row: auto;
  }

  .lsx-ph,
  .lsx-cost {
    grid-template-columns: minmax(0, 1fr);
  }

  .lsx-cmpwrap {
    overflow-x: auto;
  }

  .lsx-cmp {
    min-width: 1100px;
  }

  .lsx-cmp__k {
    position: sticky;
    left: 0;
    z-index: 1;
    background: var(--surf);
  }

  .lsx-fin {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .lsx-eqs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .lsx-specs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1199px) {
  .lsx-sec {
    padding-top: 64px;
  }

  .lsx-h .lsg-h__t {
    font-size: 40px;
  }

  .lsx-title {
    margin-top: 16px;
    flex-direction: column;
    align-items: flex-start;
    gap: 18px;
  }

  .lsx-title__meta {
    flex-wrap: wrap;
  }

  .lsx-h1 {
    font-size: 48px;
    white-space: normal;
  }

  .lsx-tile,
  .lsx-card {
    border-radius: 24px;
  }

  .lsx-bento {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-auto-rows: auto;
    gap: 12px;
  }

  .lsx-photo,
  .lsx-price,
  .lsx-adv {
    grid-column: 1 / -1;
    grid-row: auto;
  }

  .lsx-photo {
    aspect-ratio: 3 / 2;
    border-radius: 24px;
  }

  .lsx-price {
    padding: 28px;
  }

  .lsx-price__v {
    font-size: 72px;
  }

  .lsx-deal,
  .lsx-insp {
    grid-column: auto;
    grid-row: auto;
    padding: 24px;
  }

  .lsx-adv {
    padding: 18px 24px;
    flex-wrap: wrap;
  }

  .lsx-stat {
    grid-column: auto;
    grid-row: auto;
    padding: 18px 20px;
    gap: 10px;
  }

  .lsx-stat__v {
    font-size: 32px;
  }

  .lsx-ph,
  .lsx-cost,
  .lsx-hist,
  .lsx-next {
    grid-template-columns: minmax(0, 1fr);
  }

  .lsx-chart,
  .lsx-dem,
  .lsx-run,
  .lsx-lines,
  .lsx-tlwrap,
  .lsx-card {
    padding: 28px;
  }

  .lsx-ch {
    height: 260px;
  }

  .lsx-cmpwrap {
    overflow-x: auto;
  }

  .lsx-cmp {
    min-width: 900px;
    grid-template-columns: 150px repeat(4, minmax(0, 1fr));
  }

  .lsx-cmp__k {
    position: sticky;
    left: 0;
    z-index: 1;
    padding: 0 12px;
    background: var(--surf);
  }

  .lsx-cmp__img,
  .lsx-cmp__slot {
    height: 110px;
  }

  .lsx-fin {
    padding: 24px;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 20px;
  }

  .lsx-fin__dp {
    grid-column: 1 / -1;
  }

  .lsx-eqs {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .lsx-eq {
    padding: 22px 24px;
  }

  .lsx-eq.is-open .lsx-eq__ul {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .lsx-specwrap {
    padding: 8px 24px;
  }

  .lsx-specs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    column-gap: 30px;
  }

  .lsx-tl {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 28px;
  }

  .lsx-tl::before {
    display: none;
  }

  .lsx-card__t {
    font-size: 36px;
  }

  /* bottom bar: price + Reserve */
  .lsx-mbar {
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 60;
    padding: 12px var(--gut);
    border-top: .5px solid var(--sg-ln);
    background: var(--surf);
    box-shadow: var(--st-bar-shadow);
    display: flex;
    align-items: center;
    gap: 16px;
    transform: translateY(110%);
    transition: transform .35s var(--lx-ease);
  }

  .lsx-mbar.is-on {
    transform: translateY(0);
  }

  .lsx-mbar__p {
    margin-right: auto;
    white-space: nowrap;
  }

  .lsx-mbar__mo {
    font-size: 24px;
    font-weight: 300;
    color: var(--acc);
  }

  .lsx-mbar__per {
    font-size: 14px;
    color: var(--body);
  }

  .lsx-mbar__res {
    height: 48px;
    padding: 0 20px;
    border: 0;
    border-radius: 24px;
    background: var(--acc);
    color: #fff;
    font: inherit;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: .14em;
    cursor: pointer;
  }

  .lsx ~ .ft {
    margin-bottom: 72px;
  }
}

@media (max-width: 767px) {
  .lsx-h1 {
    font-size: 36px;
  }

  .lsx-title__r {
    width: 100%;
  }

  .lsx-pill {
    height: 48px;
    padding: 0 16px;
    flex: 1;
  }

  .lsx-fav {
    width: 48px;
    height: 48px;
  }

  .lsx-photo__tr .js-s4-spin,
  .lsx-photo__sep,
  .lsx-photo__cnt .js-s4-lbl {
    display: none;
  }

  .lsx-photo__cnt,
  .lsx-photo__tr {
    top: 12px;
  }

  .lsx-photo__cnt {
    left: 12px;
  }

  .lsx-photo__tr {
    right: 12px;
  }

  .lsx-glass {
    height: 32px;
    padding: 0 12px;
  }

  .lsx-photo__foot {
