/* == 129. Listing Single v5 — bands and chapters ======================= */
/* Shared: tokens, .lsg-e / .lsg-s (30), lightbox (31). Photo bands stay dark in both themes. */
:root {
  --sw-band: #0b0c0e;
  --sw-glass: rgba(12, 13, 16, .6);
  --sw-w10: rgba(255, 255, 255, .1);
  --sw-w16: rgba(255, 255, 255, .16);
  --sw-w20: rgba(255, 255, 255, .2);
  --sw-w40: rgba(255, 255, 255, .4);
  --sw-w45: rgba(255, 255, 255, .45);
  --sw-w60: rgba(255, 255, 255, .6);
  --sw-w65: rgba(255, 255, 255, .65);
  --sw-w70: rgba(255, 255, 255, .7);
  --sw-w75: rgba(255, 255, 255, .75);
  --sw-w85: rgba(255, 255, 255, .85);
  --sw-w90: rgba(255, 255, 255, .9);
  --sw-mint: #5fd49a;
  --sw-l12: rgba(17, 20, 24, .12);
  --sw-l30: rgba(17, 20, 24, .3);
  --sw-hero: linear-gradient(180deg, rgba(8, 9, 11, .55) 0%, rgba(8, 9, 11, 0) 34%, rgba(8, 9, 11, 0) 62%, rgba(8, 9, 11, .75) 100%);
  --sw-inside: linear-gradient(90deg, rgba(8, 9, 11, .88) 0%, rgba(8, 9, 11, .55) 38%, rgba(8, 9, 11, 0) 70%);
  --sw-drive: radial-gradient(ellipse at center, rgba(8, 9, 11, .35) 0%, rgba(8, 9, 11, .85) 75%);
  /* the Serpent is shot on white: deeper shades keep the white type readable */
  --sw-hero-e: linear-gradient(180deg, rgba(8, 9, 11, .82) 0%, rgba(8, 9, 11, .3) 34%, rgba(8, 9, 11, .1) 58%, rgba(8, 9, 11, .85) 100%);
  --sw-inside-e: linear-gradient(90deg, rgba(8, 9, 11, .94) 0%, rgba(8, 9, 11, .72) 42%, rgba(8, 9, 11, .1) 75%);
  --sw-drive-e: radial-gradient(ellipse at center, rgba(8, 9, 11, .66) 0%, rgba(8, 9, 11, .9) 75%);
  --sw-acc70: rgba(216, 71, 14, .7);
}

[data-skin="green"] {
  --sw-acc70: rgba(18, 132, 79, .7);
}

[data-theme="dark"] {
  --sw-l12: rgba(242, 243, 245, .12);
  --sw-l30: rgba(242, 243, 245, .3);
}

.lsw-band,
.lsw-ch,
.lsw-filmsec,
.lsw-yours,
.lsw-mbar {
