}

.lsw-mute {
  color: var(--mute);
}

.lsw-eb {
  font-size: max(12px, calc(var(--u) * 15));
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 4.5);
  color: var(--mute);
}

.lsw-eb--light {
