/* == 132. Listing Single v6 — hero and ask bar ========================= */
/* Shared: tokens, .lsg-e / .lsg-s (30), range / lightbox / ribbon arrows (31), chart and deal bar (33). */
:root {
  --sy-hero: linear-gradient(90deg, rgba(8, 9, 11, .8) 0%, rgba(8, 9, 11, .35) 45%, rgba(8, 9, 11, .1) 100%);
  /* the Serpent is shot on white: dark on both sides so the price at the right reads too */
  --sy-hero-e: linear-gradient(180deg, rgba(8, 9, 11, .45) 0%, rgba(8, 9, 11, 0) 45%), linear-gradient(90deg, rgba(8, 9, 11, .88) 0%, rgba(8, 9, 11, .45) 45%, rgba(8, 9, 11, .8) 100%);
  --sy-ask-shadow: 0 24px 60px rgba(17, 20, 24, .14);
  --sy-ok10: rgba(47, 163, 107, .1);
  --sy-video: rgba(8, 9, 11, .35);
  --sy-busy: #c4c8ce;
}

[data-theme="dark"] {
  --sy-ask-shadow: 0 24px 60px rgba(0, 0, 0, .45);
  --sy-busy: #3a3e45;
}

.lsy-hero,
.lsy-askwrap,
.lsy-cols,
.lsy-more,
.lsy-fab {
  font-weight: 400;
}

.lsy .acc {
  color: var(--acc);
}

.lsy-mute {
  color: var(--mute);
}

.lsy-k {
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.34);
  color: var(--mute);
}

.lsy-tile {
  min-width: 0;
  border-radius: calc(var(--u) * 32);
  background: var(--surf);
}

.lsy-hero {
  position: relative;
  height: calc(var(--u) * 1100);
  margin: calc(var(--u) * 20) calc(var(--u) * 20) 0;
  border-radius: calc(var(--u) * 44);
  overflow: hidden;
  background: #0b0c0e;
  color: #fff;
}

.lsy-hero__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 62%;
}

.lsy-hero__shade {
  position: absolute;
  inset: 0;
  background: var(--sy-hero);
}

:root:not([data-skin]) .lsy-hero__shade {
  background: var(--sy-hero-e);
}

.lsy-hero__l {
  position: absolute;
  left: calc(var(--u) * 80);
  top: calc(var(--u) * 90);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 16);
}

.lsy-hero__eb {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 3.36);
  color: var(--sw-w70);
}

.lsy-hero__dot {
  width: calc(var(--u) * 8);
  height: calc(var(--u) * 8);
  border-radius: 50%;
  background: var(--ok);
}

.lsy-hero__h1 {
  font-size: max(12px, calc(var(--u) * 150));
  letter-spacing: -.06em;
  line-height: .92;
}

.lsy-hero__stats {
  font-size: max(12px, calc(var(--u) * 22));
  font-weight: 300;
  color: var(--sw-w75);
}

.lsy-hero__r {
  position: absolute;
  right: calc(var(--u) * 80);
  top: calc(var(--u) * 90);
