  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.54);
  white-space: nowrap;
  cursor: pointer;
}

.lsy-chat__new:hover {
  border-color: var(--acc);
  color: var(--acc);
}

/* the close button belongs to the phone bottom sheet */
.lsy-chat__x {
  display: none;
}

.lsy-msgs {
  min-height: 0;
  flex: 1;
  padding: calc(var(--u) * 26) calc(var(--u) * 30);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 14);
}

.lsy-msg {
  display: flex;
}

.lsy-msg--me {
  justify-content: flex-end;
}

.lsy-msg__b {
  max-width: 86%;
  padding: calc(var(--u) * 18) calc(var(--u) * 22);
  border-radius: calc(var(--u) * 22) calc(var(--u) * 22) calc(var(--u) * 22) calc(var(--u) * 6);
  background: var(--sg-chip);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 18));
  font-weight: 300;
  line-height: 1.5;
  white-space: pre-wrap;
  text-wrap: pretty;
}

.lsy-msg--me .lsy-msg__b {
  border-radius: calc(var(--u) * 22) calc(var(--u) * 22) calc(var(--u) * 6) calc(var(--u) * 22);
  background: var(--acc);
  color: #fff;
}

.lsy-typing {
  display: flex;
  gap: calc(var(--u) * 6);
  align-items: center;
}

.lsy-typing span {
  width: calc(var(--u) * 8);
  height: calc(var(--u) * 8);
  border-radius: 50%;
  background: var(--mute);
  animation: lsy-dot 1s infinite ease-in-out;
}

.lsy-typing span:nth-child(2) {
  animation-delay: .15s;
}

.lsy-typing span:nth-child(3) {
  animation-delay: .3s;
}

@keyframes lsy-dot {
  0%, 100% { opacity: .3; }
  50% { opacity: 1; }
}

.lsy-chips {
  padding: calc(var(--u) * 16) calc(var(--u) * 30) 0;
  display: flex;
  flex-wrap: wrap;
  gap: calc(var(--u) * 8);
}

.lsy-chip {
  height: calc(var(--u) * 42);
  padding: 0 calc(var(--u) * 16);
  border-radius: calc(var(--u) * 21);
  border: .5px solid var(--line2);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 14));
  font-weight: 300;
  white-space: nowrap;
  cursor: pointer;
  transition: border-color .25s, color .25s;
}

.lsy-chip:hover {
  border-color: var(--acc);
  color: var(--acc);
}

.lsy-send {
  padding: calc(var(--u) * 16) calc(var(--u) * 30) calc(var(--u) * 20);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.lsy-send__in {
  min-width: 0;
  height: calc(var(--u) * 64);
  flex: 1;
  padding: 0 calc(var(--u) * 24);
  border-radius: calc(var(--u) * 32);
  border: .5px solid var(--line2);
  background: var(--sg-chip);
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 18));
  font-weight: 300;
  outline: 0;
}

.lsy-send__in:focus {
  border-color: var(--acc);
}

.lsy-send__go {
  width: calc(var(--u) * 64);
  height: calc(var(--u) * 64);
  padding: 0;
  flex-shrink: 0;
  border: 0;
  border-radius: 50%;
  background: var(--acc);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 22));
  cursor: pointer;
}

.lsy-send__go:disabled {
  background: var(--sy-busy);
  cursor: default;
}

.lsy-chat__foot {
  padding: calc(var(--u) * 20) calc(var(--u) * 30);
  border-top: .5px solid var(--sg-ln);
  background: var(--sg-chip);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 16);
}

.lsy-chat__price {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 2);
  white-space: nowrap;
}

.lsy-chat__mo {
  font-size: max(12px, calc(var(--u) * 28));
  font-weight: 300;
  color: var(--acc);
}

.lsy-chat__per {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

.lsy-chat__cash {
  font-size: max(12px, calc(var(--u) * 13));
  color: var(--mute);
}

.lsy-chat__res {
  height: calc(var(--u) * 64);
  margin-left: auto;
  padding: 0 calc(var(--u) * 30);
  border: 0;
  border-radius: calc(var(--u) * 32);
  background: var(--acc);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.82);
  white-space: nowrap;
  cursor: pointer;
  transition: background .25s;
}

/* not quite it? */
.lsy-more {
  padding-top: calc(var(--u) * 80);
}

.lsy-more__head {
  margin-bottom: calc(var(--u) * 40);
  padding-top: calc(var(--u) * 80);
  border-top: .5px solid var(--line2);
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: calc(var(--u) * 24);
}

.lsy-more__t {
  font-size: max(12px, calc(var(--u) * 64));
  letter-spacing: -.045em;
}

.lsy-more__r {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 24);
}

.lsy-more__cmp {
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.24);
  text-decoration: none;
  transition: color .25s;
}

.lsy-more__cmp:hover {
  color: var(--acc);
}

.lsy-rib {
  padding: 0 var(--gut) calc(var(--u) * 10);
  scroll-padding: 0 var(--gut);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  display: flex;
  gap: calc(var(--u) * 20);
}

.lsy-rib::-webkit-scrollbar {
  display: none;
}

.lsy-rc {
  flex: 0 0 calc(var(--u) * 600);
  scroll-snap-align: start;
}

.lsy-rc__a {
  height: 100%;
  border-radius: calc(var(--u) * 32);
  border: .5px solid var(--sg-ln);
  background: var(--surf);
  color: var(--ink);
  text-decoration: none;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color .25s;
}

.lsy-rc__a:hover {
  border-color: var(--acc);
}

.lsy-rc__ph {
  height: calc(var(--u) * 300);
  display: block;
}

.lsy-rc__ph img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.lsy-rc__b {
  padding: calc(var(--u) * 26) calc(var(--u) * 30) calc(var(--u) * 30);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

.lsy-rc__meta {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.92);
  color: var(--mute);
}

.lsy-rc__n {
  font-size: max(12px, calc(var(--u) * 28));
  font-weight: 300;
}

.lsy-rc__p {
  padding-top: calc(var(--u) * 14);
  border-top: .5px solid var(--sg-ln);
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.lsy-rc__mo {
  font-size: max(12px, calc(var(--u) * 28));
  font-weight: 300;
  color: var(--acc);
}

.lsy-rc__per {
  font-size: max(12px, calc(var(--u) * 13));
  color: var(--body);
}

.lsy-rc__c {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

/* the floating "Ask Jordan" button exists below 1200 px only */
.lsy-fab {
  display: none;
}

/* == 135. Listing Single v6 — smaller screens ========================== */
@media (max-width: 1599px) and (min-width: 1200px) {
  /* the chat never gets narrower than 400 px */
  .lsy-cols {
    grid-template-columns: minmax(0, 1fr) minmax(400px, calc(var(--u) * 560));
    gap: calc(var(--u) * 50);
  }

  .lsy-q2,
  .lsy-q4,
  .lsy-q5,
  .lsy-q7 {
    grid-template-columns: minmax(0, 1fr);
  }

  .lsy-fin {
    grid-template-columns: minmax(0, 1fr);
  }

  .lsy-fin__r {
    align-items: flex-start;
  }

  .lsy-tops,
  .lsy-ogs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .lsy-chat__r {
    white-space: normal;
  }
}

@media (max-width: 1199px) {
  .lsy-hero {
    height: auto;
    min-height: 560px;
    margin: 12px 12px 0;
    border-radius: 24px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .lsy-hero__shade {
    background: rgba(8, 9, 11, .55);
  }

  :root:not([data-skin]) .lsy-hero__shade {
    background: rgba(8, 9, 11, .68);
  }

  .lsy-hero__l,
  .lsy-hero__r {
    position: relative;
    left: auto;
    right: auto;
    top: auto;
    padding: 36px 28px 0;
  }

  .lsy-hero__r {
    padding: 28px 28px 96px;
    align-items: flex-start;
    text-align: left;
  }

  .lsy-hero__h1 {
    font-size: 64px;
  }

  .lsy-hero__price {
    font-size: 44px;
  }

  .lsy-askwrap {
    margin-top: -40px;
  }

  .lsy-ask {
    height: 72px;
    padding: 0 8px 0 20px;
    gap: 12px;
  }

  .lsy-ask__in {
    height: 56px;
    font-size: 17px;
  }

  .lsy-ask__go {
    height: 56px;
    padding: 0 20px;
  }

  .lsy-jumps {
    width: 100%;
    flex-wrap: nowrap;
    justify-content: flex-start;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .lsy-jumps::-webkit-scrollbar {
    display: none;
  }

  .lsy-cols {
    margin-top: 32px;
    grid-template-columns: minmax(0, 1fr);
  }

  .lsy-q {
    padding: 56px 0;
  }

  .lsy-q__t {
    font-size: 40px;
  }

  .lsy-q__short {
    flex-direction: column;
    gap: 8px;
    font-size: 20px;
  }

  .lsy-tile {
    border-radius: 24px;
  }

  .lsy-fin,
  .lsy-q2,
  .lsy-q3,
  .lsy-q4,
  .lsy-q5,
  .lsy-q7,
  .lsy-back {
    grid-template-columns: minmax(0, 1fr);
  }

  .lsy-fin {
    padding: 28px;
    gap: 24px;
  }

  .lsy-fin__r {
    align-items: flex-start;
  }

  .lsy-fin__v {
    font-size: 64px;
  }

  .lsy-zero,
  .lsy-q2__r,
  .lsy-slots,
  .lsy-shop,
  .lsy-deal,
  .lsy-chart,
  .lsy-back__c {
    padding: 28px;
  }

  .lsy-zero__n {
    font-size: 96px;
  }

  .lsy-video {
    height: auto;
    aspect-ratio: 3 / 2;
    border-radius: 24px;
  }

  .lsy-video__play {
    width: 80px;
    height: 80px;
    font-size: 26px;
  }

  .lsy-tops,
  .lsy-ogs {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  /* the chat becomes a bottom sheet behind the "Ask Jordan" button */
  .lsy-chat {
    position: fixed;
    left: 0;
    right: 0;
    top: auto;
    bottom: 0;
    z-index: 70;
    height: min(86svh, 720px);
    border-radius: 24px 24px 0 0;
    box-shadow: var(--st-bar-shadow);
    transform: translateY(105%);
    visibility: hidden;
    transition: transform .35s var(--lx-ease), visibility 0s .35s;
  }

  .lsy-chat.is-open {
    transform: translateY(0);
    visibility: visible;
    transition: transform .35s var(--lx-ease);
  }

  .lsy-chat__x {
    width: 40px;
    height: 40px;
    padding: 0;
    flex-shrink: 0;
    border: .5px solid var(--line2);
    border-radius: 50%;
    background: transparent;
    color: var(--ink);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
  }

  .lsy-chat__x .ico {
    width: 18px;
    height: 18px;
  }

  .lsy-chat__r {
    white-space: normal;
  }

  .lsy-chips {
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .lsy-fab {
    position: fixed;
    right: 16px;
    bottom: 16px;
    z-index: 65;
    height: 56px;
    padding: 0 20px 0 8px;
    border: 0;
    border-radius: 28px;
    background: var(--acc);
    color: #fff;
    font: inherit;
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: .14em;
    box-shadow: var(--st-bar-shadow);
    display: flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
  }

  .lsy-fab__ph img {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    object-fit: cover;
  }

  .lsy-more__head {
    flex-wrap: wrap;
  }

  .lsy-more__t {
    font-size: 40px;
  }

  .lsy-rc {
    flex-basis: 420px;
  }

  .lsy-rc__ph {
    height: auto;
    aspect-ratio: 1376 / 864;
  }
}

@media (max-width: 767px) {
  .lsy-hero__h1 {
    font-size: 44px;
  }

  .lsy-hero__l,
  .lsy-hero__r {
    padding-left: 18px;
    padding-right: 18px;
  }

  .lsy-ask__go {
    padding: 0 14px;
    font-size: 12px;
  }

  .lsy-q__t {
    font-size: 32px;
  }

  .lsy-fin__segs {
    grid-template-columns: minmax(0, 1fr);
  }

  /* BBH Bartle is wide: six glyphs take about 6.3em */
  .lsy-fin__v {
    font-size: min(56px, 12vw);
  }

  .lsy-ck,
  .lsy-fine__c {
    white-space: normal;
    height: auto;
    min-height: 40px;
  }

  .lsy-hist__r {
    grid-template-columns: 52px minmax(0, 1fr);
  }

  .lsy-hist__m {
    grid-column: 2;
  }

  .lsy-vin {
    flex-wrap: wrap;
  }

  .lsy-tops,
  .lsy-ogs {
    grid-template-columns: minmax(0, 1fr);
  }

  .lsy-chart .lsx-ch__lab {
    font-size: 12px;
    padding: 0 8px;
  }

  .lsy-rc {
    flex-basis: 82%;
  }

  .lsy-more__r {
    width: 100%;
    flex-wrap: wrap;
  }
}

/* == 136. Shop v1 — search, car, categories ============================ */
:root {
  --shp-ok12: rgba(47, 163, 107, .12);
  --shp-grey: #5f6671;
  --shp-fab: #111418;
  --shp-scrim: rgba(8, 9, 11, .5);
  --shp-drawer-shadow: -30px 0 80px rgba(8, 9, 11, .3);
}

.shp-page .acc {
  color: var(--acc);
}

.shp-top,
.shp-cats,
.shp-cat-sec,
.shp-kits-sec,
.shp-why,
.shp-fab,
.shp-drawer {
  font-weight: 400;
}

.shp-k {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.16);
  color: var(--mute);
}

.shp-link {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--mute);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  cursor: pointer;
}

.shp-link:hover {
  color: var(--acc);
}

/* search + my car */
.shp-search {
  padding: calc(var(--u) * 14) calc(var(--u) * 14) calc(var(--u) * 14) calc(var(--u) * 40);
  border-radius: calc(var(--u) * 32);
  background: var(--surf);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 24);
}

.shp-search__ic {
  width: calc(var(--u) * 26);
  height: calc(var(--u) * 26);
  flex-shrink: 0;
  color: var(--acc);
}

.shp-search__in {
  min-width: 0;
  height: calc(var(--u) * 72);
  flex: 1;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 24));
  font-weight: 300;
  outline: 0;
}

.shp-search__in::placeholder {
  color: var(--mute);
}

.shp-search:focus-within {
  box-shadow: 0 0 0 2px var(--acc);
}

.shp-search__div {
  width: .5px;
  height: calc(var(--u) * 56);
  flex-shrink: 0;
  background: var(--line2);
}

.shp-car {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.shp-car__k {
  margin-right: calc(var(--u) * 6);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.16);
  color: var(--mute);
  white-space: nowrap;
}

.shp-car__k .ico {
  color: var(--acc);
}

.shp-sel {
  position: relative;
  display: flex;
  align-items: center;
}

.shp-sel__s {
  height: calc(var(--u) * 72);
  padding: 0 calc(var(--u) * 54) 0 calc(var(--u) * 24);
  border-radius: calc(var(--u) * 36);
  border: .5px solid var(--line2);
  background: var(--bg);
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 18));
  font-weight: 300;
  -webkit-appearance: none;
  appearance: none;
  cursor: pointer;
}

.shp-sel__s:focus-visible {
  outline: 2px solid var(--acc);
  outline-offset: 2px;
}

.shp-sel__c {
  position: absolute;
  right: calc(var(--u) * 22);
  color: var(--mute);
  pointer-events: none;
}

.shp-status {
  min-height: calc(var(--u) * 40);
  margin-top: calc(var(--u) * 18);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
}

.shp-chip {
  height: calc(var(--u) * 40);
  padding: 0 calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
  background: var(--acc-a10);
  color: var(--acc);
  font-size: max(12px, calc(var(--u) * 15));
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.shp-chip.is-ok {
  background: var(--shp-ok12);
  color: var(--ok);
}

.shp-chip.is-none {
  background: var(--sg-chip);
  color: var(--mute);
}

.shp-chip__dot {
  width: calc(var(--u) * 8);
  height: calc(var(--u) * 8);
  border-radius: 50%;
  background: currentColor;
}

.shp-status__s {
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--mute);
}

/* categories */
.shp-cats {
  margin-top: calc(var(--u) * 60);
}

.shp-cats__ul {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: calc(var(--u) * 16);
}

.shp-cat {
  position: relative;
  width: 100%;
  height: calc(var(--u) * 380);
  padding: 0;
  border: 1.5px solid transparent;
  border-radius: calc(var(--u) * 32);
  overflow: hidden;
  background: var(--stripes);
  color: var(--ink);
  font: inherit;
  text-align: left;
  display: block;
  cursor: pointer;
  transition: border-color .25s;
}

.shp-cat[aria-pressed="true"] {
  border-color: var(--acc);
}

.shp-cat__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .5s var(--lx-ease);
}

.shp-cat:hover .shp-cat__img {
  transform: scale(1.03);
}

.shp-card__slot {
  position: absolute;
  left: 50%;
  top: 42%;
  transform: translate(-50%, -50%);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 12));
  color: var(--mute);
  white-space: nowrap;
}

.shp-cat__lab {
  position: absolute;
  left: calc(var(--u) * 16);
  right: calc(var(--u) * 16);
  bottom: calc(var(--u) * 16);
  padding: calc(var(--u) * 22) calc(var(--u) * 26);
  border-radius: calc(var(--u) * 22);
  background: var(--surf);
  display: flex;
  align-items: center;
