  background: var(--sg-chip);
  overflow: hidden;
  display: block;
}

.shp-ship__fill {
  width: 0;
  height: 100%;
  background: var(--acc);
  display: block;
  transition: width .4s;
}

.shp-ship__fill.is-ok {
  background: var(--ok);
}

.shp-lines {
  min-height: 0;
  flex: 1;
  padding: 0 calc(var(--u) * 44);
  overflow-y: auto;
}

.shp-line {
  padding: calc(var(--u) * 22) 0;
  border-top: .5px solid var(--sg-ln);
  display: grid;
  grid-template-columns: calc(var(--u) * 110) minmax(0, 1fr) auto;
  gap: calc(var(--u) * 20);
  align-items: center;
}

.shp-line__ph {
  height: calc(var(--u) * 110);
  border-radius: calc(var(--u) * 18);
  background: var(--stripes);
  color: var(--mute);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 11));
  display: flex;
  align-items: center;
  justify-content: center;
}

.shp-line__b {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
}

.shp-line__brand {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  color: var(--mute);
}

.shp-line__n {
  font-size: max(12px, calc(var(--u) * 19));
  font-weight: 300;
  line-height: 1.3;
}

.shp-qty {
  margin-top: calc(var(--u) * 4);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 6);
}

.shp-qty__b {
  width: calc(var(--u) * 38);
  height: calc(var(--u) * 38);
  padding: 0;
  border-radius: 50%;
  border: .5px solid var(--line2);
  background: transparent;
  color: var(--ink);
  font: inherit;
  cursor: pointer;
}

.shp-qty__n {
  min-width: calc(var(--u) * 30);
  text-align: center;
  font-size: max(12px, calc(var(--u) * 17));
}

.shp-line__t {
  font-size: max(12px, calc(var(--u) * 22));
  font-weight: 300;
  white-space: nowrap;
}

.shp-lines__empty {
  padding: calc(var(--u) * 80) 0;
  text-align: center;
  font-size: max(12px, calc(var(--u) * 22));
  font-weight: 300;
  color: var(--mute);
}

.shp-lines__empty[hidden] {
  display: none;
}

.shp-drawer__foot {
  padding: calc(var(--u) * 28) calc(var(--u) * 44) calc(var(--u) * 40);
  border-top: .5px solid var(--sg-ln);
  background: var(--sg-chip);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 14);
}

.shp-totals {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 14);
}

.shp-totals div {
  display: flex;
  justify-content: space-between;
  font-size: max(12px, calc(var(--u) * 17));
  font-weight: 300;
  color: var(--body);
}

.shp-checkout {
  height: calc(var(--u) * 84);
  margin-top: calc(var(--u) * 10);
  border-radius: calc(var(--u) * 42);
  background: var(--acc);
  color: #fff;
  font-size: max(12px, calc(var(--u) * 15));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.4);
  text-decoration: none;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5em;
  transition: filter .25s;
}

.shp-checkout:hover {
  color: #fff;
  filter: brightness(1.08);
}

/* the ring sits inside the pill, not as a second outline around it */
.shp-checkout:focus-visible {
  outline: 2px solid #fff;
  outline-offset: calc(var(--u) * -6);
}

.shp-drawer__note {
  text-align: center;
  font-size: max(12px, calc(var(--u) * 13));
  color: var(--mute);
}

/* == 139. Shop v1 — smaller screens ==================================== */
@media (max-width: 1599px) and (min-width: 1200px) {
  .shp-search {
    flex-wrap: wrap;
  }

  .shp-search__div {
    display: none;
  }

  .shp-car {
    width: 100%;
    padding-bottom: 6px;
  }

  .shp-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .shp-cats__ul {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .shp-kits {
    grid-template-columns: minmax(0, 1fr);
  }

  .shp-why__ul {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .shp-why__i:nth-child(3) {
    border-left: 0;
    border-top: .5px solid var(--line2);
  }

  .shp-why__i:nth-child(4) {
    border-top: .5px solid var(--line2);
  }
}

@media (max-width: 1199px) {
  .shp-search {
    padding: 12px;
    border-radius: 24px;
    flex-wrap: wrap;
    gap: 10px 12px;
  }

  .shp-search__in {
    height: 48px;
    font-size: 17px;
  }

  .shp-search__div {
    display: none;
  }

  .shp-car {
    width: 100%;
    flex-wrap: wrap;
  }

  .shp-car__k {
    width: 100%;
  }

  .shp-sel {
    min-width: 0;
    flex: 1;
  }

  .shp-sel__s {
    width: 100%;
    height: 48px;
    padding: 0 36px 0 16px;
    font-size: 15px;
  }

  .shp-status {
    flex-wrap: wrap;
  }

  .shp-cats {
    margin-top: 32px;
  }

  .shp-cats__ul {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .shp-cat {
    height: 220px;
    border-radius: 20px;
  }

  .shp-cat__lab {
    left: 10px;
    right: 10px;
    bottom: 10px;
    padding: 14px 16px;
    border-radius: 16px;
  }

  .shp-cat__t {
    font-size: 20px;
  }

  .shp-cat__go {
    width: 40px;
    height: 40px;
  }

  .shp-cat-sec {
    margin-top: 40px;
    grid-template-columns: minmax(0, 1fr);
  }

  /* filters become a bottom sheet behind the "Filters (n)" button */
  .shp-filters {
    position: fixed;
    left: 0;
    right: 0;
    top: auto;
    bottom: 0;
    z-index: 75;
    max-height: 86svh;
    padding: 24px 24px 32px;
    border-radius: 24px 24px 0 0;
    overflow-y: auto;
    box-shadow: var(--st-bar-shadow);
    transform: translateY(105%);
    visibility: hidden;
    transition: transform .35s var(--lx-ease), visibility 0s .35s;
  }

  .shp-filters.is-open {
    transform: translateY(0);
    visibility: visible;
    box-shadow: var(--st-bar-shadow), 0 0 0 100vmax rgba(10, 12, 15, .45);
    transition: transform .35s var(--lx-ease);
  }

  .shp-filters__head {
    gap: 16px;
  }

  .shp-filters__head .shp-link {
    margin-left: auto;
  }

  .shp-filters__x {
    width: 40px;
    height: 40px;
    padding: 0;
    border-radius: 50%;
    border: .5px solid var(--line2);
    background: transparent;
    color: var(--ink);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
  }

  .shp-fopen {
    height: 44px;
    padding: 0 16px;
    border-radius: 22px;
    border: .5px solid var(--line2);
    background: transparent;
    color: var(--ink);
    font: inherit;
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: .12em;
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
  }

  .shp-fopen__n {
    min-width: 22px;
    height: 22px;
    padding: 0 6px;
    border-radius: 11px;
    background: var(--acc);
    color: #fff;
    font-size: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .shp-fopen__n[hidden] {
    display: none;
  }

  .shp-sort {
    width: 100%;
    margin-left: 0;
    overflow-x: auto;
  }

  .shp-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
  }

  .shp-card {
    border-radius: 20px;
  }

  .shp-card__ph {
    height: auto;
    aspect-ratio: 3 / 2;
  }

  .shp-card__b {
    padding: 16px;
  }

  .shp-card__n {
    min-height: 0;
    font-size: 17px;
  }

  .shp-card__foot {
    flex-wrap: wrap;
  }

  .shp-card__v {
    font-size: 22px;
  }

  .shp-kits-sec {
    padding-top: 64px;
  }

  .shp-h .lsg-h__t {
    font-size: 40px;
  }

  .shp-kits {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .shp-kit {
    padding: 28px;
    border-radius: 24px;
  }

  .shp-kit__t {
    font-size: 32px;
  }

  .shp-why {
    margin-top: 64px;
  }

  .shp-why__ul {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .shp-why__i {
    padding: 24px 18px;
  }

  .shp-why__i:nth-child(3) {
    border-left: 0;
  }

  .shp-why__i:nth-child(n + 3) {
    border-top: .5px solid var(--line2);
  }

  .shp-fab {
    right: 16px;
    bottom: 16px;
    height: 56px;
    padding: 0 18px;
    font-size: 13px;
    gap: 10px;
  }

  .shp-drawer {
    width: 100vw;
  }

  .shp-drawer__head,
  .shp-ship,
  .shp-lines,
  .shp-drawer__foot {
    padding-left: 20px;
    padding-right: 20px;
  }

  .shp-drawer__t {
    font-size: 32px;
  }

  .shp-page ~ .ft {
    margin-bottom: 72px;
  }
}

@media (max-width: 767px) {
  .shp-cats__ul,
  .shp-why__ul {
    grid-template-columns: minmax(0, 1fr);
  }

  .shp-why__i:nth-child(n) {
    border-left: 0;
  }

  .shp-why__i + .shp-why__i {
    border-top: .5px solid var(--line2);
  }

  .shp-cat {
    height: 180px;
  }

  .shp-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .shp-kit__foot {
    flex-wrap: wrap;
  }

  /* the make gets its own row, model and year share the next */
  .shp-car__k + .shp-sel {
    flex-basis: 100%;
  }

  .shp-line {
    grid-template-columns: 72px minmax(0, 1fr);
  }

  .shp-line__ph {
    height: 72px;
  }

  .shp-line__t {
    grid-column: 2;
  }
}

/* == 140. Shop v3 — hero slider, category ribbon ======================= */
:root {
  --ts-night: #0e1013;
  --ts-inv: #fff;
  --ts-ease: cubic-bezier(.2, .7, .2, 1);
  --ts-stripes-night: repeating-linear-gradient(135deg, #1a1d22 0 calc(var(--u) * 14), #14161a calc(var(--u) * 14) calc(var(--u) * 28));
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --ts-inv: #111418;
  }
}

:root[data-theme="dark"] {
  --ts-inv: #111418;
}

.ts {
  font-weight: 400;
}

.ts-sec {
  padding-top: calc(var(--u) * 110);
}

/* hero: three stacked slides crossfade */
.ts-hero {
  position: relative;
  height: calc(var(--u) * 900);
  margin: 0 var(--gut);
  border-radius: calc(var(--u) * 44);
  overflow: hidden;
  background: var(--ts-night);
  color: #fff;
  touch-action: pan-y;
}

.ts-sl {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) calc(var(--u) * 1240);
  opacity: 0;
  transform: translateX(calc(var(--u) * 40));
  pointer-events: none;
  transition: opacity .7s ease, transform .9s var(--ts-ease);
}

.ts-sl.is-past {
  transform: translateX(calc(var(--u) * -40));
}

.ts-sl.is-on {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

.ts-sl__txt {
  padding: calc(var(--u) * 110) calc(var(--u) * 90) calc(var(--u) * 150);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: calc(var(--u) * 28);
}

.ts-sl__eb {
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 3.64);
  color: rgba(255, 255, 255, .6);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
}

.ts-sl__rule {
  width: calc(var(--u) * 40);
  height: 1px;
  background: var(--acc);
}

.ts-sl__t {
  font-size: max(12px, calc(var(--u) * 124));
  font-weight: 300;
  letter-spacing: -.06em;
  line-height: .94;
  text-wrap: balance;
}

.ts-sl__d {
  max-width: calc(var(--u) * 760);
  font-size: max(12px, calc(var(--u) * 24));
  font-weight: 300;
  line-height: 1.5;
  color: rgba(255, 255, 255, .7);
}

.ts-sl__go {
  margin-top: calc(var(--u) * 14);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 26);
}

.ts-sl__cta {
  height: calc(var(--u) * 80);
  padding: 0 calc(var(--u) * 40);
  border: 0;
  border-radius: calc(var(--u) * 40);
  background: var(--acc);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.24);
  white-space: nowrap;
  cursor: pointer;
  transition: filter .25s;
}

.ts-sl__cta:hover {
  filter: brightness(1.08);
}

.ts-sl__note {
  font-size: max(12px, calc(var(--u) * 18));
  color: rgba(255, 255, 255, .6);
}

.ts-sl__pic {
  position: relative;
  background: var(--ts-stripes-night);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.ts-sl__slot {
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 13));
  color: rgba(255, 255, 255, .45);
}

.ts-sl__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ts-sl__fade {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--ts-night) 0%, rgba(14, 16, 19, 0) 30%);
}

.ts-sl__big {
  position: absolute;
  right: calc(var(--u) * 50);
  top: calc(var(--u) * 50);
  font-family: "BBH Bartle", Geist, sans-serif;
  font-size: max(12px, calc(var(--u) * 150));
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1px var(--acc);
  opacity: .6;
}

.ts-hero__ctl {
  position: absolute;
  left: calc(var(--u) * 90);
  right: calc(var(--u) * 50);
  bottom: calc(var(--u) * 50);
  z-index: 2;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 20);
}

.ts-hero__num {
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 15));
  color: rgba(255, 255, 255, .7);
}

.ts-dots {
  display: flex;
  gap: calc(var(--u) * 8);
}

.ts-dot {
  width: calc(var(--u) * 24);
  height: calc(var(--u) * 6);
  padding: 0;
  border: 0;
  border-radius: calc(var(--u) * 3);
  background: rgba(255, 255, 255, .35);
  cursor: pointer;
  transition: all .4s;
}

.ts-dot.is-on {
  width: calc(var(--u) * 60);
  background: #fff;
}

.ts-arrows {
  display: flex;
  gap: calc(var(--u) * 10);
}

.ts-hero .ts-arrows {
  margin-left: calc(var(--u) * 14);
}

.ts-arr {
  width: calc(var(--u) * 64);
  height: calc(var(--u) * 64);
  flex-shrink: 0;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 20));
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.ts-arr--ghost {
  border: .5px solid rgba(255, 255, 255, .35);
  color: #fff;
}

.ts-arr--light {
  background: #fff;
  color: #111418;
}

.ts-arr--line {
  border: .5px solid var(--line2);
  color: var(--ink);
}

.ts-arr--acc {
  background: var(--acc);
  color: #fff;
}

/* 01 — the category ribbon scrolls sideways and snaps */
.ts-ribbon {
  display: flex;
  gap: calc(var(--u) * 16);
  padding: 0 var(--gut) calc(var(--u) * 10);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-padding: 0 var(--gut);
  scrollbar-width: none;
}

.ts-ribbon::-webkit-scrollbar {
  display: none;
}

.ts-ribbon li {
  flex: 0 0 calc(var(--u) * 560);
  scroll-snap-align: start;
}

.ts-cat {
  position: relative;
  width: 100%;
  height: calc(var(--u) * 640);
  padding: 0;
  border: 0;
  border-radius: calc(var(--u) * 32);
  overflow: hidden;
  background: var(--stripes);
  color: #fff;
  font: inherit;
  text-align: left;
  display: block;
  cursor: pointer;
  transition: transform .35s var(--ts-ease);
}

.ts-cat:hover {
  transform: scale(.985);
}

.ts-cat__slot {
  position: absolute;
  left: 50%;
  top: 44%;
  transform: translate(-50%, -50%);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 12));
  color: var(--mute);
  white-space: nowrap;
}

.ts-cat__img,
.ts-brand__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ts-cat__fade {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(8, 9, 11, 0) 50%, rgba(8, 9, 11, .82) 100%);
}

.ts-cat__lab {
  position: absolute;
  left: calc(var(--u) * 34);
  right: calc(var(--u) * 34);
  bottom: calc(var(--u) * 32);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: calc(var(--u) * 20);
}

.ts-cat__txt {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
}

.ts-cat__t {
  font-size: max(12px, calc(var(--u) * 44));
  font-weight: 300;
  letter-spacing: -.03em;
  line-height: 1;
}

.ts-cat__n {
  font-size: max(12px, calc(var(--u) * 15));
  color: rgba(255, 255, 255, .7);
}

.ts-cat__go {
  width: calc(var(--u) * 60);
  height: calc(var(--u) * 60);
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--acc);
  font-size: max(12px, calc(var(--u) * 22));
  display: flex;
  align-items: center;
  justify-content: center;
}

/* == 141. Shop v3 — tabs, product cards, featured brand ================ */
.ts-seg {
  padding: calc(var(--u) * 5);
  border-radius: calc(var(--u) * 32);
  background: var(--surf);
  display: flex;
}

.ts-seg__b {
  height: calc(var(--u) * 54);
  padding: 0 calc(var(--u) * 26);
  border: 0;
  border-radius: calc(var(--u) * 27);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 15));
  font-weight: 300;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 8);
  cursor: pointer;
}

.ts-seg__b--s {
  height: calc(var(--u) * 50);
  padding: 0 calc(var(--u) * 20);
  font-size: max(12px, calc(var(--u) * 14));
}

.ts-seg__b.is-on {
  background: var(--ink);
  color: var(--ts-inv);
}

.ts-seg__n {
  opacity: .55;
}

.ts-trend,
.ts-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: calc(var(--u) * 16);
}

.ts-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.ts-card {
  border: .5px solid transparent;
  border-radius: calc(var(--u) * 28);
  background: var(--surf);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .3s var(--ts-ease), border-color .25s;
}

.ts-card:hover {
  transform: translateY(calc(var(--u) * -6));
}

.ts-card.is-in {
  border-color: var(--ok);
}

.ts-card__ph {
  position: relative;
  height: calc(var(--u) * 440);
  background: var(--stripes);
