    max-width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .ts-seg__b {
    height: 44px;
    padding: 0 18px;
    font-size: 14px;
  }

  /* trending scrolls sideways */
  .ts-trend {
    margin: 0 calc(var(--gut) * -1);
    padding: 0 var(--gut) 8px;
    grid-template-columns: none;
    grid-auto-flow: column;
    grid-auto-columns: min(72vw, 320px);
    gap: 12px;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scroll-padding: 0 var(--gut);
    scrollbar-width: none;
  }

  .ts-trend > li {
    scroll-snap-align: start;
  }

  .ts-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
  }

  .ts-card {
    border-radius: 22px;
  }

  .ts-card__ph,
  .ts-card__ph--t {
    height: auto;
    aspect-ratio: 4 / 3;
  }

  .ts-card__b {
    padding: 16px 16px 18px;
  }

  .ts-card__meta {
    font-size: 12px;
    letter-spacing: .1em;
  }

  .ts-card__n {
    min-height: 2.5em;
    font-size: 17px;
  }

  .ts-card__v {
    font-size: 22px;
  }

  .ts-card__was {
    font-size: 13px;
  }

  .ts-add {
    height: 42px;
    padding: 0 16px;
    font-size: 12px;
  }

  .ts-badges {
    right: 62px;
    flex-wrap: wrap;
  }

  .ts-badge {
    height: 24px;
    padding: 0 9px;
    font-size: 12px;
    letter-spacing: .08em;
  }

  .ts-fav {
    width: 40px;
    height: 40px;
    font-size: 17px;
  }

  .ts-brand {
    margin: 64px 12px 0;
    border-radius: 28px;
    grid-template-columns: minmax(0, 1fr);
  }

  .ts-brand__pic {
    min-height: 0;
    aspect-ratio: 9 / 7;
  }

  .ts-brand__chip {
    left: 20px;
    top: 20px;
    height: 36px;
  }

  .ts-brand__txt {
    padding: 32px 24px 36px;
    gap: 18px;
  }

  .ts-brand__mark {
    font-size: 40px;
  }

  .ts-brand__t {
    font-size: 44px;
  }

  .ts-brand__d {
    font-size: 17px;
  }

  .ts-br__row {
    grid-template-columns: 64px minmax(0, 1fr) auto;
    gap: 8px 14px;
  }

  .ts-br__th {
    height: 64px;
    grid-row: span 2;
    border-radius: 14px;
  }

  .ts-br__n {
    font-size: 17px;
  }

  .ts-br__p {
    font-size: 19px;
    grid-column: 2;
  }

  .ts-add--br {
    grid-column: 3;
    grid-row: 1 / span 2;
  }

  .ts-brand__all {
    margin-top: 6px;
    height: 56px;
  }

  .ts-chips {
    margin: 0 calc(var(--gut) * -1) 20px;
    padding: 0 var(--gut);
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .ts-chip {
    height: 44px;
    padding: 0 18px;
    font-size: 15px;
  }

  .ts-more {
    height: 64px;
    margin-top: 28px;
    font-size: 13px;
  }

  .ts-more__dot {
    width: 36px;
    height: 36px;
  }

  .ts-score__v {
    font-size: 32px;
  }

  .ts-rvs {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .ts-rv {
    padding: 28px 26px;
    border-radius: 22px;
    gap: 18px;
  }

  .ts-rv__q {
    font-size: 19px;
  }

  .ts-rv__foot {
    flex-wrap: wrap;
  }

  .ts-rv__th {
    width: 56px;
    height: 56px;
  }

  .ts-rv__n {
    font-size: 16px;
  }

  .ts-club-sec {
    margin-top: 64px;
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .ts-club {
    padding: 36px 28px 32px;
    border-radius: 28px;
    gap: 16px;
  }

  .ts-club .ts-club__big {
    right: -20px;
    bottom: -60px;
    font-size: 240px;
  }

  .ts-club__t {
    font-size: 44px;
  }

  .ts-club__d {
    font-size: 17px;
  }

  .ts-club__form {
    height: 64px;
    padding: 0 6px 0 20px;
  }

  .ts-club__in {
    font-size: 17px;
  }

  .ts-club__b {
    height: 52px;
    padding: 0 18px;
    font-size: 12px;
  }

  .ts-club__ok {
    height: auto;
    min-height: 64px;
    padding: 14px 22px;
    font-size: 16px;
    flex-wrap: wrap;
  }

  .ts-bens {
    gap: 12px;
  }

  .ts-ben {
    padding: 26px 22px;
    border-radius: 22px;
    gap: 12px;
  }

  .ts-ben__ic {
    width: 52px;
    height: 52px;
  }

  .ts-ben__ic .ico {
    width: 24px;
    height: 24px;
  }

  .ts-ben__t {
    font-size: 21px;
  }

  .ts-ben__d {
    font-size: 14px;
  }

  .ts-toast {
    right: 16px;
    top: 16px;
    padding: 14px 16px;
    border-radius: 18px;
  }

  .ts-toast__ic {
    width: 40px;
    height: 40px;
    font-size: 16px;
  }

  .ts-toast__n {
    font-size: 16px;
  }
}

@media (max-width: 767px) {
  .ts-sl {
    grid-template-rows: 240px auto;
  }

  .ts-sl__txt {
    padding: 22px 20px 96px;
  }

  .ts-sl__t {
    font-size: 40px;
  }

  .ts-sl__big {
    font-size: 72px;
  }

  .ts-hero__ctl {
    left: 20px;
    right: 20px;
    bottom: 22px;
  }

  .ts-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .ts-card__b {
    padding: 12px 12px 14px;
  }

  .ts-card__meta {
    flex-direction: column;
    gap: 2px;
  }

  .ts-card__n {
    font-size: 15px;
  }

  .ts-card__foot {
    flex-wrap: wrap;
  }

  .ts-grid .ts-add {
    width: 100%;
  }

  .ts-card__slot {
    font-size: 12px;
    white-space: normal;
    width: 80%;
    text-align: center;
  }

  .ts-brand__t,
  .ts-club__t {
    font-size: 36px;
  }

  .ts-bens {
    grid-template-columns: minmax(0, 1fr);
  }

  .ts-club__form {
    flex-wrap: wrap;
    height: auto;
    padding: 8px;
    border-radius: 28px;
  }

  .ts-club__in {
    height: 48px;
    padding: 0 12px;
    flex-basis: 100%;
  }

  .ts-club__b {
    width: 100%;
  }
}

/* == 144. Shop v2 — category tiles, sticky toolbar ===================== */
:root {
  --g2-inv: #fff;
  --g2-band: #111418;
  --g2-panel-shadow: 0 calc(var(--u) * 30) calc(var(--u) * 70) rgba(17, 20, 24, .18);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --g2-inv: #111418;
    --g2-band: #1c1f24;
  }
}

:root[data-theme="dark"] {
  --g2-inv: #111418;
  --g2-band: #1c1f24;
}

.g2 {
  font-weight: 400;
}

.g2-tiles {
  display: grid;
  grid-template-columns: repeat(10, minmax(0, 1fr));
  gap: calc(var(--u) * 12);
}

.g2-tile {
  width: 100%;
  height: calc(var(--u) * 190);
  padding: calc(var(--u) * 24) calc(var(--u) * 22);
  border: .5px solid transparent;
  border-radius: calc(var(--u) * 28);
  background: var(--surf);
  color: var(--ink);
  font: inherit;
  text-align: left;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: all .25s;
}

.g2-tile.is-on {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--g2-inv);
}

.g2-tile__ic {
  width: calc(var(--u) * 56);
  height: calc(var(--u) * 56);
  border-radius: 50%;
  background: var(--acc-a10);
  color: var(--acc);
  display: flex;
  align-items: center;
  justify-content: center;
}

.g2-tile.is-on .g2-tile__ic {
  background: var(--acc);
  color: #fff;
}

.g2-tile__txt {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.g2-tile__t {
  font-size: max(12px, calc(var(--u) * 20));
  font-weight: 300;
  line-height: 1.15;
}

.g2-tile__n {
  font-size: max(12px, calc(var(--u) * 13));
  opacity: .6;
}

/* the toolbar sticks to the top of the viewport */
.g2-bar {
  position: sticky;
  top: 0;
  z-index: 40;
  margin-top: calc(var(--u) * 30);
  border-bottom: .5px solid var(--sg-ln);
  background: var(--bg);
}

.g2-bar__in {
  height: calc(var(--u) * 104);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.g2-search {
  width: calc(var(--u) * 520);
  height: calc(var(--u) * 64);
  flex-shrink: 0;
  padding: 0 calc(var(--u) * 22);
  border: .5px solid var(--sg-ln);
  border-radius: calc(var(--u) * 32);
  background: var(--surf);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.g2-search:focus-within {
  border-color: var(--acc);
}

.g2-search__ic {
  width: calc(var(--u) * 22);
  height: calc(var(--u) * 22);
  flex-shrink: 0;
  color: var(--mute);
}

.g2-search__in {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 18));
  font-weight: 300;
}

.g2-bar__div {
  width: .5px;
  height: calc(var(--u) * 44);
  margin: 0 calc(var(--u) * 8);
  background: var(--line2);
}

.g2-fl,
.g2-togs {
  display: contents;
}

.g2-fl__head,
.g2-fl__foot,
.g2-bar .g2-fopen {
  display: none;
}

.g2-pill {
  height: calc(var(--u) * 56);
  padding: 0 calc(var(--u) * 20);
  border: .5px solid var(--line2);
  border-radius: calc(var(--u) * 28);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 16));
  font-weight: 300;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
  cursor: pointer;
}

.g2-pill.is-on,
.g2-pill[aria-pressed="true"],
.g2-pill[aria-expanded="true"] {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--g2-inv);
}

.g2-dd {
  position: relative;
}

.g2-dd__c {
  font-size: max(12px, calc(var(--u) * 13));
  transition: transform .2s;
}

.g2-dd__b[aria-expanded="true"] .g2-dd__c {
  transform: rotate(180deg);
}

.g2-dd__p {
  position: absolute;
  left: 0;
  top: calc(var(--u) * 68);
  z-index: 50;
  width: calc(var(--u) * 380);
  margin: 0;
  padding: calc(var(--u) * 16);
  border: .5px solid var(--sg-ln);
  border-radius: calc(var(--u) * 28);
  background: var(--surf);
  box-shadow: var(--g2-panel-shadow);
}

.g2-opts {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.g2-opts li {
  position: relative;
}

/* real checkboxes / radios; the row is the label */
.g2-opt__in {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.g2-opt {
  height: calc(var(--u) * 52);
  padding: 0 calc(var(--u) * 14);
  border-radius: calc(var(--u) * 16);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 17));
  font-weight: 300;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
  cursor: pointer;
}

.g2-opt__box {
  width: calc(var(--u) * 22);
  height: calc(var(--u) * 22);
  flex-shrink: 0;
  border: 1.5px solid var(--line2);
  border-radius: calc(var(--u) * 6);
  color: #fff;
  font-size: max(12px, calc(var(--u) * 12));
  display: flex;
  align-items: center;
  justify-content: center;
}

.g2-opt--price .g2-opt__box {
  border-radius: 50%;
}

.g2-opt__in:checked + .g2-opt {
  background: var(--acc-a06);
}

.g2-opt__in:checked + .g2-opt .g2-opt__box {
  border-color: var(--acc);
  background: var(--acc);
}

.g2-opt__in:checked + .g2-opt--brand .g2-opt__box::before {
  content: "✓";
}

.g2-opt__in:checked + .g2-opt--price .g2-opt__box::before {
  content: "●";
}

.g2-opt__in:focus-visible + .g2-opt {
  outline: 2px solid var(--acc);
  outline-offset: -2px;
}

.g2-opt__n {
  margin-left: auto;
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

.g2-bar__r {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.g2-seg {
  padding: calc(var(--u) * 4);
  border: .5px solid var(--sg-ln);
  border-radius: calc(var(--u) * 30);
  background: var(--surf);
  display: flex;
}

.g2-seg__b {
  height: calc(var(--u) * 48);
  padding: 0 calc(var(--u) * 18);
  border: 0;
  border-radius: calc(var(--u) * 24);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 14));
  font-weight: 300;
  white-space: nowrap;
  cursor: pointer;
}

.g2-seg__v {
  width: calc(var(--u) * 56);
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.g2-seg__b.is-on {
  background: var(--ink);
  color: var(--g2-inv);
}

.g2-cart {
  height: calc(var(--u) * 64);
  padding: 0 calc(var(--u) * 24) 0 calc(var(--u) * 22);
  border: 0;
  border-radius: calc(var(--u) * 32);
  background: var(--ink);
  color: var(--g2-inv);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
  cursor: pointer;
  transition: transform .3s;
}

.g2-cart.is-bump {
  transform: scale(1.06);
}

.g2-cart__n {
  min-width: calc(var(--u) * 32);
  height: calc(var(--u) * 32);
  padding: 0 calc(var(--u) * 8);
  border-radius: calc(var(--u) * 16);
  background: var(--acc);
  color: #fff;
  font-size: max(12px, calc(var(--u) * 14));
  letter-spacing: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* == 145. Shop v2 — results, cards, list, pages ======================== */
.g2-res {
  margin-top: calc(var(--u) * 44);
  scroll-margin-top: calc(var(--u) * 120);
}

.g2-res__head {
  margin-bottom: calc(var(--u) * 30);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: calc(var(--u) * 30);
}

.g2-res__l {
  display: flex;
  align-items: baseline;
  gap: calc(var(--u) * 20);
}

.g2-res__t {
  font-size: max(12px, calc(var(--u) * 84));
  font-weight: 300;
  letter-spacing: -.05em;
  line-height: 1;
}

.g2-res__n {
  font-size: max(12px, calc(var(--u) * 22));
  font-weight: 300;
  color: var(--mute);
}

.g2-res__r {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: calc(var(--u) * 8);
}

.g2-active {
