  flex-wrap: wrap;
  justify-content: flex-end;
  gap: calc(var(--u) * 8);
}

.g2-active__b {
  height: calc(var(--u) * 44);
  padding: 0 calc(var(--u) * 10) 0 calc(var(--u) * 18);
  border: 0;
  border-radius: calc(var(--u) * 22);
  background: var(--sg-chip);
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 15));
  font-weight: 300;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
  cursor: pointer;
}

.g2-active__x {
  width: calc(var(--u) * 26);
  height: calc(var(--u) * 26);
  border-radius: 50%;
  background: var(--surf);
  font-size: max(12px, calc(var(--u) * 13));
  display: flex;
  align-items: center;
  justify-content: center;
}

.g2-clear {
  padding: 0 calc(var(--u) * 10);
  border: 0;
  background: transparent;
  color: var(--mute);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.82);
  cursor: pointer;
}

.g2-clear:hover {
  color: var(--acc);
}

.g2-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: calc(var(--u) * 16);
}

.g2-card {
  border: .5px solid transparent;
  border-radius: calc(var(--u) * 28);
  background: var(--surf);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color .25s;
}

.g2-card.is-in {
  border-color: var(--ok);
}

.g2-card.is-out,
.g2-row.is-out {
  opacity: .7;
}

.g2-card__ph {
