  height: calc(var(--u) * 360);
  background: var(--stripes);
  display: block;
}

.g2-card__slot {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 12));
  color: var(--mute);
  white-space: nowrap;
}

.g2-badges {
  position: absolute;
  left: calc(var(--u) * 14);
  top: calc(var(--u) * 14);
  display: flex;
  gap: calc(var(--u) * 6);
}

.g2-badges--row {
  position: static;
  margin-top: calc(var(--u) * 4);
}

.g2-badges--row:empty {
  display: none;
}

.g2-badge {
  height: calc(var(--u) * 28);
  padding: 0 calc(var(--u) * 11);
  border-radius: calc(var(--u) * 14);
  background: var(--shp-grey);
  color: #fff;
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.32);
  display: flex;
  align-items: center;
}

.g2-badge--sale {
  background: var(--acc);
}

.g2-badge--new {
  background: #111418;
}

.g2-fav {
  position: absolute;
  right: calc(var(--u) * 14);
  top: calc(var(--u) * 14);
  width: calc(var(--u) * 44);
  height: calc(var(--u) * 44);
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: var(--surf);
  color: var(--ink);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 18));
  cursor: pointer;
}

.g2-fav[aria-pressed="true"] {
  color: var(--acc);
}

.g2-card__b {
  flex: 1;
  padding: calc(var(--u) * 20) calc(var(--u) * 22) calc(var(--u) * 22);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 8);
}

.g2-card__meta {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  color: var(--mute);
  display: flex;
  justify-content: space-between;
}

.g2-card__n {
  min-height: calc(var(--u) * 52);
  font-size: max(12px, calc(var(--u) * 21));
  font-weight: 300;
  line-height: 1.25;
  text-wrap: pretty;
}

.g2-st {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 7);
}

.g2-st.is-ok {
  color: var(--ok);
}

.g2-st .ico {
  width: calc(var(--u) * 15);
  height: calc(var(--u) * 15);
  flex-shrink: 0;
}

.g2-card__foot {
  margin-top: auto;
  padding-top: calc(var(--u) * 12);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: calc(var(--u) * 10);
}

.g2-price {
  white-space: nowrap;
  display: flex;
  align-items: baseline;
  gap: calc(var(--u) * 8);
}

.g2-price__v {
  font-size: max(12px, calc(var(--u) * 28));
  font-weight: 300;
}

.g2-price__v.is-sale {
  color: var(--acc);
}

.g2-price__was {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

.g2-add {
  height: calc(var(--u) * 50);
  padding: 0 calc(var(--u) * 18);
  border: 0;
  border-radius: calc(var(--u) * 25);
  background: var(--acc);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.56);
  white-space: nowrap;
  cursor: pointer;
  transition: background .2s;
}

.g2-add.is-in {
  background: var(--ok);
}

.g2-add.is-out {
  background: var(--sg-chip);
  color: var(--ink);
}

.g2-add.is-out[aria-pressed="true"] {
  color: var(--ok);
}

/* the promo tile spans two columns */
.g2-promo {
  position: relative;
  grid-column: span 2;
  padding: calc(var(--u) * 50);
  border-radius: calc(var(--u) * 28);
  overflow: hidden;
  background: var(--g2-band);
  color: #f2f3f5;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: calc(var(--u) * 20);
}

.g2-promo > * {
  position: relative;
}

.g2-promo .g2-promo__big {
  position: absolute;
  right: calc(var(--u) * -40);
  bottom: calc(var(--u) * -80);
  font-family: "BBH Bartle", Geist, sans-serif;
  font-size: max(12px, calc(var(--u) * 360));
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1px var(--acc);
  opacity: .45;
}

.g2-promo__eb {
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.6);
  color: #7d838d;
}

.g2-promo__txt {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 16);
}

.g2-promo__t {
  max-width: calc(var(--u) * 640);
  font-size: max(12px, calc(var(--u) * 56));
  font-weight: 300;
  letter-spacing: -.035em;
  line-height: 1.02;
}

.g2-promo__d {
  max-width: calc(var(--u) * 560);
  font-size: max(12px, calc(var(--u) * 18));
  font-weight: 300;
  color: #a3a9b3;
}

.g2-promo__cta {
  align-self: flex-start;
  height: calc(var(--u) * 64);
  padding: 0 calc(var(--u) * 28);
  border: 0;
  border-radius: calc(var(--u) * 32);
  background: var(--acc);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.82);
  cursor: pointer;
}

/* list view: one surface card with rows */
.g2-list {
  padding: calc(var(--u) * 6) calc(var(--u) * 30);
  border-radius: calc(var(--u) * 28);
  background: var(--surf);
}

.g2-row {
  padding: calc(var(--u) * 22) 0;
  border-bottom: .5px solid var(--sg-ln);
  display: grid;
  grid-template-columns: calc(var(--u) * 240) minmax(0, 1fr) calc(var(--u) * 260) calc(var(--u) * 220);
  align-items: center;
  gap: calc(var(--u) * 36);
}

.g2-row.is-last {
  border-bottom: 0;
}

.g2-row__ph {
  height: calc(var(--u) * 180);
  border-radius: calc(var(--u) * 20);
  background: var(--stripes);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 11));
  color: var(--mute);
  display: flex;
  align-items: center;
  justify-content: center;
}

.g2-row__main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 8);
}

.g2-row__meta {
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
  color: var(--mute);
  display: flex;
  flex-wrap: wrap;
  gap: 0 calc(var(--u) * 14);
}

.g2-row__n {
  font-size: max(12px, calc(var(--u) * 28));
  font-weight: 300;
  letter-spacing: -.02em;
}

.g2-row__d {
  font-size: max(12px, calc(var(--u) * 16));
  font-weight: 300;
  color: var(--body);
}

.g2-row__st {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 8);
}

.g2-row__st .g2-st {
  font-size: max(12px, calc(var(--u) * 15));
}

.g2-row__ship {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

.g2-row__buy {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: calc(var(--u) * 12);
}

.g2-price--row .g2-price__v {
  font-size: max(12px, calc(var(--u) * 32));
}

.g2-price--row .g2-price__was {
  font-size: max(12px, calc(var(--u) * 15));
}

.g2-add--row {
  height: calc(var(--u) * 54);
  padding: 0 calc(var(--u) * 24);
}

.g2-empty {
  padding: calc(var(--u) * 80);
  border-radius: calc(var(--u) * 28);
  background: var(--surf);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--u) * 18);
}

.g2-empty__t {
  font-size: max(12px, calc(var(--u) * 36));
  font-weight: 300;
}

.g2-empty__b {
  height: calc(var(--u) * 60);
  padding: 0 calc(var(--u) * 28);
  border: 0;
  border-radius: calc(var(--u) * 30);
  background: var(--acc);
  color: #fff;
  font: inherit;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.82);
  cursor: pointer;
}

.g2-pg {
  margin-top: calc(var(--u) * 50);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: calc(var(--u) * 20);
}

.g2-pg__range,
.g2-pg__per {
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--mute);
}

.g2-pg__nav,
.g2-pg__nums {
  display: flex;
  gap: calc(var(--u) * 8);
}

.g2-pg__prev,
.g2-pg__next {
  height: calc(var(--u) * 60);
  padding: 0 calc(var(--u) * 22);
  border: .5px solid var(--line2);
  border-radius: calc(var(--u) * 30);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 14));
  cursor: pointer;
}

.g2-pg__next {
  border: 0;
  background: var(--acc);
  color: #fff;
}

.g2-pg__prev:disabled,
.g2-pg__next:disabled {
  opacity: .35;
  cursor: default;
}

.g2-pg__n {
  width: calc(var(--u) * 60);
  height: calc(var(--u) * 60);
  border: .5px solid var(--line2);
  border-radius: 50%;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 17));
  font-weight: 300;
  cursor: pointer;
}

.g2-pg__n.is-on {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--g2-inv);
}

/* == 146. Shop v2 — smaller screens ==================================== */
@media (max-width: 1199px) {
  .g2-tiles-nav {
    margin: 0;
  }

  .g2-tiles {
    padding: 0 var(--gut) 4px;
    grid-template-columns: none;
    grid-auto-flow: column;
    grid-auto-columns: 150px;
    gap: 10px;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scroll-padding: 0 var(--gut);
    scrollbar-width: none;
  }

  .g2-tiles > li {
