    font-weight: 300;
  }

  .g2-fl__x {
    width: 40px;
    height: 40px;
    padding: 0;
    border: .5px solid var(--line2);
    border-radius: 50%;
    background: transparent;
    color: var(--ink);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
  }

  .g2-fl__foot {
    display: block;
  }

  .g2-fl__done {
    width: 100%;
    height: 54px;
    border: 0;
    border-radius: 27px;
    background: var(--acc);
    color: #fff;
    font: inherit;
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: .14em;
    cursor: pointer;
  }

  .g2-togs {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  /* inside the sheet the dropdown panels are always open lists */
  .g2-dd__b {
    pointer-events: none;
    height: auto;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--mute);
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: .18em;
  }

  .g2-dd__b[aria-expanded="true"] {
    background: transparent;
    color: var(--mute);
  }

  .g2-dd__c {
    display: none;
  }

  .g2-fl .g2-dd__p[hidden] {
    display: block !important;
  }

  .g2-dd__p {
    position: static;
    width: auto;
    margin-top: 8px;
    padding: 0;
    border: 0;
