  }

  .g2-opt {
    height: 44px;
    padding: 0 8px;
    font-size: 16px;
  }

  .g2-opt__box {
    width: 22px;
    height: 22px;
    font-size: 12px;
  }

  .g2-opt__n {
    font-size: 13px;
  }

  .g2-bar__r {
    margin-left: auto;
  }

  .g2-seg--sort {
    display: none;
  }

  .g2-seg__v {
    width: 44px;
    height: 40px;
  }

  .g2-cart {
    height: 46px;
    padding: 0 16px;
    font-size: 13px;
    gap: 8px;
  }

  .g2-cart__n {
    min-width: 24px;
    height: 24px;
    font-size: 12px;
  }

  .g2-res {
    margin-top: 28px;
    scroll-margin-top: 140px;
  }

  .g2-res__head {
    flex-wrap: wrap;
    align-items: flex-start;
    gap: 14px;
  }

  .g2-res__l {
    flex-wrap: wrap;
    gap: 6px 14px;
  }

  .g2-res__t {
    font-size: 44px;
  }

  .g2-res__n {
    font-size: 16px;
  }

  .g2-res__r,
  .g2-active {
    justify-content: flex-start;
  }

  .g2-active__b {
    height: 38px;
    font-size: 14px;
  }

  .g2-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
  }

  .g2-card {
    border-radius: 22px;
  }

  .g2-card__ph {
    height: auto;
    aspect-ratio: 4 / 3;
  }

  .g2-badges {
    right: 62px;
    flex-wrap: wrap;
  }

  .g2-badge {
    height: 24px;
    padding: 0 9px;
    font-size: 12px;
    letter-spacing: .08em;
  }

  .g2-fav {
    width: 40px;
    height: 40px;
    font-size: 17px;
  }

  .g2-card__b {
    padding: 16px 16px 18px;
  }

  .g2-card__meta {
    font-size: 12px;
    letter-spacing: .1em;
  }

  .g2-card__n {
    min-height: 2.5em;
