    bottom: -40px;
    font-size: 200px;
  }

  .g2-promo__t {
    font-size: 34px;
  }

  .g2-promo__d {
    font-size: 16px;
  }

  .g2-promo__cta {
    height: 52px;
    padding: 0 22px;
    font-size: 12px;
  }

  .g2-list {
    padding: 4px 18px;
    border-radius: 22px;
  }

  .g2-row {
    padding: 16px 0;
    grid-template-columns: 120px minmax(0, 1fr);
    gap: 10px 16px;
  }

  .g2-row__ph {
    height: 90px;
    grid-row: span 2;
    border-radius: 14px;
    font-size: 12px;
    text-align: center;
  }

  .g2-row__st {
    grid-column: 2;
  }

  .g2-row__buy {
    grid-column: 1 / -1;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .g2-row__meta {
    font-size: 12px;
    letter-spacing: .08em;
  }

  .g2-row__n {
    font-size: 19px;
  }

  .g2-row__d {
    font-size: 14px;
  }

  .g2-price--row .g2-price__v {
