@media (max-width: 767px) {
  .g2-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .g2-card__b {
    padding: 12px 12px 14px;
  }

  .g2-card__meta {
    flex-direction: column;
    gap: 2px;
  }

  .g2-card__n {
    font-size: 15px;
  }

  .g2-card__foot {
    flex-wrap: wrap;
  }

  .g2-grid .g2-add {
    width: 100%;
  }

  .g2-card__slot {
    width: 80%;
    font-size: 12px;
    white-space: normal;
    text-align: center;
  }

  .g2-seg--view {
    display: none;
  }

  .g2-row {
    grid-template-columns: 88px minmax(0, 1fr);
  }

  .g2-row__ph {
    height: 72px;
  }

  .g2-pg__per {
    display: none;
  }
}

/* == 147. Shop single v1 — hero: gallery and buy column ================= */
:root {
  --pd-night: #0e1013;
  --pd-inv: #fff;
  --pd-ok: #2fa36b;
  --pd-ok14: rgba(47, 163, 107, .14);
  --pd-ok40: rgba(47, 163, 107, .4);
  --pd-ease: cubic-bezier(.2, .7, .2, 1);
  --pd-stripes-night: repeating-linear-gradient(135deg, #1a1d22 0 calc(var(--u) * 14), #14161a calc(var(--u) * 14) calc(var(--u) * 28));
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --pd-inv: #111418;
  }
}

:root[data-theme="dark"] {
  --pd-inv: #111418;
}

.pd {
  font-weight: 400;
}

/* variant swaps: the root carries data-axle / data-comp */
.pd[data-axle="0"] .pd-ax1,
.pd[data-axle="1"] .pd-ax0,
.pd[data-comp="0"] .pd-c1,
.pd[data-comp="1"] .pd-c0 {
  display: none !important;
}

.pd-sec {
  padding-top: calc(var(--u) * 110);
}

.pd-h__r {
  font-size: max(12px, calc(var(--u) * 18));
  font-weight: 300;
  color: var(--mute);
}

.pd-h__ctl {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 26);
}

.pd-h__link {
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.24);
  text-decoration: none;
}

.pd-h__link:hover {
  color: var(--acc);
}

.pd-h__pill {
  height: calc(var(--u) * 50);
  padding: 0 calc(var(--u) * 22);
  border: .5px solid var(--line2);
  border-radius: calc(var(--u) * 25);
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.82);
  cursor: pointer;
}

.pd-hero {
  padding-top: calc(var(--u) * 50);
  display: grid;
  grid-template-columns: minmax(0, 1fr) calc(var(--u) * 980);
  align-items: start;
  gap: calc(var(--u) * 80);
}

.pd-gal {
  display: grid;
  grid-template-columns: calc(var(--u) * 150) minmax(0, 1fr);
  gap: calc(var(--u) * 16);
}

.pd-thumbs {
  height: calc(var(--u) * 1180);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.pd-thumbs li {
  flex: 1;
  min-height: 0;
}

.pd-th {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 1.5px solid transparent;
  border-radius: calc(var(--u) * 22);
  overflow: hidden;
  background: repeating-linear-gradient(135deg, var(--s1) 0 calc(var(--u) * 10), var(--s2) calc(var(--u) * 10) calc(var(--u) * 20));
  color: var(--mute);
  font: inherit;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: calc(var(--u) * 6);
  cursor: pointer;
  transition: border-color .2s;
}

.pd-th.is-on {
  border-color: var(--acc);
}

.pd-th__img,
.pd-frame__img,
.pd-bti__img,
.pd-rc__img,
.pd-wr__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.pd-th__slot {
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 10));
