/* == 151. Shop single v2 — showroom hero ================================ */
:root {
  --p2-P: #fff;
  --p2-K: #f5f6f8;
  --p2-C: #f2f3f5;
  --p2-I: #f2f3f5;
  --p2-L: rgba(17, 20, 24, .1);
  --p2-L2: rgba(17, 20, 24, .2);
  --p2-sh: 0 calc(var(--u) * 40) calc(var(--u) * 100) rgba(17, 20, 24, .08);
  --p2-warn: #e0a03a;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --p2-P: #0e1013;
    --p2-K: #15171b;
    --p2-C: rgba(242, 243, 245, .06);
    --p2-I: #14161a;
    --p2-L: rgba(242, 243, 245, .12);
    --p2-L2: rgba(242, 243, 245, .22);
    --p2-sh: none;
  }
}

:root[data-theme="dark"] {
  --p2-P: #0e1013;
  --p2-K: #15171b;
  --p2-C: rgba(242, 243, 245, .06);
  --p2-I: #14161a;
  --p2-L: rgba(242, 243, 245, .12);
  --p2-L2: rgba(242, 243, 245, .22);
  --p2-sh: none;
}

.p2-ok {
  color: var(--pd-ok);
}

.p2-n {
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 14));
  letter-spacing: calc(var(--u) * 1.4);
  color: var(--acc);
  margin-right: calc(var(--u) * 24);
  vertical-align: .9em;
}

.p2-k {
  margin: 0;
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.34);
  color: var(--mute);
  text-align: left;
}

.p2-heroWrap {
  padding-top: calc(var(--u) * 50);
}

.p2-hero {
  min-height: calc(var(--u) * 1220);
  padding: calc(var(--u) * 20);
  border-radius: calc(var(--u) * 44);
  background: var(--p2-P);
  color: var(--ink);
  box-shadow: var(--p2-sh);
  display: grid;
  grid-template-columns: calc(var(--u) * 124) minmax(0, 1fr) calc(var(--u) * 940);
  gap: calc(var(--u) * 16);
}

/* thumb rail */
.p2-rail {
  margin: 0;
  padding: calc(var(--u) * 20) 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

.p2-rail > li {
  flex: 1;
  display: flex;
}

.p2-th {
  position: relative;
  flex: 1;
  min-height: calc(var(--u) * 80);
  padding: 0;
  border: 1.5px solid transparent;
  border-radius: calc(var(--u) * 22);
  background: var(--p2-I);
  overflow: hidden;
  cursor: pointer;
  transition: border-color .2s;
}

.p2-th__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.p2-th__bar {
  position: absolute;
  left: 0;
  bottom: 0;
  height: calc(var(--u) * 4);
  width: 0;
  background: var(--acc);
  transition: width .4s;
}

.p2[data-mode="photos"] .p2-th.is-on {
  border-color: var(--acc);
}

.p2[data-mode="photos"] .p2-th.is-on .p2-th__bar {
  width: 100%;
}

/* stage */
.p2-stage {
  position: relative;
  overflow: hidden;
  border-radius: calc(var(--u) * 34);
  background: var(--p2-I);
}

.p2-stage__photos,
.p2-stage__spin,
.p2-stage__video {
  position: absolute;
  inset: 0;
}

.p2[data-mode="photos"] .p2-stage__spin,
.p2[data-mode="photos"] .p2-stage__video,
.p2[data-mode="photos"] .p2-spin,
.p2[data-mode="spin"] .p2-stage__photos,
.p2[data-mode="spin"] .p2-stage__video,
.p2[data-mode="spin"] .p2-nav,
.p2[data-mode="video"] .p2-stage__photos,
.p2[data-mode="video"] .p2-stage__spin,
.p2[data-mode="video"] .p2-spin,
.p2[data-mode="video"] .p2-nav {
  display: none;
}

.p2-frame {
  position: absolute;
  inset: 0;
  display: none;
}

.p2-frame.is-on {
  display: block;
}

.p2-frame__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.p2-stage__slot {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(135deg, var(--s1) 0 calc(var(--u) * 14), var(--s2) calc(var(--u) * 14) calc(var(--u) * 28));
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: calc(var(--u) * 10);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 13));
  color: var(--mute);
}

.p2-stage__l {
  font-family: Geist, Helvetica, Arial, sans-serif;
  font-size: max(12px, calc(var(--u) * 15));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 3.3);
  color: var(--body);
}

.p2-play {
  position: absolute;
  left: 50%;
  top: 50%;
  width: calc(var(--u) * 110);
  height: calc(var(--u) * 110);
  padding-left: calc(var(--u) * 8);
  border-radius: 50%;
  background: var(--acc);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: max(12px, calc(var(--u) * 34));
  transform: translate(-50%, -50%) translateY(calc(var(--u) * -90));
  box-shadow: 0 0 0 calc(var(--u) * 18) var(--acc-a18);
}

.p2-ghost {
  position: absolute;
  left: calc(var(--u) * 44);
  bottom: calc(var(--u) * 6);
  font-family: 'BBH Bartle', Geist, sans-serif;
  font-size: max(12px, calc(var(--u) * 190));
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1.5px var(--acc-a40);
  white-space: nowrap;
  pointer-events: none;
}

.p2-mode {
  position: absolute;
  left: calc(var(--u) * 30);
  top: calc(var(--u) * 30);
  margin: 0;
  padding: calc(var(--u) * 5);
  border: 0;
  border-radius: calc(var(--u) * 30);
  background: var(--p2-P);
  box-shadow: 0 calc(var(--u) * 8) calc(var(--u) * 24) rgba(8, 9, 11, .12);
}

.p2-mode__ul,
.p2-comp__ul,
.p2-ax__ul,
.p2-cars,
.p2-slots__ul {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
}

.p2-mode__in,
.p2-comp__in,
.p2-ax__in,
.p2-slot__in,
.p2-ki__in {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
}

.p2-mode__b {
  height: calc(var(--u) * 46);
  padding: 0 calc(var(--u) * 20);
  border-radius: calc(var(--u) * 23);
  display: flex;
  align-items: center;
  font-size: max(12px, calc(var(--u) * 14));
  white-space: nowrap;
  cursor: pointer;
  transition: background .2s, color .2s;
}

.p2-mode__in:checked + .p2-mode__b {
  background: var(--acc);
  color: #fff;
}

.p2-mode__in:focus-visible + .p2-mode__b,
.p2-ax__in:focus-visible + .p2-ax__b,
.p2-slot__in:focus-visible + .p2-slot__b,
.p2-ki__in:focus-visible + .p2-ki__lab {
  outline: 2px solid var(--acc);
  outline-offset: 2px;
}

.p2-tr {
  position: absolute;
  right: calc(var(--u) * 30);
  top: calc(var(--u) * 30);
  margin: 0;
  display: flex;
  gap: calc(var(--u) * 8);
}

.p2-oem {
  height: calc(var(--u) * 46);
  padding: 0 calc(var(--u) * 16);
  border-radius: calc(var(--u) * 23);
  background: var(--acc);
  color: #fff;
  display: flex;
  align-items: center;
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
}

.p2-fav {
  width: calc(var(--u) * 46);
  height: calc(var(--u) * 46);
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: var(--p2-P);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 18));
  cursor: pointer;
}

.p2-fav[aria-pressed="true"] {
  color: var(--acc);
}

.p2-nav {
  position: absolute;
  right: calc(var(--u) * 30);
  bottom: calc(var(--u) * 30);
  margin: 0;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.p2-nav__n {
  height: calc(var(--u) * 56);
  padding: 0 calc(var(--u) * 18);
  border-radius: calc(var(--u) * 28);
  background: var(--p2-P);
  display: flex;
  align-items: center;
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 15));
}

.p2-nav__b {
  width: calc(var(--u) * 60);
  height: calc(var(--u) * 60);
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: var(--p2-P);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 20));
  cursor: pointer;
}

.p2-nav__b--acc {
  background: var(--acc);
  color: #fff;
}

.p2-spin {
  position: absolute;
  left: 50%;
  bottom: calc(var(--u) * 40);
  width: calc(var(--u) * 640);
  max-width: calc(100% - 40px);
  margin: 0;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.p2-spin__v {
  height: calc(var(--u) * 40);
  padding: 0 calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
  background: var(--p2-P);
  display: flex;
  align-items: center;
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 14));
}

.p2-spin__in {
  width: 100%;
  accent-color: var(--acc);
  cursor: ew-resize;
}

/* buy column */
.p2-buy {
  min-width: 0;
  padding: calc(var(--u) * 46) calc(var(--u) * 48) calc(var(--u) * 40);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 28);
}

.p2-meta {
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: calc(var(--u) * 16);
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.34);
  color: var(--mute);
  white-space: nowrap;
}

.p2-rate {
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 16));
  text-transform: none;
  letter-spacing: 0;
  text-decoration: none;
}

.p2-rate .acc {
  letter-spacing: calc(var(--u) * 3);
}

.p2-title {
  margin: 0;
  font-size: max(12px, calc(var(--u) * 80));
  font-weight: 300;
  letter-spacing: -.06em;
  line-height: .98;
}

.p2-price {
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: calc(var(--u) * 14) calc(var(--u) * 18);
}

.p2-price__v {
  font-family: 'BBH Bartle', Geist, sans-serif;
  font-size: max(12px, calc(var(--u) * 128));
  line-height: .8;
  color: var(--acc);
  white-space: nowrap;
}

.p2-price__s {
  padding-bottom: calc(var(--u) * 4);
  white-space: nowrap;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
  font-size: max(12px, calc(var(--u) * 16));
  color: var(--body);
}

.p2-price__q {
  color: var(--ink);
}

.p2-cmp {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 16);
}

.p2-comp {
  position: relative;
  margin: 0;
  padding: calc(var(--u) * 6);
  border: 0;
  border-radius: calc(var(--u) * 42);
  background: var(--p2-C);
}

.p2-comp__ind {
  position: absolute;
  top: calc(var(--u) * 6);
  bottom: calc(var(--u) * 6);
  left: calc(var(--u) * 6);
  width: calc(50% - calc(var(--u) * 6));
  border-radius: calc(var(--u) * 36);
  background: var(--acc);
  transition: left .35s var(--pd-ease);
}

.p2[data-comp="1"] .p2-comp__ind {
  left: 50%;
}

.p2-comp__ul > li {
  flex: 1;
}

.p2-comp__b {
  position: relative;
  height: calc(var(--u) * 76);
  border-radius: calc(var(--u) * 36);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: calc(var(--u) * 2);
  cursor: pointer;
  transition: color .25s;
}

.p2-comp__in:checked + .p2-comp__b {
  color: #fff;
