/* == 165. Shop v4 — tablet and phone =================================== */
@media (max-width: 1599px) and (min-width: 1200px) {
  .s4grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 1199px) {
  .s4gap {
    height: 20px;
  }

  .s4cat {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }

  /* the filters fold behind a Filters button above the results */
  .s4side {
    position: static;
    order: 2;
    padding: 24px;
    border-radius: 24px;
  }

  .s4side:not(.is-open) {
    display: none;
  }

  .s4res {
    display: contents;
  }

  .s4bar {
    order: 1;
  }

  .s4grid,
  .s4empty,
  .s4pg {
    order: 3;
  }

  .s4bar__f {
    height: 48px;
    padding: 0 20px;
    border: .5px solid var(--line2);
    border-radius: 24px;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: .14em;
  }

  .s4bar__f[aria-expanded="true"] {
    border-color: var(--ink);
    background: var(--ink);
    color: var(--pd-inv);
  }

  .s4grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .s4bar__sort {
    margin-left: 0;
    width: 100%;
    overflow-x: auto;
  }
}

@media (max-width: 899px) {
  .s4grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .s4c {
    padding: 16px;
    gap: 14px;
  }

  .s4c__ph {
    height: auto;
    aspect-ratio: 420 / 300;
  }
}

@media (max-width: 767px) {
  .s4pg {
    flex-wrap: wrap;
    justify-content: center;
  }

  /* phone: Prev · Page N of M · Next */
  .s4pg__k:first-child,
  .s4pg__nums {
    display: none;
  }

  .s4pg__k:last-child {
    order: -1;
    width: 100%;
    text-align: center;
  }
}

@media (max-width: 559px) {
  .s4grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .s4c__ph {
    aspect-ratio: 840 / 600;
  }

  .s4c__name {
    font-size: 20px;
  }
}

