  left: 0;
  top: 0;
  bottom: 0;
  width: calc(var(--u) * 10);
  background: repeating-linear-gradient(180deg, rgba(17, 20, 24, .28) 0 1px, transparent 1px calc(var(--u) * 20));
}

[data-theme="dark"] .blp__ticks {
  background: repeating-linear-gradient(180deg, rgba(242, 243, 245, .3) 0 1px, transparent 1px calc(var(--u) * 20));
}

.blp__grow {
  position: absolute;
  left: 0;
  top: 0;
  width: 2px;
  height: 0;
  background: var(--acc);
  transition: height .8s var(--pd-ease);
}

.blp:hover .blp__grow {
  height: 100%;
}

.blp__n {
  font-family: 'BBH Bartle', Geist, sans-serif;
  font-size: max(12px, calc(var(--u) * 94));
  line-height: .85;
  color: transparent;
  -webkit-text-stroke: 1px var(--acc);
  transition: color .35s;
}

.blp:hover .blp__n {
  color: var(--acc);
}

.blp__spec {
  margin: 0;
  border-top: .5px solid var(--line2);
}

.blp__row {
  padding: calc(var(--u) * 14) 0;
  border-bottom: .5px solid var(--sg-ln);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.blp__row dt,
.blp__rk {
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.98);
  color: var(--mute);
}

.blp__sv {
  margin: 0;
  font-size: max(12px, calc(var(--u) * 17));
}

.blp__sv--acc {
  color: var(--acc);
}

.blp__sv--tags {
  color: var(--body);
  white-space: pre-wrap;
}

.blp__read {
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 8);
}

.blp__gauge {
  display: flex;
  gap: calc(var(--u) * 3);
}

.blp__seg {
  flex: 1;
  height: calc(var(--u) * 14);
  border-radius: 2px;
  background: rgba(17, 20, 24, .08);
  transition: background .3s;
}

.blp__seg.is-on {
  background: rgba(17, 20, 24, .28);
}

[data-theme="dark"] .blp__seg {
  background: rgba(242, 243, 245, .08);
}

[data-theme="dark"] .blp__seg.is-on {
  background: rgba(242, 243, 245, .3);
}

.blp:hover .blp__seg.is-on {
  background: var(--acc);
}

.blp__seg:nth-child(2) { transition-delay: .04s; }
.blp__seg:nth-child(3) { transition-delay: .08s; }
.blp__seg:nth-child(4) { transition-delay: .12s; }
.blp__seg:nth-child(5) { transition-delay: .16s; }
.blp__seg:nth-child(6) { transition-delay: .2s; }
.blp__seg:nth-child(7) { transition-delay: .24s; }
.blp__seg:nth-child(8) { transition-delay: .28s; }
.blp__seg:nth-child(9) { transition-delay: .32s; }
.blp__seg:nth-child(10) { transition-delay: .36s; }
.blp__seg:nth-child(11) { transition-delay: .4s; }
.blp__seg:nth-child(12) { transition-delay: .44s; }

/* content: cover, title, excerpt, Read story */
.blp__body {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 28);
}

.blp__cover {
  position: relative;
  display: block;
  height: calc(var(--u) * 760);
  border-radius: calc(var(--u) * 32);
  overflow: hidden;
  isolation: isolate;
  background: var(--stripes);
}

.blp__img,
.blp__slot {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transition: transform .9s var(--pd-ease);
}

.blp__img {
  object-fit: cover;
  object-position: 50% 62%;
}

.blp__slot {
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 12));
  color: var(--mute);
}

.blp:hover .blp__img,
.blp:hover .blp__slot {
  transform: scale(1.04);
}

.blp__cap {
  position: absolute;
  left: calc(var(--u) * 26);
  bottom: calc(var(--u) * 24);
  padding: calc(var(--u) * 8) calc(var(--u) * 12);
  border-radius: calc(var(--u) * 10);
  background: var(--surf);
  color: var(--body);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 12));
  letter-spacing: calc(var(--u) * 0.72);
}

.blp__go {
  position: absolute;
  right: calc(var(--u) * 24);
  top: calc(var(--u) * 24);
  width: calc(var(--u) * 76);
  height: calc(var(--u) * 76);
  border-radius: 50%;
  background: var(--surf);
  color: var(--ink);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: max(12px, calc(var(--u) * 26));
  opacity: 0;
  transform: scale(.6) rotate(-45deg);
  transition: transform .4s var(--pd-ease), opacity .4s var(--pd-ease);
}

.blp:hover .blp__go {
  opacity: 1;
  transform: none;
}

.blp__t {
  margin: 0;
  font-size: max(12px, calc(var(--u) * 64));
  font-weight: 300;
  letter-spacing: -.045em;
  line-height: 1.02;
  text-wrap: balance;
}

.blp__t a {
  transition: color .25s;
}

.blp:hover .blp__t a {
  color: var(--acc);
}

.blp__foot {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: calc(var(--u) * 48);
  align-items: end;
}

.blp__x {
  max-width: calc(var(--u) * 900);
  margin: 0;
  font-size: max(12px, calc(var(--u) * 22));
  font-weight: 300;
  line-height: 1.6;
  color: var(--body);
  text-wrap: pretty;
}

.blp__more {
  height: calc(var(--u) * 68);
  padding: 0 calc(var(--u) * 8) 0 calc(var(--u) * 30);
  border: .5px solid var(--line2);
  border-radius: calc(var(--u) * 34);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 18);
  font-size: max(12px, calc(var(--u) * 13));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.08);
  white-space: nowrap;
  transition: background .3s, color .3s, border-color .3s;
}

.blp:hover .blp__more,
.blp__more:hover {
  border-color: var(--ink);
  background: var(--ink);
  color: var(--pd-inv);
}

.blp__mdisc {
  width: calc(var(--u) * 52);
  height: calc(var(--u) * 52);
  border-radius: 50%;
  background: var(--acc);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
}

.blpg {
  margin-top: 0;
  padding-top: 0;
  border-top: 0;
}

/* == 167. Blog — spec-sheet sidebar ===================================== */
.blside {
  position: sticky;
  top: 20px;
  align-self: start;
  min-width: 0;
  border: .5px solid var(--line2);
  display: flex;
  flex-direction: column;
}

.blside__tk {
  position: absolute;
  width: calc(var(--u) * 16);
  height: calc(var(--u) * 16);
  border: 0 solid var(--acc);
}

.blside__tk--a {
  left: -1px;
  top: -1px;
  border-left-width: 1px;
  border-top-width: 1px;
}

.blside__tk--b {
  right: -1px;
  bottom: -1px;
  border-right-width: 1px;
  border-bottom-width: 1px;
}

.blsearch {
  height: calc(var(--u) * 68);
  padding: 0 calc(var(--u) * 22);
  border-bottom: .5px solid var(--line2);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.blsearch__k {
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 12));
  color: var(--acc);
}

.blsearch__in {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: none;
  background: transparent;
  font-size: max(12px, calc(var(--u) * 18));
  font-weight: 300;
}

.blsearch__in::placeholder {
  color: var(--mute);
}

.blsearch:focus-within {
  box-shadow: inset 0 -2px 0 var(--acc);
}

.blside__h {
  margin: 0;
  padding: calc(var(--u) * 14) calc(var(--u) * 22);
  border-bottom: .5px solid var(--line2);
  display: flex;
  justify-content: space-between;
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 2.2);
  color: var(--mute);
}

.blside__h--last {
  border-bottom: 0;
}

.blcats,
.bltags,
.blpops,
.blarcs,
.blfols {
  margin: 0;
  padding: 0;
  list-style: none;
}

.blcats {
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.blcats > li:nth-child(odd) {
  border-right: .5px solid var(--line2);
}

.blcat {
  width: 100%;
  height: calc(var(--u) * 92);
  padding: calc(var(--u) * 16) calc(var(--u) * 20);
  border-bottom: .5px solid var(--line2);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-start;
  text-align: left;
  transition: background .2s;
}

.blcat__n {
  font-family: 'BBH Bartle', Geist, sans-serif;
  font-size: max(12px, calc(var(--u) * 24));
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1px var(--acc);
  transition: color .2s;
}

.blcat__t {
  font-size: max(12px, calc(var(--u) * 15));
  font-weight: 300;
}

.blcat:hover,
.blcat[aria-pressed="true"] {
  background: var(--surf);
}

.blcat[aria-pressed="true"] {
  color: var(--acc);
}

.blcat[aria-pressed="true"] .blcat__n {
  color: var(--acc);
}

.bltags {
  padding: calc(var(--u) * 18) calc(var(--u) * 22);
  border-bottom: .5px solid var(--line2);
  display: flex;
  flex-wrap: wrap;
  gap: calc(var(--u) * 8);
}

.bltag {
  height: calc(var(--u) * 36);
  padding: 0 calc(var(--u) * 14);
  border: .5px solid var(--line2);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 13));
}

.bltag:hover {
  border-color: var(--acc);
}

.bltag[aria-pressed="true"] {
  border-color: var(--acc);
  background: var(--acc);
  color: #fff;
}

.blpop {
  padding: calc(var(--u) * 16) calc(var(--u) * 22);
  border-bottom: .5px solid var(--sg-ln);
  display: grid;
  grid-template-columns: calc(var(--u) * 40) minmax(0, 1fr);
  gap: calc(var(--u) * 12);
}

.blpop__n {
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 13));
  color: var(--acc);
}

.blpop__b {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.blpop__t {
  font-size: max(12px, calc(var(--u) * 16));
  font-weight: 300;
  line-height: 1.3;
}

.blpop__m {
  font-size: max(12px, calc(var(--u) * 12));
  color: var(--mute);
}

.blarcs {
  border-bottom: .5px solid var(--line2);
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.blarcs > li:nth-child(odd) {
  border-right: .5px solid var(--line2);
}

.blarcs > li:nth-child(-n+2) {
  border-bottom: .5px solid var(--line2);
}

.blarcs > li:only-child {
  grid-column: 1 / -1;
  border: 0;
}

.blarc {
  height: calc(var(--u) * 70);
  padding: 0 calc(var(--u) * 20);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: calc(var(--u) * 4);
}

.blarc__t {
  font-size: max(12px, calc(var(--u) * 15));
  font-weight: 300;
}

.blarc__n {
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 11));
  color: var(--mute);
}

.blnews {
  padding: calc(var(--u) * 22);
  border-bottom: .5px solid var(--line2);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.blnews__t {
  margin: 0;
  font-size: max(12px, calc(var(--u) * 22));
  font-weight: 300;
  line-height: 1.2;
}

.blnews__f {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.blnews__f[hidden],
.blnews__ok[hidden] {
  display: none;
}

.blnews__row {
  border: .5px solid rgba(128, 132, 140, .5);
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
}

.blnews__row.is-err {
  border-color: var(--acc);
}

.blnews__in {
  min-width: 0;
  height: calc(var(--u) * 56);
  padding: 0 calc(var(--u) * 16);
  border: 0;
  outline: none;
  background: transparent;
  font-size: max(12px, calc(var(--u) * 16));
  font-weight: 300;
}

.blnews__in::placeholder {
  color: var(--mute);
}

.blnews__b {
  height: calc(var(--u) * 56);
  padding: 0 calc(var(--u) * 20);
  background: var(--ink);
  color: var(--pd-inv);
  font-size: max(12px, calc(var(--u) * 12));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.68);
}

.blnews__e {
  min-height: calc(var(--u) * 16);
  font-size: max(12px, calc(var(--u) * 13));
  color: var(--acc);
}

.blnews__ok {
  margin: 0;
  font-size: max(12px, calc(var(--u) * 15));
  color: var(--pd-ok);
}

.blfols {
  border-top: .5px solid var(--line2);
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.blfols > li:not(:last-child) {
  border-right: .5px solid var(--line2);
}

.blfol {
  height: calc(var(--u) * 60);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 13));
}

/* == 168. Blog — tablet and phone ======================================= */
@media (max-width: 1599px) {
  .bl {
    grid-template-columns: minmax(0, 1fr);
    gap: 40px;
  }

  .blside {
    position: relative;
    top: auto !important;
    order: -1;
  }

  .blside .blpops,
  .blside .blarcs,
  .blside .blnews,
  .blside .blfols,
  .blside .blside__h:nth-of-type(n+3) {
    display: none;
  }

  .blcats {
    grid-template-columns: repeat(4, 1fr);
  }

  .blcats > li {
    border-right: .5px solid var(--line2);
  }

  .blcats > li:nth-child(4n) {
    border-right: 0;
  }

  .blp {
    grid-template-columns: minmax(0, 1fr);
  }

  .blp__rail {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
    gap: 16px 28px;
  }

  .blp__spec {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 0 20px;
  }

  .blp__read {
    grid-column: 1 / -1;
  }
}

@media (max-width: 767px) {
  .blcats {
    grid-template-columns: 1fr 1fr;
  }

  .blcats > li:nth-child(odd) {
    border-right: .5px solid var(--line2);
  }

  .blcats > li:nth-child(even) {
    border-right: 0;
  }

  .blcat {
    height: 72px;
    padding: 12px 16px;
  }

  .blp {
    margin-bottom: 40px;
    padding-bottom: 40px;
    gap: 22px;
  }

  .blp__cover {
    height: auto;
    aspect-ratio: 1712 / 760;
    border-radius: 20px;
  }

  .blp__cap {
    display: none;
  }

  .blp__rail {
    grid-template-columns: minmax(0, 1fr);
  }

  .blp__n {
    font-size: 56px;
  }

  .blp__spec {
    grid-template-columns: 1fr 1fr;
  }

  .blp__t {
    font-size: 32px;
  }

  .blp__foot {
    grid-template-columns: minmax(0, 1fr);
    gap: 18px;
  }

  .blp__x {
    font-size: 17px;
  }

  .blp__more {
    justify-self: start;
  }
}

/* == 169. Blog post — hero, fact strip, rail, text ====================== */
:root {
  --bp-body: #2a2e35;
  --bp-tick: rgba(17, 20, 24, .28);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bp-body: #d6d9de;
    --bp-tick: rgba(242, 243, 245, .3);
  }
}

:root[data-theme="dark"] {
  --bp-body: #d6d9de;
  --bp-tick: rgba(242, 243, 245, .3);
}

.bpa {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.bpa__ms {
  margin: 0;
  height: calc(var(--u) * 30);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 16);
  font-family: ui-monospace, Menlo, monospace;
  font-size: max(12px, calc(var(--u) * 12));
