}

.bpa__ml {
  flex: 1;
  height: 1px;
  background: var(--acc);
}

.bpa__hero {
  position: relative;
  height: calc(var(--u) * 860);
  margin-top: calc(var(--u) * 14);
  background: var(--stripes);
}

.bpa__img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 62%;
}

.bpa__tk,
.bpx__tk {
  position: absolute;
  z-index: 1;
  border: 0 solid var(--acc);
}

.bpa__tk {
  width: calc(var(--u) * 24);
  height: calc(var(--u) * 24);
}

.bpa__tk--tl,
.bpx__tk--a {
  left: -1px;
  top: -1px;
  border-left-width: 1px;
  border-top-width: 1px;
}

.bpa__tk--tr {
  right: -1px;
  top: -1px;
  border-right-width: 1px;
  border-top-width: 1px;
}

.bpa__tk--bl {
  left: -1px;
  bottom: -1px;
  border-left-width: 1px;
  border-bottom-width: 1px;
}

.bpa__tk--br,
.bpx__tk--b {
  right: -1px;
  bottom: -1px;
  border-right-width: 1px;
