.bpa__fc {
  padding: calc(var(--u) * 20) calc(var(--u) * 24);
  border-right: .5px solid var(--line2);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
}

.bpa__fc dt {
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.98);
  color: var(--mute);
}

.bpa__fc dd {
  margin: 0;
  font-size: max(12px, calc(var(--u) * 19));
  font-weight: 300;
}

.bpa__cols {
  padding-top: calc(var(--u) * 80);
  display: grid;
  grid-template-columns: calc(var(--u) * 300) minmax(0, 1fr) calc(var(--u) * 260);
  gap: calc(var(--u) * 60);
  align-items: start;
}

/* the rail: tick ruler, progress line, contents, gauge, share */
.bprail {
  position: sticky;
  top: 20px;
  padding-left: calc(var(--u) * 22);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 30);
}

.bprail__ticks {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: calc(var(--u) * 10);
  background: repeating-linear-gradient(180deg, var(--bp-tick) 0 1px, transparent 1px calc(var(--u) * 20));
}

.bprail__prog {
  position: absolute;
  left: 0;
  top: 0;
  width: 2px;
  height: 25%;
  background: var(--acc);
  transition: height .6s var(--pd-ease);
}

.bprail__k {
  margin: 0;
  padding-bottom: calc(var(--u) * 10);
  font-size: max(12px, calc(var(--u) * 11));
  text-transform: uppercase;
