/* == 171. Blog post — tablet and phone ================================= */
@media (max-width: 1599px) {
  /* on the article the sidebar follows the text */
  .bp .blside {
    order: 2;
  }

  .bpa__cols {
    grid-template-columns: 240px minmax(0, 1fr);
  }

  .bpnotes {
    grid-column: 2;
    padding-top: 0;
  }

  .bpn:nth-child(n) {
    margin-bottom: 0;
  }

  .cm__in {
    grid-template-columns: 360px minmax(0, 1fr);
    gap: 48px;
  }
}

@media (max-width: 1199px) {
  .bpa__hero {
    height: auto;
    aspect-ratio: 1960 / 860;
  }

  .bpa__strip {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .bpa__cols {
    padding-top: 40px;
    grid-template-columns: minmax(0, 1fr);
    gap: 32px;
  }

  .bprail {
    position: static;
  }

  .bprail__toc,
  .bprail__g {
    display: none;
  }

  .bpnotes {
    grid-column: auto;
  }

  .bpx__fph {
    height: auto;
    aspect-ratio: 1240 / 640;
  }

  .cm__in {
    grid-template-columns: minmax(0, 1fr);
  }

  .cm__side {
    position: static;
  }
}

@media (max-width: 767px) {
  .bpa__ms {
    font-size: 12px;
    white-space: normal;
  }

  .bpa__ml,
  .bpa__mt {
    display: none;
  }

  .bpa__n {
    left: 16px;
    bottom: 12px;
    font-size: 72px;
  }

  .bpa__strip {
    grid-template-columns: 1fr 1fr;
  }

  .bpx {
    gap: 22px;
  }

  .bpx__t {
    font-size: 40px;
  }

  .bpx__dek {
    font-size: 19px;
  }

  .bpx__lead {
    font-size: 19px;
    gap: 12px;
  }

  .bpx__cap {
    font-size: 64px;
  }

  .bpx__p {
    font-size: 18px;
  }

  .bpx__ha {
    gap: 12px;
  }

  .bpx__hn {
    font-size: 32px;
  }

  .bpx__ht {
    font-size: 28px;
  }

  .bpx__q {
    padding: 26px 22px;
  }

  .bpx__qt p {
    font-size: 26px;
  }

  .bpx__sg {
    grid-template-columns: 1fr 1fr;
  }

  .bpx__pn {
    grid-template-columns: minmax(0, 1fr);
  }

  .bpx__pv {
    border-right: 0;
    border-bottom: .5px solid var(--line2);
  }

  .cm__n {
    font-size: 88px;
  }

  .cm__w {
    font-size: 36px;
  }

  .cmf__more {
    padding-left: 0;
  }

  .cmf__in,
  .cmf__in:not(.cmf__in--name) {
    width: 100%;
  }

  .cmf__cnt,
  .cmf__post {
    margin-left: 0;
  }

  .cmc {
    grid-template-columns: 44px minmax(0, 1fr);
    gap: 14px;
  }

  .cmc .cmav {
    width: 40px;
    height: 40px;
  }

  .cmc__t {
    font-size: 18px;
  }

  .cmr__i {
    padding: 16px;
    grid-template-columns: 36px minmax(0, 1fr);
    gap: 12px;
  }

  .cmav--s {
    width: 36px;
    height: 36px;
  }

  .cmr__t {
    font-size: 16px;
  }
