  --up-plus: #111418;
  --up-plus-bd: rgba(17, 20, 24, .16);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --up-ln: rgba(242, 243, 245, .08);
    --up-ln2: rgba(242, 243, 245, .2);
    --up-off: rgba(242, 243, 245, .1);
    --up-tile: #25292f;
    --up-plus: #22262c;
    --up-plus-bd: rgba(242, 243, 245, .14);
  }
}

:root[data-theme="dark"] {
  --up-ln: rgba(242, 243, 245, .08);
  --up-ln2: rgba(242, 243, 245, .2);
  --up-off: rgba(242, 243, 245, .1);
  --up-tile: #25292f;
  --up-plus: #22262c;
  --up-plus-bd: rgba(242, 243, 245, .14);
}

