  right: calc(var(--u) * 16);
  top: calc(var(--u) * 14);
  height: calc(var(--u) * 26);
  padding: 0 calc(var(--u) * 10);
  border-radius: calc(var(--u) * 13);
  background: rgba(47, 163, 107, .12);
  color: var(--pd-ok);
  display: flex;
  align-items: center;
  font-size: max(12px, calc(var(--u) * 14));
}

.upf__in {
  width: 100%;
  height: calc(var(--u) * 32);
  padding: 0;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: max(12px, calc(var(--u) * 19));
  font-weight: 300;
}

.upf__in::placeholder {
  color: var(--mute);
