  color: var(--acc);
}

.upf:focus-within,
.upf.is-err {
  border-color: var(--acc);
}

.upf:focus-within .upf__l,
.upf.is-err .upf__l {
  color: var(--acc);
}

/* sticky save bar */
.upbar {
  position: sticky;
  bottom: 20px;
  z-index: 2;
  padding: calc(var(--u) * 12) calc(var(--u) * 12) calc(var(--u) * 12) calc(var(--u) * 28);
  border: .5px solid var(--up-ln2);
  border-radius: calc(var(--u) * 40);
  background: var(--surf);
  box-shadow: 0 20px 50px rgba(17, 20, 24, .12);
  color: var(--mute);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
  transition: background .35s, color .35s;
}

.upbar.is-dirty {
  background: var(--ink);
  color: var(--pd-inv);
}

.upbar__t {
  margin: 0;
  font-size: max(12px, calc(var(--u) * 16));
}

.upbar__x,
.upbar__s {
  height: calc(var(--u) * 56);
  border-radius: calc(var(--u) * 28);
  font-size: max(12px, calc(var(--u) * 14));
  text-transform: uppercase;
  letter-spacing: calc(var(--u) * 1.96);
  white-space: nowrap;
}

.upbar__x {
  margin-left: auto;
  padding: 0 calc(var(--u) * 24);
  border: .5px solid rgba(128, 132, 140, .5);
  color: inherit;
}

.upbar__x:disabled {
  opacity: .4;
  cursor: default;
}

.upbar__s {
  padding: 0 calc(var(--u) * 30);
  background: var(--mute);
  color: #fff;
  transition: background .3s;
}

.upbar.is-dirty .upbar__s {
  background: var(--acc);
}

.upbar.is-saved .upbar__s {
  background: var(--pd-ok);
}

