}

.sdcmp__h {
  margin-bottom: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.sdcmp__t {
  margin: 0;
  font-size: 40px;
  font-weight: 300;
  letter-spacing: -.03em;
}

.sdcmp__x {
  width: 44px;
  height: 44px;
  border: .5px solid var(--up-ln2);
  border-radius: 50%;
  font-size: 20px;
}

.sdcmp__b {
  overflow-x: auto;
}

.sdcmp__tb {
  width: 100%;
  border-collapse: collapse;
  font-size: 15px;
}

.sdcmp__tb th,
.sdcmp__tb td {
  padding: 12px 14px;
  border-top: .5px solid var(--up-ln2);
  text-align: left;
  vertical-align: top;
}

.sdcmp__tb th {
  width: 140px;
  font-family: ui-monospace, Menlo, monospace;
  font-size: 12px;
  font-weight: 400;
  color: var(--mute);
}

.sdcmp__img {
  display: block;
  width: 100%;
  max-width: 260px;
  height: auto;
  margin-bottom: 8px;
}

.sdcmp__n {
  font-size: 18px;
}

.sd__toast {
  position: fixed;
  left: 50%;
  bottom: 30px;
  z-index: 60;
  max-width: calc(100vw - 32px);
  margin: 0;
  padding: 14px 20px;
  background: #111418;
  color: #f2f3f5;
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 14px;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 20px);
  transition: opacity .3s, transform .3s;
}

.sd__toast.is-on {
  opacity: 1;
  pointer-events: auto;
  transform: translate(-50%, 0);
}

.sd__undo {
