/* == 181. Account · Saved cars — tablet and phone ====================== */
@media (max-width: 1599px) {
  .sdks,
  .sdgrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sdqs__ul {
    grid-template-columns: minmax(0, 1fr);
  }

  .sdss {
    margin-left: 0;
  }
}

@media (max-width: 767px) {
  /* the site's .5px phone unit makes 26 px pills; the page gets a finger-sized scale */
  .sd {
    --u: .8px;
  }

  .sdks {
    gap: 10px;
  }

  .sdk {
    padding: 16px;
  }

  .sdk__v {
    font-size: 32px;
  }

  .sdgrid {
    grid-template-columns: minmax(0, 1fr);
  }

  .sdalert {
    flex-wrap: wrap;
    padding: 14px 16px;
  }

  .sdalert__t {
    flex-basis: calc(100% - 52px);
  }

  .sdalert__go {
    width: 100%;
  }

  .sdss {
    max-width: 100%;
    overflow-x: auto;
  }

  .sdqs {
    padding: 20px 18px;
  }

  .sdqs__h {
    flex-direction: column;
    gap: 12px;
  }

  .sdcmp {
    padding: 22px 16px;
  }
}

