/* == 185. Account · My listings — tablet and phone ===================== */
@media (max-width: 1999px) {
  .mlg3 {
    grid-template-columns: calc(var(--u) * 340) minmax(0, 1fr);
  }

  .mlr {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1599px) {
  .mlks {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mlstrip {
    flex-direction: column;
    align-items: stretch;
    padding: calc(var(--u) * 14);
    border-radius: calc(var(--u) * 24);
  }

  .mlstrip__a {
    justify-content: flex-start;
  }
}

@media (max-width: 1199px) {
  .mlg3 {
    grid-template-columns: minmax(0, 1fr);
  }

  .mlt__ph {
    min-height: 0;
    aspect-ratio: 3 / 2;
  }
}

@media (max-width: 767px) {
  /* the site's .5px phone unit makes 25 px buttons; the page gets a finger-sized scale */
  .mlw {
    --u: .8px;
  }

  .mlks {
    gap: 10px;
  }

  .mlk {
    padding: 16px;
  }

  .mlk__v {
    font-size: 32px;
  }

  .mlsell {
    margin-left: 0;
  }

  .ml {
    padding: 10px;
  }

  .mlt__b {
    padding: 4px 6px;
  }

  .mlt__t {
    font-size: 24px;
  }

  .mls {
    grid-template-columns: 1fr 1fr;
  }

  .mlo__top {
    flex-wrap: wrap;
  }

  .mlo__amt {
    width: 100%;
    margin-left: 52px;
    align-items: flex-start;
  }

  .mlstrip__a .mla {
    flex: 1 1 auto;
    justify-content: center;
  }
}

