    display: none;
  }

  .uor__tt {
    grid-column: 1 / -1;
    order: 3;
  }

  .uost {
    order: 2;
  }

  .uor__tot {
    order: 4;
    text-align: left;
  }

  .uor__chev {
    order: 5;
  }

  .uor__cols {
    grid-template-columns: minmax(0, 1fr);
  }

  .uorm {
    grid-template-columns: minmax(0, 1fr);
    gap: 14px;
