  /* the site's .5px phone unit makes 25 px pills; the page gets a finger-sized scale */
  .uo {
    --u: .8px;
  }

  .uoact,
  .uoret {
    padding: 12px;
  }

  .uoact__t {
    font-size: 26px;
  }

  .uoact__date {
    font-size: 30px;
  }

  .uosps {
    padding: 4px 0 8px;
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .uosp {
    display: grid;
    grid-template-columns: 36px minmax(0, 1fr) auto;
    align-items: center;
    gap: 12px;
  }

  .uosp__ln {
    display: none;
  }

  .uor__h {
    padding: 14px;
  }

  .uor__cols {
    padding: 0 12px;
  }

  .uoc {
    padding: 16px;
  }

  .uoi {
    grid-template-columns: minmax(0, 1fr) auto auto;
  }

  .uoacts {
    padding: 12px;
  }

  .uoa {
    flex: 1 1 auto;
    justify-content: center;
  }

  .uorm__ul {
    grid-template-columns: 1fr 1fr;
    gap: 10px 8px;
  }
}

