}

/* == 197. Account · Trade-in — tablet and phone ======================== */
@media (max-width: 1999px) {
  .txo__g {
    grid-template-columns: calc(var(--u) * 280) minmax(0, 1fr);
  }

  .txo__of {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1599px) {
  .txo__r {
    grid-template-columns: minmax(0, 1fr);
  }

  .txr {
    grid-template-columns: 120px minmax(0, 1fr) auto;
    gap: 12px 18px;
  }

  .txr__ph {
    grid-row: span 2;
  }

  .txr__tt {
    grid-column: 2 / -1;
  }

  .txr__mine {
    grid-column: 2;
  }

  .txst {
    grid-column: 3;
    grid-row: 2;
    align-self: start;
  }

  .txr__ask {
    grid-column: 2 / -1;
  }

  .txr__acts {
    grid-column: 1 / -1;
    justify-content: flex-start;
  }
}

@media (max-width: 1199px) {
  .txo__g {
    grid-template-columns: minmax(0, 1fr);
  }

  .txo__ph {
    min-height: 0;
    aspect-ratio: 3 / 2;
  }

  .txsps {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 18px;
  }
}

@media (max-width: 767px) {
  /* the site's .5px phone unit makes 27 px buttons here; controls need a finger-sized scale */
  .tx {
    --u: .8px;
  }

  .txo {
    padding: 10px;
  }

  .txo__of,
  .txc {
    padding: 18px 16px;
  }

  .txo__t {
    font-size: 28px;
  }

  .txo__v {
    font-size: 44px;
  }

  .txcms {
    grid-template-columns: minmax(0, 1fr);
  }

  .txo__btns {
    grid-template-columns: minmax(0, 1fr);
  }

  .txca {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 6px 12px;
  }

  .txca__bar {
    grid-column: 1 / -1;
    grid-row: 2;
  }

  .txsps {
    padding: 4px 0 8px;
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .txsp {
    display: grid;
    grid-template-columns: 36px minmax(0, 1fr) auto;
    align-items: center;
    gap: 12px;
  }

  .txsp__ln {
    display: none;
  }

  .txslots {
    padding: 14px 16px;
    border-radius: 22px;
  }

  .txof {
    padding: 18px 16px;
  }

  .txof__hd {
    flex-direction: column;
    gap: 6px;
  }

  .txr {
    padding: 12px;
    grid-template-columns: 90px minmax(0, 1fr);
  }

  .txr__ph {
    width: 90px;
    height: 60px;
    grid-row: auto;
  }

  .txr__tt {
    grid-column: 2;
  }

  .txr__mine,
  .txr__ask {
    grid-column: 1 / -1;
  }

  .txst {
    grid-column: 1 / -1;
    grid-row: auto;
  }

  .txr__acts .txa {
    flex: 1 1 auto;
    justify-content: center;
  }
}

