/* == 201. Account · Messages — tablet and phone ======================== */
@media (max-width: 1999px) {
  .ms {
    grid-template-columns: calc(var(--u) * 440) minmax(0, 1fr);
  }

  .mst__h {
    flex-wrap: wrap;
  }

  .mst__acts {
    width: 100%;
    margin-left: 0;
    justify-content: flex-start;
  }
}

@media (max-width: 1199px) {
  .ms {
    grid-template-columns: minmax(0, 1fr);
  }

  .mslist {
    height: auto;
    max-height: 560px;
  }

  .mspane {
    height: 760px;
  }
}

@media (max-width: 767px) {
  /* the site's .5px phone unit makes 24 px pills; the inbox gets a finger-sized scale */
  .ms {
    --u: .8px;
  }

  .mslist {
    padding: 12px;
  }

  .mspane {
    height: 90vh;
    min-height: 640px;
  }

  .mst__car {
    padding: 8px;
  }

  .mst__ph {
    height: 48px;
  }

  .mst__h,
  .mst__msgs,
  .mscomp {
    padding-left: 14px;
    padding-right: 14px;
  }

  .mst__car {
    margin: 10px 14px 0;
    grid-template-columns: 72px minmax(0, 1fr);
  }

  .mst__pr {
    grid-column: 2;
    padding: 0;
    font-size: 17px;
  }

  .msb {
    max-width: 86%;
  }

  .msof,
  .mstd,
  .msdl {
    width: 100%;
  }

  .msdl__ul {
    grid-template-columns: 1fr 1fr;
    gap: 10px 6px;
  }

  .mscomp__q {
    flex-wrap: nowrap;
    overflow-x: auto;
  }

  .mstyping {
    margin: 0 14px 10px;
  }
}

