/* == 205. Account · Payment methods — tablet and phone ================= */
@media (max-width: 1999px) {
  .pmms {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .pmmid {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .pmfin {
    grid-column: 1 / -1;
  }

  .pmh {
    grid-template-columns: calc(var(--u) * 110) calc(var(--u) * 56) minmax(0, 1fr) auto auto;
  }

  .pmh__via {
    display: none;
  }

  .pmh__rc {
    grid-column: 5;
  }
}

@media (max-width: 1599px) {
  .pmms {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pmfs {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .pmh {
    grid-template-columns: calc(var(--u) * 56) minmax(0, 1fr) auto;
    gap: 8px 14px;
  }

  .pmh__d {
    grid-column: 2;
    grid-row: 2;
    font-size: max(12px, calc(var(--u) * 14));
  }

  .pmh__i {
    grid-row: span 2;
  }

  .pmst {
    grid-column: 3;
    grid-row: 2;
    justify-self: end;
  }

  .pmh__amt {
    grid-column: 3;
    grid-row: 1;
  }

  .pmh__rc {
    grid-column: 1 / -1;
    justify-self: start;
  }
}

@media (max-width: 1199px) {
  .pmmid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 767px) {
  /* the site's .5px phone unit makes 22 px buttons; the wallet gets a finger-sized scale */
  .pm {
    --u: .8px;
  }

  .pmms {
    grid-template-columns: minmax(0, 1fr);
  }

  .pmc,
  .pmnew {
    height: 200px;
  }

  .pmfs {
    grid-template-columns: minmax(0, 1fr);
  }

  .pmadd,
  .pmfin,
  .pmcard,
  .pmhist {
    padding: 18px 16px;
  }

  .pmfin__n {
    font-size: 36px;
  }

  .pmfin__fs {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .pmhist .pmseg {
    max-width: 100%;
    overflow-x: auto;
  }

  .pmh {
    grid-template-columns: 44px minmax(0, 1fr);
  }

  .pmh__i {
    width: 44px;
    height: 44px;
  }

  .pmh__amt,
  .pmst {
    grid-column: 2;
    grid-row: auto;
    justify-self: start;
    text-align: left;
  }
}

