  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.nxct {
  padding: calc(var(--u) * 14) calc(var(--u) * 16);
  border-radius: calc(var(--u) * 22);
  background: var(--bg);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
}

.nxct__b,
.nxdev__b {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 2);
}

.nxct__k {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

.nxct__v {
