}

.nxdev {
  padding: calc(var(--u) * 12) calc(var(--u) * 12) calc(var(--u) * 12) calc(var(--u) * 16);
  border-radius: calc(var(--u) * 22);
  background: var(--bg);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 14);
}

.nxdev[hidden] {
  display: none;
}

.nxdev__i {
  flex-shrink: 0;
  width: calc(var(--u) * 44);
  height: calc(var(--u) * 44);
  border-radius: calc(var(--u) * 14);
  background: var(--surf);
  display: flex;
  align-items: center;
  justify-content: center;
}

.nxdev__t {
  font-size: max(12px, calc(var(--u) * 16));
}

.nxdev__d {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--mute);
}

.nxdev__rm {
  height: calc(var(--u) * 38);
  padding: 0 calc(var(--u) * 14);
  border-radius: calc(var(--u) * 19);
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.nxdev__rm:hover {
  color: var(--acc);
}

.nxtest {
  align-self: flex-start;
  height: calc(var(--u) * 46);
  padding: 0 calc(var(--u) * 18);
  border: 1px solid var(--up-ln2);
  border-radius: calc(var(--u) * 23);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 15));
  white-space: nowrap;
  transition: background .2s, border-color .2s, color .2s;
}

.nxtest:hover:not(:disabled) {
  border-color: var(--acc);
  color: var(--acc);
}

.nxtest:disabled {
  border-color: var(--pd-ok);
  background: rgba(47, 163, 107, .12);
  color: var(--pd-ok);
  cursor: default;
}

/* == 208. Account · Notifications — tablet and phone =================== */
@media (max-width: 1999px) {
  .nxset {
    grid-template-columns: minmax(0, 1fr);
  }

  .nxside {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    align-items: start;
  }

  .nxside > .nxcard:last-child {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1599px) {
  .nxa {
    grid-template-columns: calc(var(--u) * 56) minmax(0, 1fr) auto calc(var(--u) * 44);
  }

  .nxa__ph {
    display: none;
  }

  .nxside {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 767px) {
  /* the site's .5px phone unit makes 23 px pills; the page gets a finger-sized scale */
  .nx {
    --u: .8px;
  }

  .nxfeed,
  .nxcard {
    padding: 16px 14px;
  }

  .nxfeed__all {
    margin-left: 0;
  }

  .nxa {
    padding: 12px;
    grid-template-columns: 44px minmax(0, 1fr) 36px;
    gap: 10px 12px;
  }

  .nxa__i {
    width: 44px;
    height: 44px;
  }

  .nxa__r {
    grid-column: 2 / -1;
    grid-row: 2;
    flex-direction: row-reverse;
    justify-content: flex-end;
    align-items: center;
    gap: 12px;
  }

  .nxa__x {
    grid-column: 3;
    grid-row: 1;
    width: 36px;
    height: 36px;
  }

  .nxmx__h {
    grid-template-columns: minmax(0, 1fr) repeat(3, 52px);
    gap: 6px;
  }

  .nxmx__r {
    padding: 12px;
    grid-template-columns: minmax(0, 1fr) repeat(3, 52px);
    gap: 6px;
  }

  .nxmx__c {
    font-size: 14px;
  }

  .nxq,
  .nxpause {
    flex-direction: column;
    align-items: flex-start;
  }
}

/* == 209. Account · Security — score ==================================== */
.sx {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 20);
}

.sxchks,
.sxpks,
.sxdevs,
.sxlist,
.sxevs,
.sxcodes__ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.sxscore {
  --lv: var(--gr-amber);
  --lvt: #f0b54a;
  padding: calc(var(--u) * 28) calc(var(--u) * 30);
  border-radius: calc(var(--u) * 32);
  background: var(--up-plus);
  color: #fff;
  display: grid;
  grid-template-columns: calc(var(--u) * 150) minmax(0, 1fr) auto;
  gap: calc(var(--u) * 30);
  align-items: center;
}

.sxscore.is-strong {
  --lv: var(--pd-ok);
  --lvt: #5fd39b;
}

.sxscore.is-weak {
  --lv: var(--acc);
  --lvt: #ff8a5c;
}

.sxring {
  --p: 60%;
  width: calc(var(--u) * 150);
  height: calc(var(--u) * 150);
  border-radius: 50%;
  background: conic-gradient(var(--lv) 0 var(--p), rgba(128, 132, 140, .25) var(--p) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.sxring__in {
  width: calc(var(--u) * 122);
  height: calc(var(--u) * 122);
  border-radius: 50%;
  background: var(--up-plus);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: calc(var(--u) * 2);
}

.sxring__n {
  font-size: max(12px, calc(var(--u) * 40));
  font-weight: 300;
  line-height: 1;
}

.sxring__of {
  font-size: max(12px, calc(var(--u) * 20));
  color: #a3a9b3;
}

.sxring__l {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--lvt);
}

.sxscore__b {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.sxscore__t {
  margin: 0;
  font-size: max(12px, calc(var(--u) * 28));
  font-weight: 300;
}

.sxchks {
  display: flex;
  flex-wrap: wrap;
  gap: calc(var(--u) * 8);
}

.sxchk {
  height: calc(var(--u) * 38);
  padding: 0 calc(var(--u) * 14);
  border-radius: calc(var(--u) * 19);
  background: rgba(216, 71, 14, .18);
  color: #ffb08f;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 8);
  font-size: max(12px, calc(var(--u) * 14));
  white-space: nowrap;
}

.sxchk__m {
  width: calc(var(--u) * 20);
  height: calc(var(--u) * 20);
  border-radius: 50%;
  background: var(--acc);
