}

.sxscore__go {
  height: calc(var(--u) * 56);
  padding: 0 calc(var(--u) * 18);
  border-radius: calc(var(--u) * 28);
  background: var(--acc);
  color: #fff;
  font-size: max(12px, calc(var(--u) * 16));
  white-space: nowrap;
}

.sxscore__go:hover {
  filter: brightness(1.08);
}

.sxscore__go[hidden] {
  display: none;
}

/* == 210. Account · Security — cards, rows, controls =================== */
