/* == 218. Sell my car — tablet and phone =============================== */
@media (max-width: 1999px) {
  .wzbar {
    grid-template-columns: repeat(7, minmax(0, auto));
    overflow-x: auto;
  }

  .wzst {
    padding-right: calc(var(--u) * 14);
  }

  .wzgrid {
    grid-template-columns: minmax(0, 1fr) calc(var(--u) * 360);
  }

  .wzslots {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

@media (max-width: 1599px) {
  .wzgrid {
    grid-template-columns: minmax(0, 1fr);
  }

  .wzside {
    position: static;
  }
}

@media (max-width: 767px) {
  /* the site's .5px phone unit makes 25 px buttons; the wizard gets a finger-sized scale */
  .wz {
    --u: .8px;
  }

  .wzform {
    padding: 18px 14px;
  }

  .wzform__q {
    font-size: 24px;
  }

  .wzst__t {
    display: none;
  }

  .wzst.is-cur .wzst__t {
    display: inline;
  }

  .wzpaths,
  .wzcars,
  .wzpair,
  .wzspec {
    grid-template-columns: minmax(0, 1fr);
  }

  .wzpane[data-s="1"] .wzpair,
  .wzvin,
  .wzsteps,
  .wzph,
  .wzinstant {
    flex-direction: column;
    align-items: stretch;
  }

  .wzdec {
    height: 54px;
  }

  .wzslots {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .wzslot {
    height: 80px;
  }

  .wzbox--row {
    padding: 14px;
  }

  .wznav {
    flex-wrap: wrap;
  }

  .wznav__hint {
    order: 3;
    width: 100%;
  }

  .wznav .wzbtn--acc {
    margin-left: auto;
  }
}

