/* == 224. Dealer — tablet and phone ==================================== */
@media (max-width: 1999px) {
  .dbkpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .dbhero {
    grid-column: span 3;
  }

  .dbhi {
    grid-template-columns: minmax(0, 1fr);
  }

  .dbhi__r {
    flex-wrap: wrap;
  }

  .dbl {
    grid-template-columns: calc(var(--u) * 52) minmax(0, 1fr) auto auto;
    gap: 10px 14px;
  }

  .dbl__src {
    display: none;
  }

  .dbl__a {
    grid-column: 2 / -1;
  }
}

@media (max-width: 1599px) {
  .dbgrid {
    grid-template-columns: minmax(0, 1fr);
  }

  .dbkpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dbhero {
    grid-column: span 2;
  }

  .dbt {
    grid-template-columns: calc(var(--u) * 56) minmax(0, 1fr);
  }

  .dbt__a {
    grid-column: 2;
  }
}

@media (max-width: 1199px) {
  .dl {
    grid-template-columns: minmax(0, 1fr);
    gap: 32px;
  }

  .dlside {
    position: relative;
    top: auto;
  }

  .dlg__ul {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  }
}

@media (max-width: 767px) {
  /* the site's .5px phone unit makes 27 px rows; the dealer shell and dashboard get a finger-sized scale */
  .dl {
    --u: .8px;
  }

  .dlcard,
  .dbhi,
  .dbcard {
    padding: 16px 14px;
  }

  .dbhi__l {
    flex-direction: column;
    align-items: flex-start;
    gap: 14px;
  }

  .dbhi__t {
    font-size: 30px;
  }

  .dbkpis {
    gap: 12px;
  }

  .dbk {
    padding: 16px 14px;
  }

  .dbhero__v {
    font-size: 44px;
  }

  .dbcard__h {
    flex-wrap: wrap;
  }

  .dbcard__x {
    flex-wrap: wrap;
  }

  .dbfs {
    grid-template-columns: 1fr 1fr;
  }

  .dbf:first-child {
    grid-column: 1 / -1;
  }

  .dbt {
    grid-template-columns: 44px minmax(0, 1fr);
    gap: 12px;
  }

  .dbt__i {
    width: 44px;
    height: 44px;
  }

  .dbt__a {
    grid-column: 1 / -1;
    justify-content: flex-end;
  }

  .dbev {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .dbev__time {
    grid-column: 1 / -1;
    font-size: 15px;
  }

  .dbl {
    grid-template-columns: 44px auto auto minmax(0, 1fr);
    gap: 10px;
  }

  .dbl__b {
    grid-column: 2 / -1;
  }

  .dbl__src + .dbpill {
    grid-column: 2;
  }

  .dbpill + .dbpill {
    grid-column: 3;
  }

  .dbl__av {
    width: 44px;
    height: 44px;
  }

  .dbl__a {
    grid-column: 4;
    justify-content: flex-end;
  }

  .dbage__ls {
    grid-template-columns: 1fr 1fr;
  }

  .dbprog__bar {
    width: 100px;
  }
}

