}

/* == 228. Dealer · Leads — tablet and phone ============================= */
@media (max-width: 1999px) {
  .lqkpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .lqkx {
    grid-column: 1 / -1;
    flex-direction: row;
  }

  .lqkx__add,
  .lqkx__exp {
    height: calc(var(--u) * 52);
  }

  .lqgrid {
    grid-template-columns: minmax(0, 1fr);
  }

  .lf {
    position: relative;
    top: auto;
  }
}

@media (max-width: 1599px) {
  .lqr {
    grid-template-columns: calc(var(--u) * 28) calc(var(--u) * 52) minmax(0, 1fr) auto;
  }

  .lqr__car,
  .lqr__w {
    grid-column: 3 / -1;
  }

  .lqr__st {
    grid-column: 3;
  }

  .lqr__a {
    grid-column: 4;
  }
}

@media (max-width: 767px) {
  .lq {
    --u: .8px;
  }

  .lqkpis {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }

  .lqk {
    padding: 14px 16px;
  }

  .lqsla {
    flex-wrap: wrap;
  }

  .lqsla__b {
    flex-basis: calc(100% - 140px);
    padding-left: 10px;
  }

  .lqsla__go {
    width: 100%;
  }

  .lqsearch {
    min-width: 0;
    max-width: none;
    flex-basis: 100%;
    margin-left: 0;
  }

  .lqf__src {
    flex-wrap: nowrap;
    overflow-x: auto;
    max-width: 100%;
    scrollbar-width: none;
  }

  .lqseg {
    margin-left: 0;
  }

  .lqbulk {
    flex-wrap: wrap;
    padding: 10px;
  }

  .lqbulk__t {
    flex-basis: calc(100% - 52px);
    padding-left: 8px;
  }

  .lqg {
    padding: 8px;
  }

  .lqg__s {
    display: none;
  }

  .lqr {
    grid-template-columns: 26px 44px minmax(0, 1fr);
    gap: 10px;
    padding: 12px;
  }

  .lqring {
    width: 44px;
    height: 44px;
  }

  .lqring__n {
    width: 37px;
    height: 37px;
  }

  .lqr__car,
  .lqr__w {
    grid-column: 3;
  }

  .lqr__st {
    grid-column: 1 / 3;
  }

  .lqr__a {
    grid-column: 3;
    justify-content: flex-end;
  }

  .lf {
    padding: 16px 14px;
  }

  .lfhd {
    flex-wrap: wrap;
  }

  .lfrail {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .lfnba {
    flex-wrap: wrap;
  }

  .lfnba__b {
    flex-basis: calc(100% - 60px);
  }

  .lfnba__go {
    width: 100%;
  }

  .lfseg {
    overflow-x: auto;
    scrollbar-width: none;
  }

  .lfcomp {
    height: auto;
    padding: 6px;
    border-radius: 24px;
    flex-wrap: wrap;
  }

  .lfcomp__in {
    flex-basis: 100%;
    height: 44px;
    padding: 0 10px;
  }

  .lfcomp__send {
    margin-left: auto;
  }

  .lffin {
    grid-template-columns: minmax(0, 1fr);
  }

  .lfown {
    flex-wrap: wrap;
  }
}

/* == 229. Dealer · Test drives — KPIs, day bar ========================== */
