  --tb: var(--acc-a10);
}

.tvb--done,
.tvst--done,
.tvleg__sw--done {
  --c: var(--pd-ok);
  --tb: rgba(47, 163, 107, .12);
}

.tvb--noshow,
.tvst--noshow,
.tvleg__sw--noshow {
