  align-items: baseline;
  gap: calc(var(--u) * 8);
}

.tvk__v {
  font-size: max(12px, calc(var(--u) * 38));
  font-weight: 300;
  letter-spacing: -.03em;
  line-height: 1;
}

.tvk__d {
  font-size: max(12px, calc(var(--u) * 14));
  color: var(--pd-ok);
}

.tvkx {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

.tvkx__book,
.tvkx__av {
