/* == 232. Dealer · Test drives — tablet and phone ======================= */
@media (max-width: 1999px) {
  .tvkpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tvkx {
    grid-column: 1 / -1;
    flex-direction: row;
  }

  .tvkx__book,
  .tvkx__av {
    height: calc(var(--u) * 52);
  }

  .tvday {
    flex-wrap: wrap;
  }

  .tvgrid {
    grid-template-columns: minmax(0, 1fr);
  }

  .tvp {
    position: relative;
    top: auto;
  }

  .tvfls {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 767px) {
  .tv {
    --u: .8px;
  }

  .tvkpis {
    gap: 12px;
  }

  .tvk {
    padding: 14px 16px;
  }

  .tvday__t {
    flex: 1;
    min-width: 0;
    font-size: 17px;
  }

  .tvday__sp {
    display: none;
  }

  /* four columns of drives need room: the calendar scrolls sideways inside its card */
  .tvcal {
    padding: 12px;
    overflow-x: auto;
  }

  .tvcal__in {
    min-width: 640px;
  }

  .tvp {
    padding: 16px 14px;
  }

  .tvcust {
    flex-wrap: wrap;
  }

  .tvroute {
    flex-wrap: wrap;
  }

  .tvprep__g,
  .tvwhere {
    grid-template-columns: minmax(0, 1fr);
  }

  .tvbtn {
    flex-basis: 100%;
  }

  .tvfleet__h {
    flex-direction: column;
  }

  .tvfls {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

