/* == 249. Dealer · Trade-ins — tablet and phone ========================= */
@media (max-width: 1999px) {
  .tzkpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tzkx {
    grid-column: 1 / -1;
    flex-direction: row;
  }

  .tzkx__add,
  .tzkx__cal {
    height: calc(var(--u) * 52);
  }

  .tzq {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .tzdesk {
    grid-template-columns: minmax(0, 1fr);
  }

  .tzbar2 {
    flex-wrap: wrap;
  }
}

@media (max-width: 767px) {
  .tz {
    --u: .8px;
  }

  .tzkpis {
    gap: 12px;
  }

  .tzk {
    padding: 14px 16px;
  }

  .tzq {
    grid-template-columns: repeat(7, 220px);
    overflow-x: auto;
    padding-bottom: 6px;
  }

  .tzl,
  .tzcard {
    padding: 16px 14px;
  }

  .tzl__hd {
    flex-wrap: wrap;
  }

  .tzl__e {
    flex-basis: 100%;
    margin-left: 0;
  }

  .tzcar {
    flex-direction: column;
    align-items: flex-start;
  }

  .tzcar__img {
    width: 100%;
    height: auto;
    aspect-ratio: 479 / 170;
  }

  .tzcar__n {
    font-size: 26px;
  }

  .tzcalc {
    padding: 14px;
  }

  .tzoff__v {
    font-size: 36px;
  }

  .tztiles,
  .tzstrs,
  .tzrss {
    grid-template-columns: 1fr 1fr;
  }

  .tzphs {
    grid-template-columns: 1fr 1fr;
  }

  .tzrc {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .tzrc__eta {
    grid-column: 1;
    grid-row: 2;
  }

  .tzin {
    flex-wrap: wrap;
  }

  .tzin__b {
    flex-basis: calc(100% - 40px);
  }

  .tzin__c {
    margin-left: 36px;
  }

  .tzin__sw {
    margin-left: auto;
  }

  .tzbar2 {
    padding: 16px;
    gap: 12px;
  }

  .tzwin {
    min-width: 0;
    flex-basis: 100%;
  }

  .tzbar2__sp {
    display: none;
  }

  .tzact {
    flex: 1 1 auto;
    justify-content: center;
  }
}

