/* == 261. Dealer · Reviews — tablet and phone =========================== */
@media (max-width: 1999px) {
  .rzdesk {
    grid-template-columns: calc(var(--u) * 560) minmax(0, 1fr);
  }

  .rzr {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    align-items: start;
  }
}

@media (max-width: 1599px) {
  .rzstrip {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .rzdesk,
  .rzr {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 767px) {
  .rz {
    --u: .8px;
  }

  .rzstrip {
    padding: 16px 14px;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 16px;
  }

  .rzavg,
  .rzhist {
    grid-column: 1 / -1;
  }

  .rzstat {
    padding-left: 10px;
  }

  .rztabs {
    max-width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .rzbar__n {
    flex-basis: 100%;
    margin-left: 0;
  }

  .rzrows {
    max-height: 420px;
    overflow: auto;
  }

  .rzrev,
  .rzcard {
    padding: 16px 14px;
  }

  .rzrev__h {
    flex-wrap: wrap;
  }

  .rzrev__src {
    flex-direction: row;
    align-items: center;
    flex-basis: 100%;
  }

  .rzrev__t {
    font-size: 16px;
  }

  .rzed__f {
    flex-wrap: wrap;
  }

  .rzed__tip {
    flex-basis: 100%;
  }

  .rzai__h {
    flex-wrap: wrap;
  }

  .rzsent {
    min-width: 0;
    flex-basis: 100%;
    align-items: flex-start;
  }

  .rzsent__bar {
    width: 100%;
  }

  .rzai__i {
    grid-template-columns: minmax(0, 1fr);
  }

  .rzai__go {
    justify-self: start;
  }
}

