/* == 265. Dealer · Analytics — tablet and phone ========================= */
@media (max-width: 1999px) {
  .aykpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .aymid,
  .ayrow2,
  .ayrow4 {
    grid-template-columns: minmax(0, 1fr);
  }

  .ayrow3 {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .ayrow3 > .aycard:last-child {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1599px) {
  .aytop {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 767px) {
  .ay {
    --u: .8px;
  }

  .aycard,
  .ayexec {
    padding: 16px 14px;
  }

  .ayper,
  .ayseg {
    max-width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .aybar__sp {
    display: none;
  }

  .ayexec__t {
    font-size: 20px;
  }

  .aygoals {
    grid-template-columns: minmax(0, 1fr);
  }

  .aykpis {
    grid-template-columns: 1fr 1fr;
  }

  .ayrow3 {
    grid-template-columns: minmax(0, 1fr);
  }

  .ay .aylg {
    margin-left: 0;
  }

  .ayfn__r {
    grid-template-columns: 84px minmax(0, 1fr) 54px;
  }

  .ayfn__d {
    display: none;
  }

  .ayfn__c {
    padding-left: 0;
    flex-wrap: wrap;
  }

  .aysrs,
  .aysr--h {
    overflow-x: auto;
  }

  .aysr {
    min-width: 560px;
  }

  .aycard--src {
    overflow-x: auto;
  }

  .aytm {
    grid-template-columns: minmax(0, 1.6fr) repeat(6, minmax(0, 1fr));
    gap: 6px;
    font-size: 13px;
  }

  .aytm__av {
    display: none;
  }

  .ayhm {
    grid-template-columns: 32px repeat(13, minmax(0, 1fr));
    gap: 2px;
  }

  .ayhm__lg {
    flex-wrap: wrap;
  }

  .ayal {
    grid-template-columns: 10px minmax(0, 1fr);
  }

  .ayal__go {
    grid-column: 2;
    justify-self: start;
  }
