  padding: calc(var(--u) * 12) calc(var(--u) * 12) calc(var(--u) * 12) calc(var(--u) * 22);
  border-radius: calc(var(--u) * 26);
  background: var(--ink);
  color: var(--surf);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.tqunsv__dot {
  width: calc(var(--u) * 10);
  height: calc(var(--u) * 10);
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--gr-amber);
}

.tqunsv__t {
  flex: 1;
  font-size: max(12px, calc(var(--u) * 15));
}

.tqunsv__x,
.tqunsv__go {
  height: calc(var(--u) * 40);
  padding: 0 calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
  font-size: max(12px, calc(var(--u) * 14));
  white-space: nowrap;
}

.tqunsv__x {
  border: 1px solid rgba(128, 128, 128, .45);
  color: var(--surf);
}

.tqunsv__go {
  padding: 0 calc(var(--u) * 18);
  background: var(--acc);
  color: #fff;
}

.tqmx {
  min-width: 0;
}

.tqmx__in {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.tqmx__h,
.tqmx__r {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) repeat(6, minmax(0, 1fr));
  align-items: center;
  gap: calc(var(--u) * 8);
}

.tqmx__h {
  padding: 0 calc(var(--u) * 4) calc(var(--u) * 8);
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqmx__c {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--u) * 2);
  text-align: center;
}

.tqmx__ct {
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 15));
}

.tqmx__r {
  padding: calc(var(--u) * 8) calc(var(--u) * 4);
  border-top: .5px solid var(--up-ln2);
}

.tqmx__p {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 2);
}

.tqmx__pt {
  font-size: max(12px, calc(var(--u) * 15));
}

.tqmx__pd {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqcell {
  width: calc(var(--u) * 44);
  height: calc(var(--u) * 30);
  border-radius: calc(var(--u) * 15);
  background: var(--ms-tile);
  color: var(--mute);
  justify-self: center;
  font-size: max(12px, calc(var(--u) * 15));
}

.tqcell.is-on {
  background: rgba(47, 163, 107, .14);
  color: var(--pd-ok);
}

.tqcell.is-lock {
  background: var(--ink);
  color: var(--surf);
  cursor: default;
}

.tqcell.is-hl {
  box-shadow: inset 0 0 0 1.5px var(--ink);
}

.tqcell.is-chg {
  box-shadow: inset 0 0 0 2px var(--gr-amber);
}

.tqmx__n {
  padding-top: calc(var(--u) * 8);
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

/* == 269. Dealer · Team — lead routing ================================== */
.tqrt {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  align-items: start;
  gap: calc(var(--u) * 16);
}

.tqrt__m {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 8);
}

.tqrt__k {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqrt__d {
  color: var(--body);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqrules {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
}

.tqrule {
  padding: calc(var(--u) * 10) calc(var(--u) * 14);
  border-radius: calc(var(--u) * 16);
  background: var(--bg);
  display: grid;
  grid-template-columns: minmax(0, 1fr) calc(var(--u) * 20) auto calc(var(--u) * 48);
  align-items: center;
  gap: calc(var(--u) * 10);
  font-size: max(12px, calc(var(--u) * 15));
}

.tqrule.is-off {
  opacity: .45;
}

.tqrule__ar {
  color: var(--mute);
}

.tqrule__w {
  display: flex;
  gap: calc(var(--u) * 4);
}

.tqsw {
  position: relative;
  width: calc(var(--u) * 44);
  height: calc(var(--u) * 26);
  border-radius: calc(var(--u) * 13);
  background: var(--up-ln2);
}

.tqsw.is-on {
  background: var(--acc);
}

.tqsw__k {
  position: absolute;
  top: calc(var(--u) * 3);
  left: calc(var(--u) * 3);
  width: calc(var(--u) * 20);
  height: calc(var(--u) * 20);
  border-radius: 50%;
  background: var(--surf);
  box-shadow: 0 1px 3px rgba(0, 0, 0, .2);
  transition: left .2s;
}

.tqsw.is-on .tqsw__k {
  left: calc(var(--u) * 21);
}

.tqset {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: calc(var(--u) * 10);
}

.tqset__i {
  padding: calc(var(--u) * 12) calc(var(--u) * 14);
  border-radius: calc(var(--u) * 18);
  background: var(--bg);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
}

.tqset__i--row {
  flex-direction: row;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.tqset__b {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 2);
}

.tqset__k {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqset__v {
  font-size: max(12px, calc(var(--u) * 20));
}

.tqstep {
  width: calc(var(--u) * 34);
  height: calc(var(--u) * 34);
  flex-shrink: 0;
  border: 1px solid var(--up-ln2);
  border-radius: 50%;
  background: var(--surf);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 17));
}

.tqstep:disabled {
  opacity: .4;
  cursor: default;
}

.tqnext {
  padding: calc(var(--u) * 14) calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
  background: var(--acc-a06);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: calc(var(--u) * 12);
}

.tqnext__k {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqnext__n {
  font-size: max(12px, calc(var(--u) * 16));
}

.tqnext__w {
  color: var(--body);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqld {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 16);
}

.tqld__i {
  display: grid;
  grid-template-columns: calc(var(--u) * 40) minmax(0, 1fr) calc(var(--u) * 120);
  align-items: center;
  gap: calc(var(--u) * 12);
}

.tqld__b {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 5);
}

.tqld__h {
  display: flex;
  justify-content: space-between;
  gap: calc(var(--u) * 8);
  font-size: max(12px, calc(var(--u) * 15));
}

.tqld__h span:last-child {
  font-size: max(12px, calc(var(--u) * 14));
}

.tqld__v {
  font-size: max(12px, calc(var(--u) * 15));
  text-align: right;
  white-space: nowrap;
}

.tqsmp {
  display: flex;
  flex-wrap: wrap;
  gap: calc(var(--u) * 8);
}

.tqsmp__b {
  padding: calc(var(--u) * 12) calc(var(--u) * 16);
  border: 1.5px solid var(--up-ln2);
  border-radius: calc(var(--u) * 20);
  background: var(--surf);
  color: var(--ink);
  text-align: left;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: calc(var(--u) * 2);
}

.tqsmp__b.is-on {
  border-color: var(--acc);
  background: var(--acc-a04);
}

.tqsmp__t {
  font-size: max(12px, calc(var(--u) * 15));
}

.tqsmp__m {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqpath {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: calc(var(--u) * 10);
}

.tqpath__s {
  padding: calc(var(--u) * 14) calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
  background: var(--bg);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
}

.tqpath__s.is-end {
  background: var(--acc-a06);
}

.tqpath__k {
  color: var(--mute);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 8);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqpath__i {
  width: calc(var(--u) * 22);
  height: calc(var(--u) * 22);
  border-radius: 50%;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: max(12px, calc(var(--u) * 12));
}

.tqpath__v {
  font-size: max(12px, calc(var(--u) * 16));
}

/* == 270. Dealer · Team — schedule and time off ======================== */
.tqsc {
  display: grid;
  grid-template-columns: minmax(0, 1fr) calc(var(--u) * 440);
  align-items: start;
  gap: calc(var(--u) * 16);
}

.tqsc__w {
  min-width: 0;
}

.tqsc__in {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 16);
}

.tqsg {
  display: grid;
  grid-template-columns: calc(var(--u) * 180) repeat(7, minmax(0, 1fr));
  align-items: center;
  gap: calc(var(--u) * 6);
}

.tqsg--days {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqsg__d {
  text-align: center;
}

.tqsg__m {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.tqsg__n {
  overflow: hidden;
  font-size: max(12px, calc(var(--u) * 15));
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tqsh {
  height: calc(var(--u) * 40);
  border-radius: calc(var(--u) * 12);
  background: var(--acc-a10);
  color: var(--acc);
  font-size: max(12px, calc(var(--u) * 14));
  white-space: nowrap;
}

.tqsh.is-off {
  background: var(--bg);
  color: var(--mute);
}

.tqsg--cov {
  padding-top: calc(var(--u) * 6);
  border-top: .5px solid var(--up-ln2);
}

.tqsg__k {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqsg__c {
  font-size: max(12px, calc(var(--u) * 15));
  text-align: center;
}

.tqsg__dm {
  display: flex;
  justify-content: center;
}

.tqdem {
  height: calc(var(--u) * 26);
  padding: 0 calc(var(--u) * 10);
  border-radius: calc(var(--u) * 14);
  background: rgba(47, 163, 107, .1);
  color: var(--pd-ok);
  display: flex;
  align-items: center;
  font-size: max(12px, calc(var(--u) * 14));
  white-space: nowrap;
}

.tqdem.is-short {
  background: var(--acc-a10);
  color: var(--acc);
}

.tqsc__st {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.tqsc__t {
  flex: 1;
  font-size: max(12px, calc(var(--u) * 14));
}

.tqsc__go {
  height: calc(var(--u) * 40);
  padding: 0 calc(var(--u) * 18);
  border-radius: calc(var(--u) * 20);
  background: var(--acc);
  color: #fff;
  font-size: max(12px, calc(var(--u) * 14));
  white-space: nowrap;
}

.tqto {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 16);
}

.tqto__i {
  padding: calc(var(--u) * 14) calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
  background: var(--bg);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

.tqto__h {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 10);
}

.tqto__b {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 1);
}

.tqto__n {
  font-size: max(12px, calc(var(--u) * 15));
}

.tqto__w {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqto__h .tqpill {
  align-self: center;
}

.tqto__imp {
  font-size: max(12px, calc(var(--u) * 14));
}

.tqto__a {
  display: flex;
  gap: calc(var(--u) * 8);
}

.tqto__ok,
.tqto__no {
  flex: 1;
  height: calc(var(--u) * 40);
  border-radius: calc(var(--u) * 20);
  font-size: max(12px, calc(var(--u) * 14));
}

.tqto__ok {
  background: var(--pd-ok);
  color: #fff;
}

.tqto__no {
  padding: 0 calc(var(--u) * 16);
  border: 1px solid var(--up-ln2);
  background: var(--surf);
  color: var(--ink);
  white-space: nowrap;
}

/* tablet and phone */
@media (max-width: 1999px) {
  .tqtop {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .tqtop__b {
    grid-column: 1 / -1;
    flex-direction: row;
  }

  .tqsc {
    grid-template-columns: minmax(0, 1fr);
  }

  .tqto {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    align-items: start;
  }
}

@media (max-width: 1599px) {
  .tqgrid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .tqroles,
  .tqrt {
    grid-template-columns: minmax(0, 1fr);
  }

  .tqroles__l {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .tqmx,
  .tqsc__w {
    overflow-x: auto;
  }

  .tqmx__in {
    min-width: 720px;
  }

  .tqsc__in {
    min-width: 760px;
  }
}

@media (max-width: 1023px) {
  .tqtop {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tqgrid,
  .tqroles__l {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tqorg__cols {
    grid-template-columns: minmax(0, 1fr);
  }

  .tqorg__hz,
  .tqorg__v--s {
    display: none;
  }

  .tqpath {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .tqto {
    grid-template-columns: minmax(0, 1fr);
  }

  .tqtabs {
    overflow-x: auto;
    scrollbar-width: none;
  }

  .tqtab {
    flex: none;
    padding: 0 18px;
  }
}

@media (max-width: 767px) {
  .tq {
    --u: .8px;
  }

  .tqkpi {
    padding: 14px;
  }

  .tqtop__b {
    flex-direction: column;
  }

  .tqtop__inv,
  .tqtop__exp {
    flex: none;
    height: 44px;
  }

  .tqform {
    padding: 14px;
  }

  .tqform__in {
    flex-basis: 100%;
    min-width: 0;
  }

  .tqform .tqseg {
    max-width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .tqform__go {
    flex: 1;
  }

  .tqbar .tqseg {
    max-width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .tqsearch {
    flex-basis: 100%;
    max-width: none;
  }

  .tqbar__sp {
    display: none;
  }

  .tqgrid,
  .tqroles__l,
  .tqset {
    grid-template-columns: minmax(0, 1fr);
  }

  .tqwork__i {
    padding: 10px;
  }

  .tqcard,
  .tqpro,
  .tqbox,
  .tqorg {
    padding: 16px 14px;
  }

  .tqpro__h {
    flex-wrap: wrap;
  }

  .tqpro__b {
    flex-basis: calc(100% - 80px);
  }

  .tqwk__d li {
    font-size: 12px;
  }

  .tqrole .tqseg {
    overflow-x: auto;
    scrollbar-width: none;
  }

  .tqrole .tqseg__b {
    flex: none;
    padding: 0 12px;
  }

  .tqacts {
    flex-direction: column;
  }

  .tqacts__b {
    flex: none;
  }

  .tqunsv {
    flex-wrap: wrap;
    padding: 12px 14px;
  }

  .tqunsv__t {
    flex-basis: calc(100% - 30px);
  }

  .tqunsv__x,
  .tqunsv__go {
    flex: 1;
  }

  .tqrt .tqseg--lg {
    overflow-x: auto;
    scrollbar-width: none;
  }

  .tqrt .tqseg--lg .tqseg__b {
    flex: none;
    padding: 0 14px;
  }

  .tqrule {
    grid-template-columns: minmax(0, 1fr) auto 48px;
  }

  .tqrule__ar {
    display: none;
  }

  .tqld__i {
    grid-template-columns: 36px minmax(0, 1fr);
  }

  .tqld__v {
    grid-column: 2;
    text-align: left;
  }

  .tqsmp__b {
    flex-basis: 100%;
  }

  .tqpath {
    grid-template-columns: minmax(0, 1fr);
  }

  .tqsc__st {
    flex-direction: column;
    align-items: stretch;
  }
}

/* == 271. Dealer · Profile — tokens, strength hero ===================== */
:root {
  --pz-amt: #8a6200;
  --pz-graph: #1c1f24;
  --pz-graph-t: rgba(28, 31, 36, .08);
  --pz-frame: #111418;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --pz-amt: #e8b64c;
    --pz-graph: #e6e8eb;
    --pz-graph-t: rgba(230, 232, 235, .1);
    --pz-frame: #3a3f47;
  }
}

:root[data-theme="dark"] {
  --pz-amt: #e8b64c;
  --pz-graph: #e6e8eb;
  --pz-graph-t: rgba(230, 232, 235, .1);
  --pz-frame: #3a3f47;
}

.pz {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 20);
  font-weight: 400;
  line-height: normal;
}

.pz p {
  margin: 0;
}

.pzben,
.pzsf,
.pzterms,
.pzmini,
.pzlocs {
  margin: 0;
  padding: 0;
  list-style: none;
}

.pz .pzv--ok {
  color: var(--pd-ok);
}

.pz .pzv--amber {
  color: var(--gr-amber);
}

/* storefront colours are the dealer's own and stay fixed across themes (Graphite flips) */
.pzbr--0 {
  --br: #d8470e;
  --br-t: rgba(216, 71, 14, .1);
}

.pzbr--1 {
  --br: #177a4b;
  --br-t: rgba(23, 122, 75, .1);
}

.pzbr--2 {
  --br: #2450e0;
  --br-t: rgba(36, 80, 224, .1);
}

.pzbr--3 {
  --br: var(--pz-graph);
  --br-t: var(--pz-graph-t);
}

.pzhero {
  padding: calc(var(--u) * 26) calc(var(--u) * 30);
  border-radius: calc(var(--u) * 32);
  background: var(--up-plus);
  color: #fff;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: calc(var(--u) * 30);
}

.pzhero__q {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 4);
}

.pzhero__k {
  color: rgba(255, 255, 255, .6);
  font-size: max(12px, calc(var(--u) * 14));
  letter-spacing: calc(var(--u) * 2.24);
  text-transform: uppercase;
}

.pzhero__v {
  font-size: max(12px, calc(var(--u) * 64));
  font-weight: 300;
  letter-spacing: -.04em;
  line-height: 1;
}

.pzhero__m {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.pzseg {
  display: flex;
  gap: calc(var(--u) * 4);
}

.pzseg__i {
  flex: 1 1 0;
