/* == 275. Dealer · Profile — tablet and phone ========================== */
@media (max-width: 1999px) {
  .pzhero {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .pzhero__a {
    grid-column: 1 / -1;
    width: auto;
  }

  .pzmain {
    grid-template-columns: minmax(0, 1fr);
  }

  .pzpv {
    position: static;
  }
}

@media (max-width: 1599px) {
  .pzins {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }

  .pzcard--up {
    grid-column: 1 / -1;
  }

  .pzgal {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 1023px) {
  .pzins,
  .pzsecs {
    grid-template-columns: minmax(0, 1fr);
  }

  .pzsec.is-open {
    grid-column: auto;
  }

  .pzchg {
    flex-wrap: wrap;
  }

  .pzchg__l {
    flex-basis: 100%;
    order: 3;
  }
}

@media (max-width: 767px) {
  .pz {
    --u: .8px;
  }

  .pzhero {
    padding: 18px 16px;
    grid-template-columns: minmax(0, 1fr);
    gap: 18px;
  }

  .pzseg {
    flex-wrap: wrap;
    row-gap: 10px;
  }

  .pzseg__i {
    flex-basis: calc(33.33% - 3px);
  }

  .pzhero__a {
    flex-direction: column;
  }

  .pzhero__live,
  .pzhero__pub {
    flex: none;
    height: 48px;
  }

  .pzcard,
  .pzsec,
  .pzpv {
    padding: 16px 14px;
  }

  .pzben__i {
    grid-template-columns: 120px minmax(0, 1fr) 40px;
  }

  .pzsec__h {
    flex-wrap: wrap;
  }

  .pzsec__b {
    flex-basis: calc(100% - 50px);
  }

  .pzsec__p {
    margin-left: 48px;
  }

  .pzsec .pzbtn {
    margin-left: auto;
  }

  .pzf3,
  .pzlocs,
  .pzmed,
  .pzsv,
  .pzfc {
    grid-template-columns: minmax(0, 1fr);
  }

  .pzlic {
    flex-wrap: wrap;
  }

  .pzlic__b {
    flex-basis: calc(100% - 42px);
  }

  .pzab__n {
    flex-basis: 100%;
    margin-left: 0;
  }

  .pzhrs {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .pzmini li {
    font-size: 12px;
  }

  .pzmini li span:last-child {
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .pzgal {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pzfc__img {
    height: 120px;
  }

  .pzcm {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .pzcm__r {
    grid-column: 1 / -1;
    padding-left: 0;
  }

  .pzpv__h {
    flex-wrap: wrap;
  }

  .pzpv__k {
    flex-basis: 100%;
  }

  .pzph {
    border-width: 8px;
    border-radius: 36px;
  }

  /* the name wraps on a narrow frame: start it below the cover instead of growing up into it */
  .pzph__id {
    align-items: flex-start;
  }

  .pzph__nm {
    padding: 44px 0 0;
  }
}

