.szpre__d {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.szlog {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

.szlog__i {
  display: grid;
  grid-template-columns: calc(var(--u) * 28) minmax(0, 1fr);
  align-items: start;
  gap: calc(var(--u) * 10);
}

.szlog__av,
.szlog__you {
  width: calc(var(--u) * 28);
  height: calc(var(--u) * 28);
  border-radius: 50%;
}

.szlog__av {
  display: block;
  object-fit: cover;
}

.szlog__you {
  background: var(--acc);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: max(12px, calc(var(--u) * 12));
}

.szlog__b {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 1);
}

.szlog__t {
  font-size: max(12px, calc(var(--u) * 14));
}

.szlog__w {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 12));
}

/* == 283. Dealer · Settings — cards ==================================== */
.szmain {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 16);
}

.szgrid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: start;
  gap: calc(var(--u) * 16);
}

.szcard {
  min-width: 0;
  padding: calc(var(--u) * 24) calc(var(--u) * 26);
  border-radius: calc(var(--u) * 32);
  background: var(--surf);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
  scroll-margin-top: 90px;
}

.szcard__h {
  padding-bottom: calc(var(--u) * 6);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.szcard__i {
  width: calc(var(--u) * 40);
  height: calc(var(--u) * 40);
  border-radius: calc(var(--u) * 13);
  font-size: max(12px, calc(var(--u) * 15));
}

.szcard__b {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 2);
}

.szcard__t {
  font-size: max(12px, calc(var(--u) * 22));
  font-weight: 300;
}

.szcard__d {
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.szmx {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.szmx__h,
.szmx__r {
  display: grid;
  grid-template-columns: minmax(0, 1fr) repeat(4, calc(var(--u) * 72));
  align-items: center;
  gap: calc(var(--u) * 8);
}

.szmx__h {
  padding-bottom: calc(var(--u) * 6);
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.szmx__c {
  text-align: center;
}

.szmx__r {
  padding: calc(var(--u) * 10) 0;
  border-top: .5px solid var(--up-ln2);
}

.szmx__e {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 1);
}

.szmx__e .szrow__t {
  font-size: max(12px, calc(var(--u) * 15));
}

.szcell {
  width: calc(var(--u) * 44);
  height: calc(var(--u) * 30);
  border-radius: calc(var(--u) * 15);
  background: var(--ms-tile);
  color: var(--mute);
  justify-self: center;
  font-size: max(12px, calc(var(--u) * 15));
}

.szcell.is-on {
  background: rgba(47, 163, 107, .14);
  color: var(--pd-ok);
}

.szcell.is-chg {
  box-shadow: inset 0 0 0 2px #c98a12;
}

.szar {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
}

.szar__ta {
  width: 100%;
  min-height: calc(var(--u) * 84);
  padding: calc(var(--u) * 12) calc(var(--u) * 14);
  border: 1px solid var(--up-ln2);
  border-radius: calc(var(--u) * 18);
  background: var(--bg);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 15));
  line-height: 1.5;
  outline: 0;
  resize: vertical;
}

.szar__ta:focus,
.szdz__in:focus {
  border-color: var(--acc);
}

.szints {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: calc(var(--u) * 10);
}

.szint {
  min-width: 0;
  padding: calc(var(--u) * 14);
  border-radius: calc(var(--u) * 20);
  background: var(--bg);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.szint.is-err {
  box-shadow: inset 0 0 0 1.5px var(--acc-a40);
}

.szint__i {
  width: calc(var(--u) * 44);
  height: calc(var(--u) * 44);
  flex-shrink: 0;
  border-radius: calc(var(--u) * 14);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: max(12px, calc(var(--u) * 14));
}

.szint--0 {
  background: #2b2f36;
}

.szint--1 {
  background: var(--ml-blue);
}

.szint--2 {
  background: var(--db-purple);
}

.szint--3 {
  background: var(--body);
}

.szint--4 {
  background: var(--pd-ok);
}

.szint--5 {
  background: var(--gr-amber);
}

.szint__b {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 2);
}

.szint__n {
  font-size: max(12px, calc(var(--u) * 15));
}

.szint__s {
  overflow: hidden;
  color: var(--body);
  font-size: max(12px, calc(var(--u) * 14));
  text-overflow: ellipsis;
  white-space: nowrap;
}

.szint__go {
  height: calc(var(--u) * 36);
  padding: 0 calc(var(--u) * 14);
  border: 1px solid var(--up-ln2);
  border-radius: calc(var(--u) * 18);
  background: var(--surf);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 14));
  white-space: nowrap;
}

.szint__go.is-acc {
  border: 0;
  background: var(--acc);
  color: #fff;
}

.szfeed {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
  gap: calc(var(--u) * 10);
}

.szfeed__i {
  min-width: 0;
  padding: calc(var(--u) * 14) calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
  background: var(--bg);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 6);
  font-size: max(12px, calc(var(--u) * 14));
}

.szfeed__u {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.szfeed__a {
  display: flex;
  gap: calc(var(--u) * 6);
}

.szfa {
  padding: calc(var(--u) * 12) calc(var(--u) * 14);
  border-radius: calc(var(--u) * 18);
  background: var(--acc-a06);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.szfa.is-ok {
  background: rgba(47, 163, 107, .08);
}

.szfa__m {
  width: calc(var(--u) * 28);
  height: calc(var(--u) * 28);
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--acc);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: max(12px, calc(var(--u) * 14));
}

.szfa.is-ok .szfa__m {
  background: var(--pd-ok);
}

.szfa__t {
  flex: 1;
  font-size: max(12px, calc(var(--u) * 15));
}

.szsub {
  padding-top: calc(var(--u) * 6);
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.szsess {
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 12);
}

.szsess__i {
  padding: calc(var(--u) * 10) calc(var(--u) * 14);
  border-radius: calc(var(--u) * 16);
  background: var(--bg);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.szsess__b {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 1);
}

.szsess__t {
  font-size: max(12px, calc(var(--u) * 15));
}

.szips {
  display: flex;
  flex-wrap: wrap;
  gap: calc(var(--u) * 6);
}

.szip {
  height: calc(var(--u) * 34);
  padding: 0 calc(var(--u) * 6) 0 calc(var(--u) * 12);
  border-radius: calc(var(--u) * 14);
  background: var(--bg);
  color: var(--ink);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 6);
  white-space: nowrap;
}

.szip__x {
  width: calc(var(--u) * 22);
  height: calc(var(--u) * 22);
  border-radius: 50%;
  background: var(--surf);
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 14));
}

.szip__x:hover {
  color: var(--acc);
}

.szexp {
  padding: calc(var(--u) * 14) calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
  background: var(--bg);
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.szexp .szrow__t,
.szdz .szrow__t {
  font-size: max(12px, calc(var(--u) * 15));
}

.szexp .szbtn,
.szdz .szbtn {
  height: calc(var(--u) * 40);
  padding: 0 calc(var(--u) * 16);
  border-radius: calc(var(--u) * 20);
}

.szdz {
  margin-top: calc(var(--u) * 6);
  padding: calc(var(--u) * 16) calc(var(--u) * 18);
  border-radius: calc(var(--u) * 22);
  background: var(--acc-a04);
  box-shadow: inset 0 0 0 1px var(--acc-a25);
  display: flex;
  flex-direction: column;
  gap: calc(var(--u) * 10);
}

.szdz__t {
  color: var(--acc);
  font-size: max(12px, calc(var(--u) * 15));
}

.szdz__r,
.szdz__c {
  display: flex;
  align-items: center;
  gap: calc(var(--u) * 12);
}

.szdz__c {
  gap: calc(var(--u) * 10);
}

.szdz__l {
  flex: 1;
  min-width: 0;
  display: flex;
}

.szdz__in {
  width: 100%;
  height: calc(var(--u) * 44);
  padding: 0 calc(var(--u) * 16);
  border: 1px solid var(--acc-a35);
  border-radius: calc(var(--u) * 22);
  background: var(--surf);
  color: var(--ink);
  font-size: max(12px, calc(var(--u) * 15));
  outline: 0;
}

.szdz__go {
  height: calc(var(--u) * 44);
  padding: 0 calc(var(--u) * 18);
  border-radius: calc(var(--u) * 22);
  background: var(--acc);
  color: #fff;
  font-size: max(12px, calc(var(--u) * 14));
  white-space: nowrap;
}

.szdz__go:disabled {
  background: var(--up-ln2);
  cursor: default;
}

.szdz__done {
  color: var(--acc);
  font-size: max(12px, calc(var(--u) * 14));
}

.szempty {
  padding: calc(var(--u) * 40);
  color: var(--mute);
  font-size: max(12px, calc(var(--u) * 16));
  text-align: center;
}

/* == 284. Dealer · Settings — tablet and phone ========================= */
@media (max-width: 1999px) {
  .szgrid {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 1279px) {
  .szlay {
    grid-template-columns: minmax(0, 1fr);
  }

  .szside {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 767px) {
  .sz {
    --u: .8px;
  }

  .szsearch {
    min-width: 0;
    flex-basis: 100%;
    padding: 0 16px;
  }

  .szsearch__n {
    display: none;
  }

  .szjump {
    max-width: 100%;
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .szbar {
    top: 8px;
    padding: 10px 12px;
    flex-wrap: wrap;
  }

  .szbar__l {
    display: none;
  }

  .szbar__t {
    flex: 1;
    min-width: 0;
    white-space: normal;
  }

  .szbar {
    flex-wrap: nowrap;
    gap: 8px;
  }

  .szbar__x,
  .szbar__go {
    padding: 0 12px;
  }

  .szside {
    grid-template-columns: minmax(0, 1fr);
  }

  .szcard,
  .szbox {
    padding: 16px 14px;
  }

  .szcard__h {
    flex-wrap: wrap;
  }

  .szcard__b {
    flex-basis: calc(100% - 54px);
  }

  .szrow {
    flex-wrap: wrap;
  }

  .szrow--tg {
    flex-wrap: nowrap;
  }

  .szseg {
    max-width: 100%;
    overflow-x: auto;
    scrollbar-width: none;
  }

  .szrow .szrow__b {
    flex-basis: 100%;
  }

  .szrow--tg .szrow__b,
  .szexp .szrow__b,
  .szdz .szrow__b {
    flex-basis: auto;
  }

  .szrow .szstep:first-of-type {
    margin-left: auto;
  }

  .szmx__h,
  .szmx__r {
    grid-template-columns: minmax(0, 1fr) repeat(4, 46px);
    gap: 4px;
  }

  .szcell {
    width: 40px;
  }

  .szints,
  .szfeed {
    grid-template-columns: minmax(0, 1fr);
  }

  .szsess__i {
    flex-wrap: wrap;
  }

  .szexp,
  .szdz__r,
  .szdz__c {
    flex-wrap: wrap;
  }

  .szdz__l {
    flex-basis: 100%;
  }
}
